KB.add({"board":"09","title":"古希腊文明与中外史诗","note":"交大2020–2022连续三年在名解里考古希腊：柏拉图、修昔底德陷阱（2020），古希腊城邦制度（2021），三一律、亚里士多德（2022）；2025选择考赫拉克利特与朴素唯物主义，2024名解考《格萨尔王传》。2013–2019还考过《历史》作者、伯罗奔尼撒战争、古希腊文明、希腊神话、寓言、史诗、贺拉斯、特洛伊战争、迈锡尼文明、原始印欧语、荷马史诗、宿命论、二元论、辩证法。这是西方板块里出题最稳定的一块，一级卡要能整段默写。","clusters":[{"cid":"09a","name":"爱琴文明与城邦","line":"希腊文明起于爱琴海：克里特（米诺斯）文明在先，迈锡尼文明继起，特洛伊战争传说即附着于迈锡尼时代，线形文字B是最早的希腊语文字；多利亚人南下后经历“黑暗时代”，前8世纪起城邦兴起，雅典经梭伦、克里斯提尼改革走向民主，到伯里克利时代达到鼎盛，斯巴达则实行军事贵族寡头统治。"},{"cid":"09b","name":"两场战争与两位史家","line":"前5世纪希腊城邦先联合抗击波斯（希波战争，希罗多德《历史》记之），胜后雅典借提洛同盟称霸，与斯巴达领导的伯罗奔尼撒同盟爆发伯罗奔尼撒战争（修昔底德记之），后人由此概括出“修昔底德陷阱”；城邦衰落后马其顿亚历山大东征，开启希腊化时代，亚历山大里亚成为新的学术中心。"},{"cid":"09c","name":"神话与史诗：西方文学的源头","line":"希腊神话以奥林匹斯十二主神和英雄传说为核心，赫西俄德《神谱》整理神的谱系，荷马史诗以特洛伊战争为背景；神话人物沉淀为大量典故（潘多拉的盒子、阿喀琉斯之踵、斯芬克斯之谜），古希腊文化与希伯来文化并称西方文明的“两希”源头。"},{"cid":"09d","name":"古希腊戏剧与文论","line":"戏剧起源于酒神狄俄尼索斯祭祀：悲剧有埃斯库罗斯、索福克勒斯、欧里庇得斯三大家，阿里斯托芬是“喜剧之父”；亚里士多德《诗学》提出模仿说和净化说，古罗马贺拉斯《诗艺》继承发展，后人据《诗学》引申出三一律，17世纪法国古典主义把它定为戏剧规则。"},{"cid":"09e","name":"前苏格拉底哲学：追问万物本原","line":"最早的哲学家追问世界由什么构成：米利都学派泰勒斯说水、阿那克西美尼说气，毕达哥拉斯说数，赫拉克利特说火并提出万物流变的辩证思想，德谟克利特提出原子论；以具体物质为本原的属朴素唯物主义；爱利亚学派讲不变的“存在”，智者学派把目光转向人本身。"},{"cid":"09f","name":"古典三贤与希腊化哲学科学","line":"苏格拉底、柏拉图、亚里士多德师徒三代：苏格拉底述而不作，用“助产术”追问美德；柏拉图写《理想国》，提出理念论和洞穴比喻，创阿卡德米学园；亚里士多德集大成，创形式逻辑。亚历山大之后，斯多葛派与伊壁鸠鲁派转向个人内心安宁，欧几里得、阿基米德、希波克拉底代表希腊的科学与医学。"},{"cid":"09g","name":"古罗马：继承与传播","line":"罗马在军事上征服希腊，在文化上被希腊征服：奥古斯都时代维吉尔、贺拉斯、奥维德并称三大诗人，西塞罗代表拉丁散文，马可·奥勒留以斯多葛哲学写《沉思录》；希腊化时期的《七十子译本》把希伯来圣经译成希腊文，是西方早期大规模翻译活动，拉丁语则成为中世纪欧洲的通用学术语言。"},{"cid":"09h","name":"西方哲学史主线：从中世纪到后现代","line":"古希腊之后，中世纪以教父哲学和经院哲学调和信仰与理性；近代哲学转向认识论，形成英国经验论（培根、洛克、贝克莱、休谟）与大陆唯理论（笛卡尔、斯宾诺莎、莱布尼茨）之争，康德调和二者，经黑格尔辩证法到费尔巴哈唯物主义，合称德国古典哲学；19世纪叔本华、尼采转向非理性，20世纪出现现象学、存在主义（见板块11）、分析哲学、实用主义、精神分析、结构主义与后现代主义。"},{"cid":"09i","name":"中外史诗谱系","line":"史诗分民间史诗与文人史诗：两河流域《吉尔伽美什》是现存最早的史诗之一，荷马史诗与印度两大史诗是古代民间史诗的代表，罗马《埃涅阿斯纪》是文人史诗；中世纪欧洲各民族有《贝奥武甫》《罗兰之歌》《尼伯龙根之歌》《熙德之歌》《伊戈尔远征记》；中国少数民族有《格萨尔王传》《江格尔》《玛纳斯》三大英雄史诗。"}],"entries":[{"id":"c-061","t":"世界四大寓言家","cid":"09c","p":2,"kind":"合称","alias":["四大寓言家","世界四大寓言作家","伊索、拉封丹、克雷洛夫、莱辛"],"one":"伊索、拉封丹、克雷洛夫、莱辛。","ans":"世界四大寓言家指**伊索、拉封丹、克雷洛夫、莱辛**。**伊索**是古希腊寓言作家，相传为奴隶，有《伊索寓言》；**拉封丹**是17世纪法国诗人，有《拉封丹寓言》；**克雷洛夫**是19世纪俄国作家，有《克雷洛夫寓言》；**莱辛**是18世纪德国启蒙思想家，有《寓言三卷》，同时著有《拉奥孔》。寓言用短小的故事讲道理，常以动物为角色。其中伊索、拉封丹、克雷洛夫又被称为**世界三大寓言作家**。","pts":["伊索、拉封丹、克雷洛夫、莱辛","古希腊、法、俄、德四国","三大寓言作家只含前三位"],"members":[["伊索","古希腊，《伊索寓言》"],["拉封丹","法国，《拉封丹寓言》"],["克雷洛夫","俄国，《克雷洛夫寓言》"],["莱辛","德国，《寓言三卷》，另著《拉奥孔》"]],"mem":"国别串联“希法俄德”：伊索（希腊）、拉封丹（法）、克雷洛夫（俄）、莱辛（德）。三大寓言作家去掉最后的莱辛即可。画面：龟兔赛跑（伊索）、狐狸与乌鸦（拉封丹也写）、克雷洛夫写鹰和蚂蚁。","mix":"“三大寓言作家”（伊索、拉封丹、克雷洛夫）与“四大寓言家”（再加莱辛）并存，考试按题干数字区分；中国寓言常见于《庄子》《韩非子》。","mcq":[{"q":"下列作家中，不在“世界三大寓言作家”之列的是","o":["伊索","拉封丹","莱辛","克雷洛夫"],"a":2,"w":"三大寓言作家是伊索、拉封丹、克雷洛夫，莱辛是四大寓言家之一。"}],"rel":[{"t":"伊索","n":"成员"},{"t":"莱辛","n":"成员"},{"t":"世界三大寓言作家","n":"三大与四大之别"},{"t":"庄子名篇与寓言","n":"中国寓言对照"}],"exam":[]},{"id":"b09-001","t":"古希腊文明","cid":"09a","p":1,"kind":"概念","exam":["2017名解","2018名解","2019名解"],"alias":["古希腊","古希腊文化","希腊文明"],"one":"以爱琴海为中心的古代文明，西方文明的主要源头。","ans":"古希腊文明是**以爱琴海为中心，包括希腊半岛、爱琴海诸岛和小亚细亚西岸的古代文明**，是**西方文明的主要源头**。它上承**克里特的米诺斯文明和迈锡尼文明**，经荷马时代，在**古风时期（约前8至前6世纪）形成众多城邦**，**古典时期（前5至前4世纪）以雅典、斯巴达为代表达到鼎盛**。古希腊人在**哲学、史学、戏剧、史诗、数学和民主政治**等方面成就卓著，奥林匹克运动也始于此。**亚历山大东征后进入希腊化时代**，其文化经罗马继承，在文艺复兴中复兴。","pts":["爱琴海为中心，西方文明源头","爱琴文明、城邦、古典鼎盛、希腊化四个阶段","哲学史学戏剧民主等成就，影响后世"],"mem":"四步走时间线：爱琴（克里特、迈锡尼）→ 城邦（前8世纪）→ 古典（前5世纪雅典斯巴达）→ 希腊化（亚历山大之后）。成就用“哲史戏诗数民运”七个字串起：哲学、史学、戏剧、史诗、数学、民主、奥运。2019 年同组名解还有特洛伊战争、迈锡尼文明、荷马史诗，答题时可顺带点到。","mix":"古希腊文明与爱琴文明不同：爱琴文明是前身（米诺斯、迈锡尼），城邦兴起后才算古希腊文明主体；罗马文明是继承者，不等于古希腊。","mcq":[{"q":"下列属于古希腊文明直接前身的是","o":["两河流域文明","爱琴文明","古埃及文明","腓尼基文明"],"a":1,"w":"克里特的米诺斯文明和迈锡尼文明合称爱琴文明，是古希腊文明的先驱。"},{"q":"古希腊文明的发展顺序正确的是","o":["城邦兴起、爱琴文明、希腊化、古典时期","古典时期、城邦兴起、爱琴文明、希腊化","爱琴文明、城邦兴起、古典时期、希腊化","爱琴文明、古典时期、城邦兴起、希腊化"],"a":2,"w":"先有爱琴文明，前8世纪城邦兴起，前5至前4世纪古典鼎盛，亚历山大东征后进入希腊化。"}],"rel":[{"t":"爱琴文明","n":"古希腊文明的前身"},{"t":"城邦","n":"古希腊的政治形态"},{"t":"希腊化时代","n":"古希腊文明的延伸"},{"t":"两希文明（希腊传统与希伯来传统）","n":"西方文明两大源头"},{"t":"二里头遗址","n":"同期东方早期国家文明"}],"more":"重要节点：约前8世纪城邦形成；前776年首届古代奥运会（传统说法）；前5世纪伯里克利时代；前338年马其顿控制希腊；前146年罗马灭亡希腊。"},{"id":"b09-002","t":"城邦","cid":"09a","p":1,"kind":"制度","exam":["2021名解"],"alias":["城邦制度","polis","古希腊城邦"],"one":"古希腊以城市为中心的独立小国，雅典民主、斯巴达寡头为两种典型。","ans":"城邦（polis）是**古希腊以一座城市为中心、连同周边乡村构成的独立国家**，约**公元前8世纪起普遍形成**，数量多达数百个。其特点是**小国寡民、独立自治**，以**公民集体**为核心，公民共同参与政治、军事和宗教事务。城邦政体多样：**雅典经梭伦改革、克里斯提尼改革，在伯里克利时代形成奴隶制民主政治**；**斯巴达实行贵族寡头政治，以军事化管理著称**。城邦孕育了**公民意识、法治与民主传统**，但民主只属于成年男性公民，妇女、奴隶和外邦人被排除在外。","pts":["以城市为中心的独立小国，前8世纪形成","小国寡民、公民集体，雅典民主与斯巴达寡头","西方民主法治源头，民主有局限"],"mem":"一句话画面：一座城加一圈田就是一个国，所以叫“小国寡民”。两大样板对着记：雅典“民主”重公民参政，斯巴达“寡头”重军事训练。局限记“三类人没票”：妇女、奴隶、外邦人。亚里士多德“人是天生的城邦动物”可作结尾点题。","mix":"城邦是国家形态，不是统一国家：希腊从未形成统一政权。雅典民主有局限，不等于现代普选民主。","mcq":[{"q":"古希腊城邦的基本特征是","o":["疆域辽阔、中央集权","小国寡民、独立自治","君主世袭、官僚治理","宗教统一、神权统治"],"a":1,"w":"城邦以一座城市及周边乡村为单位，彼此独立，公民集体参与公共事务。"},{"q":"下列城邦与政体对应正确的是","o":["斯巴达：奴隶制民主","雅典：军事贵族寡头","雅典：奴隶制民主","斯巴达：僭主政治"],"a":2,"w":"雅典经梭伦、克里斯提尼改革形成民主制，斯巴达实行贵族寡头制。"}],"rel":[{"t":"雅典民主","n":"城邦政治的典型"},{"t":"斯巴达","n":"军事寡头城邦"},{"t":"人是政治动物","n":"亚里士多德论城邦"},{"t":"古希腊文明","n":"城邦是其政治基础"},{"t":"三家分晋","n":"同时代中国列国分立"}],"more":"亚里士多德：人是天生的城邦动物（政治动物）。｜《政治学》\n前8世纪起希腊人向地中海和黑海沿岸殖民，建立大量新城邦。"},{"id":"b09-003","t":"荷马史诗","cid":"09c","p":1,"kind":"作品","exam":["2019名解"],"alias":["荷马","《伊利亚特》","《奥德赛》","伊利亚特","奥德赛","伊利昂纪","奥德修纪"],"one":"相传盲诗人荷马所作的《伊利亚特》和《奥德赛》，西方文学源头。","ans":"荷马史诗是**古希腊长篇叙事诗《伊利亚特》和《奥德赛》的合称，相传为盲诗人荷马所作**，在长期口头传唱基础上**约于公元前8世纪前后定型**。**《伊利亚特》以特洛伊战争第十年为背景，围绕阿喀琉斯的愤怒展开**；**《奥德赛》叙述伊塔卡国王奥德修斯战后十年漂泊、返乡复仇的经历**。史诗反映了**迈锡尼文明衰落后、城邦兴起前的“荷马时代”（约前11至前9世纪）**的社会面貌，是**西方文学的源头**，也是研究早期希腊历史的重要史料。","pts":["两部史诗，相传荷马，约前8世纪定型","阿喀琉斯之怒、奥德修斯返乡","反映荷马时代，西方文学源头"],"mem":"“伊”打仗，“奥”回家：《伊利亚特》写战场，《奥德赛》写归途。主角一对一：阿喀琉斯（愤怒）、奥德修斯（智谋）。木马计不在《伊利亚特》里：书以赫克托耳的葬礼结束，木马见于《奥德赛》的回述和维吉尔《埃涅阿斯纪》。","mix":"《伊利亚特》没有木马计，也没有阿喀琉斯之死；木马故事最完整见于《埃涅阿斯纪》。荷马是否真有其人、是否一人所作，学界有“荷马问题”之争。","mcq":[{"q":"荷马史诗中讲述奥德修斯战后漂泊返乡的是","o":["《伊利亚特》","《埃涅阿斯纪》","《奥德赛》","《神谱》"],"a":2,"w":"《奥德赛》写伊塔卡国王奥德修斯十年返乡。"},{"q":"下列关于《伊利亚特》的说法，正确的是","o":["详细描写了木马计","以阿喀琉斯的愤怒为主线","作者是维吉尔","记述希波战争"],"a":1,"w":"《伊利亚特》围绕阿喀琉斯的愤怒展开，以赫克托耳葬礼结束，没有写木马计。"}],"rel":[{"t":"特洛伊战争","n":"史诗的背景"},{"t":"奥德修斯","n":"《奥德赛》主角"},{"t":"《埃涅阿斯纪》","n":"罗马的“荷马”式史诗"},{"t":"民间史诗与文人史诗","n":"荷马属民间史诗"},{"t":"《吉尔伽美什》","n":"更早的两河史诗"}],"more":"《伊利亚特》约15693行，24卷；《奥德赛》约12110行，24卷。\n荷马被称为“盲诗人”，相传为小亚细亚的吟游诗人。"},{"id":"b09-004","t":"希罗多德","cid":"09b","p":1,"kind":"人物","exam":["2013名解","2015名解"],"alias":["历史之父","《历史》作者"],"one":"古希腊史学家，“历史之父”，《历史》记希波战争。","ans":"希罗多德（约前484至约前425）是**古希腊历史学家，生于小亚细亚的哈利卡纳苏斯**，**被古罗马的西塞罗称为“历史之父”**。其著作**《历史》（又名《希波战争史》）是西方第一部完整流传下来的历史著作**，**以希腊城邦与波斯帝国之间的希波战争为主线**，同时记述西亚、埃及、北非等地的地理风俗和传说。他**重视实地考察和访谈，保存不同说法**，开创了西方叙事史学传统，书中也保留了不少神意与传闻。","pts":["古希腊史学家，“历史之父”","《历史》即《希波战争史》，西方第一部完整史书","实地考察、叙事史学"],"mem":"双史家对照：希罗多德写“希波”，修昔底德写“伯罗奔尼撒”。口诀“希对希，修对伯”：希罗多德对希波战争，修昔底德对伯罗奔尼撒战争。风格也对着记：希罗多德爱讲故事、保留神意；修昔底德重因果、排除神意。中国对应人物是司马迁，被称为“史学之父”。","mix":"西塞罗称希罗多德为“历史之父”；修昔底德被后世称为“科学历史学之父”。《历史》原名意为“探究”，中文常译《希波战争史》。","mcq":[{"q":"被称为“历史之父”的古希腊史学家是","o":["修昔底德","色诺芬","希罗多德","普鲁塔克"],"a":2,"w":"西塞罗称希罗多德为历史之父，《历史》记述希波战争。"},{"q":"希罗多德《历史》的主线是","o":["伯罗奔尼撒战争","希波战争","特洛伊战争","布匿战争"],"a":1,"w":"《历史》又名《希波战争史》；伯罗奔尼撒战争由修昔底德记述。"}],"rel":[{"t":"伯罗奔尼撒战争","n":"修昔底德所记，常对举"},{"t":"波斯帝国","n":"《历史》中的对手"},{"t":"修昔底德陷阱","n":"另一位史家的论断"},{"t":"古希腊文明","n":"史学是其成就之一"},{"t":"司马迁","n":"中国的“史学之父”"}],"more":"《历史》共九卷，后世以九位缪斯之名为各卷命名。"},{"id":"b09-005","t":"修昔底德陷阱","cid":"09b","p":1,"kind":"概念","exam":["2020名解"],"alias":["修昔底德圈套","修昔底德陷阱论"],"one":"崛起大国与守成大国必有一战之说，源自修昔底德论伯罗奔尼撒战争。","ans":"修昔底德陷阱指**新崛起的大国必然挑战现存大国、现存大国也必然回应，战争因而几乎不可避免**的说法。它**源自古希腊史学家修昔底德对伯罗奔尼撒战争起因的分析：“使战争不可避免的，是雅典力量的增长及其在斯巴达引起的恐惧。”** **2012年哈佛大学学者格雷厄姆·艾利森提出这一概念**，并在**2017年出版的《注定一战：中美能避免修昔底德陷阱吗？》**中用来分析中美关系。中国领导人提出，**世界上本无“修昔底德陷阱”，大国之间一再发生战略误判才会自己给自己造成陷阱**，主张走和平发展道路。","pts":["崛起国与守成国必有一战之说","源于修昔底德论伯罗奔尼撒战争，艾利森2012年提出","中方：本无此陷阱，避免战略误判"],"mem":"画面：雅典长高了，斯巴达害怕了，于是打起来。因果链“崛起、恐惧、战争”。人物挂钩：修昔底德（古人，提供原话）、艾利森（今人，2012年命名，2017年出书《注定一战》）。中方立场一句话：陷阱不是天注定，是误判造成的。","mix":"提出者艾利森是美国人，修昔底德只是史料源头；该词不是修昔底德本人使用的概念。书名《注定一战》，副标题问的是“能否避免”。","mcq":[{"q":"“修昔底德陷阱”概念的现代提出者是","o":["基辛格","约瑟夫·奈","格雷厄姆·艾利森","亨廷顿"],"a":2,"w":"哈佛学者艾利森2012年提出，并著《注定一战》。"},{"q":"修昔底德陷阱所依据的古代战争是","o":["希波战争","特洛伊战争","布匿战争","伯罗奔尼撒战争"],"a":3,"w":"修昔底德认为雅典力量增长引起斯巴达恐惧，使伯罗奔尼撒战争不可避免。"}],"rel":[{"t":"伯罗奔尼撒战争","n":"概念的历史原型"},{"t":"斯巴达","n":"守成一方"},{"t":"中美建设性战略稳定关系","n":"当代中美关系语境"},{"t":"地缘政治","n":"相关分析框架"},{"t":"希罗多德","n":"另一位希腊史家"}],"more":"原话：使战争不可避免的，是雅典力量的增长，以及这种增长在斯巴达引起的恐惧。｜修昔底德《伯罗奔尼撒战争史》"},{"id":"b09-006","t":"伯罗奔尼撒战争","cid":"09b","p":1,"kind":"事件","exam":["2013名解","2015名解"],"alias":["伯罗奔尼撒战争史","伯罗奔尼撒同盟","提洛同盟"],"one":"前431至前404年，雅典与斯巴达争霸，古典城邦由盛转衰。","ans":"伯罗奔尼撒战争是**公元前431年至前404年，以雅典为首的提洛同盟与以斯巴达为首的伯罗奔尼撒同盟之间争夺希腊霸权的战争**。战争起因于**希波战争后雅典势力扩张引起斯巴达的恐惧**；其间雅典暴发瘟疫、伯里克利病逝，**前415年远征西西里惨败**，最终**雅典投降，斯巴达获胜**。战争**削弱了整个希腊世界，标志着古典城邦由盛转衰**，为后来马其顿征服希腊创造了条件。**修昔底德的《伯罗奔尼撒战争史》**记述了这场战争。","pts":["前431至前404，雅典与斯巴达两大同盟","雅典扩张引发恐惧，西西里远征失败，斯巴达胜","城邦由盛转衰，修昔底德记载"],"mem":"数字“431 到 404”，二十七年。结构：提洛（雅典，海上）对伯罗奔尼撒（斯巴达，陆上）。败因三连：瘟疫、伯里克利病逝、西西里惨败（415）。结局一句话：雅典输了，斯巴达赢了，但整个希腊都输了，马其顿坐收渔利。","mix":"希波战争（希腊对波斯，前5世纪前期）与伯罗奔尼撒战争（希腊内战）不能混；前者由希罗多德记，后者由修昔底德记。","mcq":[{"q":"伯罗奔尼撒战争的交战双方是","o":["希腊城邦与波斯","罗马与迦太基","雅典与马其顿","提洛同盟与伯罗奔尼撒同盟"],"a":3,"w":"雅典领导提洛同盟，斯巴达领导伯罗奔尼撒同盟。"},{"q":"伯罗奔尼撒战争的时间是","o":["前492至前449年","前431至前404年","前356至前323年","前264至前146年"],"a":1,"w":"战争自前431年持续到前404年，以雅典投降结束。"}],"rel":[{"t":"修昔底德陷阱","n":"由此战争概括而来"},{"t":"伯里克利","n":"战争初期的雅典领袖"},{"t":"斯巴达","n":"战胜方"},{"t":"雅典民主","n":"战败方的政制"},{"t":"希罗多德","n":"所记希波战争常对举"}],"more":"修昔底德《伯罗奔尼撒战争史》记事止于前411年，未写完。"},{"id":"b09-007","t":"苏格拉底","cid":"09f","p":1,"kind":"人物","alias":["苏氏","苏格拉底方法","精神助产术"],"one":"雅典哲学家，无著作，“认识你自己”，被判死刑。","ans":"苏格拉底（约前469至前399）是**古希腊雅典哲学家**，与柏拉图、亚里士多德并称“古希腊三贤”。他**本人没有著作**，思想主要见于**弟子柏拉图的对话录和色诺芬的回忆录**。他把哲学**从研究自然转向研究人和伦理**，倡导**“认识你自己”**，提出**“美德即知识”**，以**问答诘难、层层追问的“苏格拉底方法”（精神助产术）**揭示矛盾、探求定义。**前399年他以“不敬神”“败坏青年”的罪名被雅典法庭判处死刑，饮鸩而死**。","pts":["雅典哲学家，三贤之首，无著作","认识你自己、美德即知识、助产术","被判死刑，饮鸩而死"],"mem":"师徒三代口诀“苏柏亚”：苏格拉底（述而不作）→ 柏拉图（写对话）→ 亚里士多德（集大成）。苏格拉底三件套：一句话“认识你自己”（德尔斐神庙箴言），一个命题“美德即知识”，一种方法“助产术”。画面：广场上不停追问的老人，最后捧着毒酒杯。","mix":"苏格拉底无著作，《申辩篇》等对话由柏拉图所写；他的死刑发生于前399年，与伯罗奔尼撒战争（前404）后的雅典政治动荡有关。孔子也述而不作，常被拿来类比。","mcq":[{"q":"下列关于苏格拉底的说法正确的是","o":["著有《理想国》","创办阿卡德米学园","没有亲自写作","是亚里士多德的老师"],"a":2,"w":"苏格拉底述而不作，《理想国》和阿卡德米学园属于柏拉图。"},{"q":"提出“美德即知识”的哲学家是","o":["亚里士多德","柏拉图","德谟克利特","苏格拉底"],"a":3,"w":"苏格拉底提出美德即知识，主张“认识你自己”。"}],"rel":[{"t":"柏拉图","n":"学生，记录其思想"},{"t":"古希腊三贤","n":"三贤之首"},{"t":"助产术（苏格拉底方法）","n":"问答诘难的方法"},{"t":"苏格拉底之死","n":"饮鸩而死的事件"},{"t":"孔子","n":"同为述而不作的师者"}],"more":"认识你自己。｜德尔斐神庙箴言，苏格拉底奉为宗旨\n我知道我一无所知。｜传为苏格拉底之言","exam":[]},{"id":"b09-008","t":"柏拉图","cid":"09f","p":1,"kind":"人物","exam":["2020名解"],"alias":["柏拉图学园","阿卡德米学园"],"one":"苏格拉底弟子，著《理想国》，提出理念论，创阿卡德米学园。","ans":"柏拉图（约前427至前347）是**古希腊哲学家，苏格拉底的学生、亚里士多德的老师**，**约前387年在雅典创办阿卡德米学园**。著作多为**对话体，代表作《理想国》**。他提出**理念论**，认为**感官所见的事物变动不居，真实存在的是永恒不变的理念世界**，并以**“洞穴比喻”**说明认识过程；在《理想国》中设计了由**哲学王统治、各阶层各司其职的理想国家**，以正义为核心。他是**西方客观唯心主义的创始人**，深刻影响了西方哲学和政治思想。","pts":["苏格拉底学生、亚里士多德老师，创阿卡德米学园","理念论、洞穴比喻","《理想国》哲学王与正义，客观唯心主义"],"mem":"三个关键词“理、洞、王”：理念论、洞穴比喻、哲学王，三者都在《理想国》。画面：洞里的囚徒只看见墙上的影子，走出洞的人才见到太阳（理念）。师承线“苏柏亚”：苏格拉底 → 柏拉图 → 亚里士多德。学园在雅典，名叫阿卡德米，是 Academy（学院）一词的来源。","mix":"《诗学》《政治学》属亚里士多德，不属柏拉图。柏拉图是客观唯心主义，亚里士多德摇摆于唯物与唯心之间，德谟克利特才是唯物主义原子论者。","mcq":[{"q":"柏拉图创办的学园名称是","o":["吕克昂","阿卡德米","伊壁鸠鲁花园","斯多葛学园"],"a":1,"w":"柏拉图约前387年创办阿卡德米学园；亚里士多德创办的是吕克昂。"},{"q":"下列哪一项不属于柏拉图的思想或作品","o":["《理想国》","洞穴比喻","理念论","《诗学》"],"a":3,"w":"《诗学》是亚里士多德所作。"}],"rel":[{"t":"苏格拉底","n":"老师"},{"t":"亚里士多德","n":"学生"},{"t":"理念论","n":"核心学说"},{"t":"洞穴比喻","n":"出自《理想国》"},{"t":"《理想国》","n":"代表作"}],"more":"主要对话：《理想国》《申辩篇》《斐多篇》《会饮篇》《蒂迈欧篇》。\n《理想国》第七卷提出洞穴比喻。"},{"id":"b09-009","t":"《理想国》","cid":"09f","p":1,"kind":"作品","alias":["理想国","The Republic"],"one":"柏拉图的对话录，围绕正义构建三阶层的理想城邦，提出哲学王。","ans":"《理想国》是**古希腊哲学家柏拉图的代表作**，以苏格拉底为主要对话人的对话录，共十卷，成书于公元前4世纪。全书**围绕“什么是正义”展开**，设计了由统治者（哲学王）、护卫者和生产者**三个阶层各安其位**的理想城邦，主张**“哲学家成为国王，或者国王成为哲学家”**。书中提出**理念论和“洞穴比喻”**，还讨论教育与诗歌，主张把模仿性的诗人逐出理想国。它是**西方政治哲学的奠基之作**，开启了西方乌托邦思想传统。","pts":["柏拉图对话录，苏格拉底为主讲人","围绕正义：三阶层、哲学王、理念论、洞穴比喻","西方政治哲学奠基，乌托邦传统源头"],"mem":"三阶层配三种美德：统治者对应智慧，护卫者对应勇敢，生产者对应节制，三者各守本分就是正义。画面：一座按金、银、铜铁三种“禀赋”分层的城邦（书中的“金属神话”），最高处坐着爱智慧的哲学家。","mix":"莫尔《乌托邦》（1516，英国）、康帕内拉《太阳城》是近代作品，不是柏拉图所作；柏拉图晚年另有《法律篇》，写的是“次优”的城邦；亚里士多德《政治学》对《理想国》有批评。","mcq":[{"q":"关于《理想国》，下列说法正确的是","o":["作者是亚里士多德","以苏格拉底为主要对话人","最早提出“三一律”","是近代空想社会主义作品"],"a":1,"w":"《理想国》是柏拉图的对话录，苏格拉底是主要对话人。"},{"q":"柏拉图在《理想国》中设想的理想城邦，应由哪类人担任统治者","o":["诗人","武士","商人","哲学家"],"a":3,"w":"主张“哲学家成为国王”，即哲学王。"}],"rel":[{"t":"柏拉图","n":"作者"},{"t":"理念论","n":"书中核心学说"},{"t":"洞穴比喻","n":"见第七卷"},{"t":"托马斯·莫尔《乌托邦》","n":"近代乌托邦，常作干扰项"},{"t":"苏格拉底","n":"书中主要对话人"}],"more":"名言：除非哲学家成为国王，或者国王成为哲学家，城邦就不会有安宁。｜《理想国》卷五\n洞穴比喻见第七卷；全书十卷。","exam":[]},{"id":"b09-010","t":"亚里士多德","cid":"09f","p":1,"kind":"人物","exam":["2022名解"],"alias":["亚理斯多德","亚里斯多德"],"one":"古希腊百科全书式哲学家，柏拉图弟子，创形式逻辑，著《诗学》。","ans":"亚里士多德（前384—前322）是**古希腊哲学家、科学家，柏拉图的学生、亚历山大大帝的老师**，约前335年在雅典创办**吕克昂学园**（学派称**逍遥学派**）。他是百科全书式的学者，代表作有《工具论》《形而上学》《尼各马可伦理学》《政治学》《诗学》。他批判老师的理念论（“**吾爱吾师，吾更爱真理**”），**创立形式逻辑**（三段论）；《诗学》提出**模仿说与悲剧的“净化”作用**，是西方第一部系统的文艺理论著作，后世“三一律”即由此引申。马克思称他为“古代最伟大的思想家”。","pts":["柏拉图学生、亚历山大老师，创吕克昂学园","百科全书式学者，创形式逻辑，批判理念论","《诗学》模仿说与净化说，影响三一律"],"mem":"师徒三代接力：苏格拉底（述而不作）→柏拉图（学园、理念论）→亚里士多德（吕克昂、逻辑与百科）。画面：他在吕克昂的林荫道上边散步边讲课，学生跟着走，所以叫“逍遥（漫步）学派”。五部代表作自编首字串“工形尼政诗”：《工具论》《形而上学》《尼各马可伦理学》《政治学》《诗学》。","mix":"阿卡德米学园是柏拉图创办，吕克昂是亚里士多德创办；《诗学》（亚里士多德）与《诗艺》（贺拉斯）一字之差；“吾爱吾师，吾更爱真理”是后人对其意思的概括，并非原话。","mcq":[{"q":"下列著作中，作者是亚里士多德的是","o":["《理想国》","《诗学》","《诗艺》","《神谱》"],"a":1,"w":"《理想国》柏拉图，《诗艺》贺拉斯，《神谱》赫西俄德。"},{"q":"亚里士多德创办的学园是","o":["阿卡德米学园","伊壁鸠鲁花园","吕克昂学园","斯多葛画廊"],"a":2,"w":"阿卡德米属柏拉图；吕克昂属亚里士多德，学派称逍遥学派。"}],"rel":[{"t":"柏拉图","n":"老师"},{"t":"《诗学》","n":"代表作，模仿说与净化说"},{"t":"吕克昂学园与逍遥学派","n":"所创学园"},{"t":"亚历山大大帝","n":"其学生"},{"t":"人是政治动物","n":"《政治学》名句"}],"more":"主要著作：《工具论》《形而上学》《物理学》《尼各马可伦理学》《政治学》《诗学》。\n名句：人是天生的政治动物。｜《政治学》"},{"id":"b09-011","t":"三一律","cid":"09d","p":1,"kind":"概念","exam":["2022名解"],"alias":["三整一律","三一律原则"],"one":"古典主义戏剧规则：行动、时间、地点三个一致。","ans":"三一律是**西方古典主义戏剧的创作规则**，要求一部剧作**只有一个情节（行动一致）、剧情发生在一天之内（时间一致）、地点固定在一处（地点一致）**。它**源于亚里士多德《诗学》对悲剧情节整一和时间集中的论述**，**16世纪由意大利学者（卡斯特尔维特罗）归纳为规则**，**17世纪法国古典主义理论家布瓦洛在《诗的艺术》中将其奉为定律**，高乃依、拉辛、莫里哀的剧作多加遵循。它使剧情集中紧凑，也束缚了创作，**19世纪雨果在《〈克伦威尔〉序言》中予以批判**。","pts":["行动、时间、地点三个一致","源于亚里士多德，意大利归纳、法国古典主义确立","利弊并存，雨果为代表的浪漫主义批判"],"members":[["行动一致","全剧只有一个中心情节"],["时间一致","剧情发生在一昼夜之内"],["地点一致","场景固定在一处"]],"mem":"口诀“一事、一日、一地”。传承四站：亚里士多德（源）→ 卡斯特尔维特罗（归纳）→ 布瓦洛（立法）→ 雨果（破除）。画面：一出戏只演一件事、一天、一间屋，没法写出莎士比亚式的大场面，所以莎士比亚被古典主义者批评，被浪漫主义者推崇。","mix":"亚里士多德《诗学》明确强调的只有行动整一，时间与地点的要求是后人补充的。布瓦洛是古典主义理论家，不是剧作家；高乃依、拉辛、莫里哀是遵循者。","mcq":[{"q":"“三一律”不包括下列哪一项一致","o":["行动","时间","地点","人物"],"a":3,"w":"三一律是行动、时间、地点三个一致，不含人物一致。"},{"q":"在《诗的艺术》中将三一律奉为定律的是","o":["布瓦洛","雨果","莫里哀","高乃依"],"a":0,"w":"布瓦洛是17世纪法国古典主义理论家，《诗的艺术》（1674）是古典主义的纲领。"}],"rel":[{"t":"布瓦洛《诗的艺术》","n":"确立三一律的著作"},{"t":"《诗学》","n":"三一律的思想源头"},{"t":"古典主义","n":"三一律所属潮流"},{"t":"雨果","n":"浪漫主义批判者"},{"t":"《欧那尼》","n":"突破三一律的演出事件"}],"more":"法国古典主义戏剧三大家：高乃依、拉辛、莫里哀。\n雨果《〈克伦威尔〉序言》（1827）被称为法国浪漫主义的宣言。"},{"id":"b09-012","t":"古希腊三大悲剧家","cid":"09d","p":1,"kind":"合称","alias":["三大悲剧家","希腊三大悲剧诗人","古希腊三大悲剧诗人"],"one":"埃斯库罗斯、索福克勒斯、欧里庇得斯，公元前5世纪雅典的悲剧大家。","ans":"古希腊三大悲剧家指**公元前5世纪雅典的埃斯库罗斯、索福克勒斯和欧里庇得斯**。**埃斯库罗斯被称为“悲剧之父”**，代表作有**《俄瑞斯忒亚》三部曲（《阿伽门农》《奠酒人》《报仇神》）、《被缚的普罗米修斯》《波斯人》**；**索福克勒斯**被誉为“戏剧艺术的荷马”，代表作**《俄狄浦斯王》《安提戈涅》**；**欧里庇得斯**被称为“舞台上的哲学家”，代表作**《美狄亚》《特洛伊妇女》**。三人的创作从**命运观念走向人物性格与人性心理**，奠定了西方悲剧传统；同时期的**阿里斯托芬被称为“喜剧之父”**。","pts":["三人名单与时代：前5世纪雅典","作品对应：《俄瑞斯忒亚》《俄狄浦斯王》《美狄亚》","西方悲剧奠基；阿里斯托芬为喜剧之父"],"members":[["埃斯库罗斯","“悲剧之父”；《俄瑞斯忒亚》三部曲、《被缚的普罗米修斯》"],["索福克勒斯","《俄狄浦斯王》《安提戈涅》；“戏剧艺术的荷马”"],["欧里庇得斯","“舞台上的哲学家”；《美狄亚》《特洛伊妇女》"]],"mem":"顺序“埃、索、欧”，作品跟着排：埃（普罗米修斯、俄瑞斯忒亚）、索（俄狄浦斯、安提戈涅）、欧（美狄亚、特洛伊妇女）。主题递进：命运（埃）→ 性格与选择（索）→ 人性与心理（欧）。头衔配对：埃是“悲剧之父”，索是“戏剧艺术的荷马”，欧是“舞台上的哲学家”。","mix":"《被缚的普罗米修斯》归埃斯库罗斯，不归索福克勒斯；雪莱另有诗剧《解放了的普罗米修斯》。阿里斯托芬写喜剧，不在三大悲剧家之列。","mcq":[{"q":"《俄狄浦斯王》的作者是","o":["埃斯库罗斯","欧里庇得斯","阿里斯托芬","索福克勒斯"],"a":3,"w":"索福克勒斯，另有《安提戈涅》。"},{"q":"下列作家与作品对应错误的是","o":["欧里庇得斯：《美狄亚》","埃斯库罗斯：《波斯人》","阿里斯托芬：《俄瑞斯忒亚》","索福克勒斯：《安提戈涅》"],"a":2,"w":"《俄瑞斯忒亚》三部曲出自埃斯库罗斯；阿里斯托芬写喜剧《鸟》《蛙》《云》。"}],"rel":[{"t":"埃斯库罗斯","n":"“悲剧之父”"},{"t":"索福克勒斯","n":"《俄狄浦斯王》作者"},{"t":"欧里庇得斯","n":"“舞台上的哲学家”"},{"t":"阿里斯托芬","n":"“喜剧之父”"},{"t":"莎士比亚四大悲剧","n":"西方悲剧的后世高峰"}],"more":"悲剧起源于祭祀酒神狄俄尼索斯的颂歌与竞赛。\n《美狄亚》：科林斯公主美狄亚因伊阿宋变心而复仇，杀死亲生子女。","exam":[]},{"id":"b09-013","t":"朴素唯物主义","cid":"09e","p":1,"kind":"概念","exam":["2019名解","2025选择"],"alias":["古代朴素唯物主义","朴素唯物论"],"one":"把世界本原归为水、火、原子、气等具体物质的古代唯物主义。","ans":"朴素唯物主义是**古代唯物主义的基本形态**，**把世界的本原归结为一种或几种具体的物质形态**，如**古希腊泰勒斯的“水”、赫拉克利特的“火”、德谟克利特的“原子”，中国古代的“五行说”和“气”**。它**坚持从物质本身说明世界、肯定世界的物质统一性**，方向正确，但**建立在直观和猜测的基础上，缺乏科学论证**，把物质等同于具体物质形态。它常与**朴素辩证法**相结合，后来发展为近代**形而上学唯物主义**和马克思主义的**辩证唯物主义**。","pts":["古代唯物主义，本原归结为具体物质","水、火、原子、五行、气","直观猜测的局限，后续发展"],"mem":"“水、气、火、原”四个字对四个人：泰勒斯水，阿那克西美尼气，赫拉克利特火，德谟克利特原子。中国对应“五行、气”。发展线：朴素唯物 → 形而上学唯物（近代）→ 辩证唯物（马克思）。局限一句话：凭直观猜出来，没有论证。","mix":"本原说（朴素唯物主义）与辩证法是两条分类轴：赫拉克利特“火是本原”属朴素唯物主义，“万物皆流”属朴素辩证法。毕达哥拉斯的“数”不是具体物质，通常不归入朴素唯物主义。","mcq":[{"q":"下列哲学家与本原对应属于朴素唯物主义的是","o":["赫拉克利特：火","毕达哥拉斯：数","柏拉图：理念","巴门尼德：存在"],"a":0,"w":"火是具体物质，属朴素唯物主义；数、理念、存在不是具体物质。"},{"q":"关于朴素唯物主义，下列说法正确的是","o":["肯定理念世界先于物质","以神意解释自然","以直观猜测为基础，缺乏科学论证","由马克思创立"],"a":2,"w":"朴素唯物主义把本原归为具体物质，但基于直观猜测，缺乏科学论证。"}],"rel":[{"t":"赫拉克利特","n":"火为本原"},{"t":"泰勒斯","n":"水为本原"},{"t":"德谟克利特","n":"原子论"},{"t":"五行","n":"中国的朴素唯物主义"},{"t":"唯物主义与唯心主义","n":"哲学两大基本派别"}],"more":"2025年选择题：赫拉克利特“火是万物本原”属朴素唯物主义，“万物皆流”属朴素辩证法。"},{"id":"b09-014","t":"特洛伊战争","cid":"09c","p":1,"kind":"事件","exam":["2019名解"],"alias":["特洛伊","木马计","金苹果之争","特洛伊之战"],"one":"传说中希腊联军远征特洛伊十年，以木马计攻陷，见于荷马史诗。","ans":"特洛伊战争是**古希腊传说中以迈锡尼国王阿伽门农为首的希腊联军远征小亚细亚特洛伊城的十年战争**，传说发生在**公元前13至前12世纪之交**。起因是**特洛伊王子帕里斯带走斯巴达王后海伦**（远因是“金苹果之争”）；战争中涌现了**阿喀琉斯、赫克托耳、奥德修斯**等英雄，**最终希腊人以奥德修斯的“木马计”攻陷特洛伊**。故事主要见于**荷马史诗**；**19世纪70年代德国人谢里曼在今土耳其西北部发掘出特洛伊遗址**，说明传说有一定历史背景。","pts":["阿伽门农率希腊联军攻特洛伊十年","海伦、阿喀琉斯、木马计","荷马史诗记载，谢里曼发掘"],"mem":"因果链：金苹果（谁最美）→ 帕里斯选阿芙洛狄忒 → 得海伦 → 希腊联军出征 → 十年 → 木马计。四个人物各配一词：阿伽门农（统帅）、阿喀琉斯（第一勇士）、赫克托耳（特洛伊守将）、奥德修斯（献木马计）。考古人物：谢里曼。","mix":"《伊利亚特》只写战争第十年的一段，没有木马；木马计见于《奥德赛》的回述和《埃涅阿斯纪》。特洛伊战争属传说，不能直接当信史。","mcq":[{"q":"特洛伊战争的直接起因是","o":["帕里斯带走斯巴达王后海伦","阿喀琉斯与阿伽门农争夺女俘","波斯入侵希腊","雅典远征西西里"],"a":0,"w":"特洛伊王子帕里斯带走斯巴达王后海伦，引发希腊联军远征。"},{"q":"19世纪70年代发掘特洛伊遗址的是","o":["伊文思","谢里曼","文特里斯","卡特"],"a":1,"w":"德国人谢里曼在今土耳其西北部发掘特洛伊遗址。"}],"rel":[{"t":"荷马史诗","n":"主要文献来源"},{"t":"特洛伊木马","n":"战争中的典故"},{"t":"迈锡尼文明","n":"战争的时代背景"},{"t":"奥德修斯","n":"木马计设计者"},{"t":"《埃涅阿斯纪》","n":"从特洛伊败将写起"}],"more":"阿喀琉斯之踵：母亲握其脚踵浸冥河水，脚踵成唯一弱点，后被帕里斯一箭射中致死。"},{"id":"b09-015","t":"迈锡尼文明","cid":"09a","p":1,"kind":"概念","exam":["2019名解"],"alias":["迈锡尼","迈锡尼时代"],"one":"希腊大陆晚期青铜文明，用线形文字B，传说阿伽门农为其国王。","ans":"迈锡尼文明是**希腊半岛南部伯罗奔尼撒地区的晚期青铜时代文明（约前1600至前1100年）**，因**迈锡尼城**得名。它以**巨石城堡（“狮子门”）、王宫和竖井墓、圆顶墓**为特征，由**武士贵族**统治，使用**线形文字B**，1952年由英国人文特里斯释读，记录的是早期希腊语。**传说中率希腊联军远征特洛伊的阿伽门农就是迈锡尼国王**。约前12世纪迈锡尼文明衰落，希腊进入文字失传的**“黑暗时代”（荷马时代）**。","pts":["希腊大陆晚期青铜文明，因迈锡尼城得名","狮子门、武士贵族、线形文字B","阿伽门农传说，衰落后进入荷马时代"],"mem":"对比记：克里特“海上、和平、文字A读不通”，迈锡尼“陆上、武士、文字B已读通”。画面：狮子门前站着带兵的阿伽门农，文字B是他账房里的泥板。读通的人是文特里斯（1952）。","mix":"线形文字A属米诺斯文明，至今未释读；线形文字B属迈锡尼文明，已释读为希腊语。发掘迈锡尼的是谢里曼，发掘克诺索斯的是伊文思。","mcq":[{"q":"由英国人文特里斯于1952年释读的文字是","o":["线形文字B","线形文字A","楔形文字","象形文字"],"a":0,"w":"线形文字B记录早期希腊语，属迈锡尼文明；线形文字A至今未释读。"},{"q":"传说中率希腊联军远征特洛伊的阿伽门农是哪个文明的国王","o":["米诺斯文明","腓尼基文明","迈锡尼文明","赫梯文明"],"a":2,"w":"阿伽门农为迈锡尼国王，特洛伊战争传说附着于迈锡尼时代。"}],"rel":[{"t":"爱琴文明","n":"迈锡尼属其后期"},{"t":"克里特文明（米诺斯文明）","n":"迈锡尼的前辈"},{"t":"线形文字B","n":"迈锡尼使用的文字"},{"t":"特洛伊战争","n":"传说发生于迈锡尼时代"},{"t":"荷马史诗","n":"反映迈锡尼的追忆"}],"more":"1876年谢里曼在迈锡尼发掘竖井墓，发现“阿伽门农面具”。"},{"id":"b09-016","t":"爱琴文明","cid":"09a","p":1,"kind":"地理","exam":["2016名解"],"alias":["爱琴海文明","爱琴海","克里特-迈锡尼文明"],"one":"爱琴海地区青铜时代文明，含克里特与迈锡尼，古希腊文明先驱。","ans":"爱琴文明是**公元前20世纪至前12世纪左右爱琴海地区的青铜时代文明**，是**古希腊文明的先驱**，主要包括**克里特岛的米诺斯文明和希腊半岛的迈锡尼文明**。**米诺斯文明以克诺索斯王宫为代表**，使用至今未能释读的**线形文字A**，流传有国王米诺斯和迷宫的传说；约前15世纪米诺斯文明衰落，**迈锡尼人控制克里特**。**19世纪后期德国人谢里曼发掘特洛伊和迈锡尼，1900年英国人伊文思发掘克诺索斯**，使爱琴文明重见天日。","pts":["青铜时代爱琴海文明，古希腊先驱","米诺斯（克诺索斯、线形文字A）与迈锡尼","谢里曼、伊文思的考古发掘"],"mem":"先后顺序“克在先，迈在后”：克里特（米诺斯）先，迈锡尼后。考古两人各认一处：谢里曼挖“特洛伊、迈锡尼”，伊文思挖“克诺索斯”（1900）。文字“A 先 B 后”，A 属克里特未解，B 属迈锡尼已解。","mix":"爱琴海是地理名称，位于希腊半岛与小亚细亚之间；爱琴文明是考古文明。克里特迷宫与牛头怪米诺陶洛斯属神话传说，与克诺索斯王宫的复杂结构相关联。","mcq":[{"q":"发掘克诺索斯王宫、使米诺斯文明重见天日的是","o":["谢里曼","伊文思","文特里斯","达尔文"],"a":1,"w":"英国人伊文思于1900年起发掘克诺索斯；谢里曼发掘的是特洛伊和迈锡尼。"},{"q":"爱琴文明的构成是","o":["克里特文明与迈锡尼文明","雅典与斯巴达","腓尼基与赫梯","埃及与两河"],"a":0,"w":"爱琴文明包括克里特岛的米诺斯文明和希腊半岛的迈锡尼文明。"}],"rel":[{"t":"克里特文明（米诺斯文明）","n":"爱琴文明前期"},{"t":"迈锡尼文明","n":"爱琴文明后期"},{"t":"线形文字B","n":"迈锡尼文字"},{"t":"古希腊文明","n":"爱琴文明是其先驱"},{"t":"二里头遗址","n":"同期中国早期青铜文明"}],"more":"线形文字A：米诺斯，未释读。线形文字B：迈锡尼，1952年文特里斯释读。"},{"id":"b09-017","t":"希腊神话","cid":"09c","p":1,"kind":"概念","exam":["2018名解"],"alias":["希腊罗马神话","古希腊神话"],"one":"古希腊神话和英雄传说的总称，奥林匹斯诸神与英雄故事。","ans":"希腊神话是**古希腊人创造的神话和英雄传说的总称**，**在口头流传中形成，保存于荷马史诗、赫西俄德《神谱》、悲剧以及古罗马奥维德《变形记》等作品中**。其主体是**以宙斯为首的奥林匹斯诸神**（赫拉、波塞冬、雅典娜、阿波罗、阿佛洛狄忒等）的故事，以及**赫拉克勒斯十二功绩、伊阿宋取金羊毛、特洛伊战争、俄狄浦斯**等英雄传说。神话中的神**“神人同形同性”，有人的情感和弱点**，体现了人本精神。它是**西方文学艺术的重要源泉**，留下“潘多拉的盒子”“阿喀琉斯之踵”“特洛伊木马”等典故。","pts":["神话与英雄传说总称，载于荷马、赫西俄德等","奥林匹斯诸神、英雄传说","神人同形同性，西方文艺源泉与典故"],"mem":"两条线：“神的故事”（《神谱》，宙斯上位）和“人的故事”（英雄传说：赫拉克勒斯、伊阿宋、俄狄浦斯、特洛伊）。特征六字：神人同形同性。典故三件套：潘多拉的盒子、阿喀琉斯之踵、特洛伊木马。文献记“荷赫奥”：荷马、赫西俄德、奥维德。","mix":"希腊神话（宙斯）与罗马神话（朱庇特）名字不同；《变形记》是罗马诗人奥维德所作，不是希腊人写的。《神谱》整理神的谱系，不是史诗。","mcq":[{"q":"系统整理希腊诸神谱系的作品是","o":["《变形记》","《伊利亚特》","《神谱》","《工作与时日》"],"a":2,"w":"赫西俄德《神谱》整理众神谱系；《工作与时日》写农事与劳动。"},{"q":"下列不属于希腊神话典故的是","o":["阿喀琉斯之踵","潘多拉的盒子","特洛伊木马","诺亚方舟"],"a":3,"w":"诺亚方舟出自希伯来《圣经》，属两希中的希伯来传统。"}],"rel":[{"t":"奥林匹斯十二主神","n":"神话主体"},{"t":"赫西俄德","n":"《神谱》作者"},{"t":"潘多拉的盒子","n":"常见典故"},{"t":"希腊神祇的罗马名对应","n":"罗马神话对照"},{"t":"中国古代神话","n":"中西神话对照"}],"more":"神人同形同性：神有人的外形、情感与弱点，与基督教的全能唯一神形成对照。"},{"id":"b09-018","t":"史诗","cid":"09i","p":1,"kind":"概念","exam":["2018名解"],"alias":["英雄史诗","叙事史诗"],"one":"以民族历史、英雄事迹或神话为题材的宏大长篇叙事诗。","ans":"史诗是**以民族历史、英雄事迹或神话传说为题材、规模宏大的长篇叙事诗**，多在**口头传唱中形成，后经整理定型**，风格庄严，被视为民族生活的“百科全书”。西方以**古希腊荷马史诗《伊利亚特》《奥德赛》**为源头，另有两河流域《吉尔伽美什》、古印度**《摩诃婆罗多》《罗摩衍那》**、英国《贝奥武甫》、法国《罗兰之歌》、德国《尼伯龙根之歌》；文人史诗有维吉尔《埃涅阿斯纪》、弥尔顿《失乐园》。中国少数民族有**三大英雄史诗**：藏族《格萨尔王传》、蒙古族《江格尔》、柯尔克孜族《玛纳斯》。","pts":["长篇叙事诗，写民族历史与英雄，口头形成","荷马史诗及世界各地史诗，文人史诗另列","中国三大英雄史诗"],"mem":"按“谁写的”分两类：民间史诗靠集体口传（荷马、印度两部、中世纪欧洲五部、中国三部），文人史诗由个人案头创作（《埃涅阿斯纪》《失乐园》）。数量口诀自编“荷印两、中三、欧五”：荷马两部、印度两部、中国三部、中世纪欧洲五部（《贝奥武甫》《罗兰之歌》《尼伯龙根之歌》《熙德之歌》《伊戈尔远征记》）。","mix":"《伊利亚特》是西方文学的源头，《吉尔伽美什》才是现存最早的史诗之一；《埃涅阿斯纪》是模仿荷马的文人史诗；《神曲》《阿诗玛》不属于上述史诗名单。","mcq":[{"q":"下列作品中，属于文人史诗的是","o":["《伊利亚特》","《罗兰之歌》","《摩诃婆罗多》","《埃涅阿斯纪》"],"a":3,"w":"《埃涅阿斯纪》是维吉尔个人创作的文人史诗，其余为民间史诗。"},{"q":"现存最早的史诗之一，刻于泥板上的是","o":["《吉尔伽美什》","《伊利亚特》","《贝奥武甫》","《罗兰之歌》"],"a":0,"w":"《吉尔伽美什》出自古代两河流域，刻于泥板，含洪水故事。"}],"rel":[{"t":"荷马史诗","n":"西方史诗源头"},{"t":"民间史诗与文人史诗","n":"史诗两大类型"},{"t":"中国三大英雄史诗","n":"中国少数民族史诗"},{"t":"印度两大史诗","n":"东方史诗代表"},{"t":"《吉尔伽美什》","n":"现存最早史诗之一"}],"more":"中世纪欧洲英雄史诗：《贝奥武甫》（英）、《罗兰之歌》（法）、《尼伯龙根之歌》（德）、《熙德之歌》（西）、《伊戈尔远征记》（古罗斯）。"},{"id":"b09-019","t":"《格萨尔王传》","cid":"09i","p":1,"kind":"作品","exam":["2024名解"],"alias":["格萨尔","格萨尔王","《格斯尔》","格萨（斯）尔"],"one":"藏族长篇英雄史诗，岭国国王格萨尔降妖伏魔，世界最长史诗。","ans":"《格萨尔王传》是**藏族民间长篇英雄史诗**，**主要流传于青藏高原藏族地区，并传播到蒙古族、土族等民族中**（蒙古族称《格斯尔》）。史诗以**岭国国王格萨尔降妖伏魔、抑强扶弱、统一各部**的业绩为主线，**主要依靠说唱艺人口耳相传，至今仍在活态传承**。它有一百多部、一百多万诗行，被认为是**世界上最长的史诗**。**2009年“格萨（斯）尔”史诗传统入选联合国教科文组织人类非物质文化遗产代表作名录**，与《江格尔》《玛纳斯》并称**中国三大英雄史诗**。","pts":["藏族英雄史诗，流传藏、蒙、土等族","格萨尔降妖伏魔，说唱艺人活态传承，世界最长","2009年入选人类非遗，中国三大史诗之一"],"mem":"数字口诀“百部百万行，世界最长”。画面：说唱艺人戴帽弹唱，相传在梦中得到格萨尔的“神授”，一人能唱几十部。记地名：格萨尔是“岭国”之王，这个“岭”指藏地的岭国，与岭南无关。","mix":"蒙古族称《格斯尔》，另有蒙古族卫拉特的《江格尔》，二者不是同一部；《玛纳斯》属柯尔克孜族。三大史诗中只有《格萨尔》常与“世界最长”连用。","mcq":[{"q":"关于《格萨尔王传》，下列说法正确的是","o":["主要靠说唱艺人口耳相传","是柯尔克孜族史诗","以江格尔汗为主人公","是文人案头创作的长诗"],"a":0,"w":"《格萨尔王传》是藏族英雄史诗，至今活态传承。"},{"q":"《格萨尔王传》中格萨尔是哪里的国王","o":["宝木巴","香巴拉","楼兰","岭国"],"a":3,"w":"宝木巴是《江格尔》中的理想家园。"}],"rel":[{"t":"中国三大英雄史诗","n":"三大史诗之一"},{"t":"《江格尔》","n":"同为三大史诗"},{"t":"《玛纳斯》","n":"同为三大史诗"},{"t":"人类非遗代表作中国项目","n":"2009年入选"},{"t":"荷马史诗","n":"活态口传史诗对照"}],"more":"2009年，“格萨（斯）尔”史诗传统入选联合国教科文组织人类非物质文化遗产代表作名录。\n说唱艺人是传承主体，蒙古族称《格斯尔》。"},{"id":"b09-020","t":"赫拉克利特","cid":"09e","p":1,"kind":"人物","exam":["2025选择"],"alias":["以弗所的赫拉克利特","万物皆流","逻各斯"],"one":"以弗所哲学家，火是万物本原，“人不能两次踏进同一条河流”。","ans":"赫拉克利特（约前540至约前480）是**古希腊以弗所的哲学家**，**朴素辩证法的代表**。他认为**火是万物的本原**，世界是“一团永恒的活火”，属**朴素唯物主义**；提出**“万物皆流”“人不能两次踏进同一条河流”**，强调世界处于不断变化和对立斗争之中，属**朴素辩证法**；并提出**“逻各斯”**概念，指万物变化所遵循的规律。他是古希腊辩证思想的开创者，列宁称其为辩证法的奠基人之一，对黑格尔辩证法有直接影响。","pts":["以弗所哲学家，火是万物本原","万物皆流，人不能两次踏进同一条河流","逻各斯：变化背后的规律"],"mem":"一火一河一逻各斯：本原说“火”（唯物），变化说“河”（辩证），规律说“逻各斯”。两条分类轴要分清：火属朴素唯物主义，河流属朴素辩证法。画面：同一条河，第二次踏进已经是新的水。","mix":"2025选择题考了这点：本原说和辩证法属不同轴。“人不能两次踏进同一条河流”常被误说成孔子或老子的话；孔子“逝者如斯夫”意思相近但思想不同。","mcq":[{"q":"提出“人不能两次踏进同一条河流”的哲学家是","o":["泰勒斯","德谟克利特","毕达哥拉斯","赫拉克利特"],"a":3,"w":"赫拉克利特，“万物皆流”，属朴素辩证法。"},{"q":"赫拉克利特认为万物的本原是","o":["火","水","数","原子"],"a":0,"w":"火为本原；水是泰勒斯，数是毕达哥拉斯，原子是德谟克利特。"}],"rel":[{"t":"朴素唯物主义","n":"火为本原属此类"},{"t":"辩证法","n":"万物皆流属朴素辩证法"},{"t":"泰勒斯","n":"水为本原"},{"t":"德谟克利特","n":"原子论"},{"t":"老子","n":"中国朴素辩证法对照"}],"more":"人不能两次踏进同一条河流。\n这个世界是一团永恒的活火，在一定分寸上燃烧，在一定分寸上熄灭。"},{"id":"b09-021","t":"泰勒斯","cid":"09e","p":2,"kind":"人物","alias":["米利都的泰勒斯","哲学之父","泰勒士","泰利斯"],"one":"米利都学派创始人，“哲学之父”，主张水是万物本原。","ans":"泰勒斯（约前624–约前546）是**古希腊米利都人**，**米利都学派创始人**，被称为**“哲学之父”**。他认为**水是万物的本原**，万物由水生成又复归于水，是**用自然本身解释自然**的开端，标志着哲学从神话中分离。据传他还预测过前585年的日食，是希腊七贤之一。他的观点属**朴素唯物主义**，开启了西方哲学追问**本原**的传统。","pts":["米利都学派创始人，哲学之父","水是万物本原","朴素唯物主义，哲学脱离神话"],"mem":"“泰”字开头，第一个。本原口诀：“泰水，阿气，赫火，毕数，德原子”：泰勒斯水、阿那克西美尼气、赫拉克利特火、毕达哥拉斯数、德谟克利特原子。","mix":"水是泰勒斯，气是阿那克西美尼，无定是阿那克西曼德；三人同属米利都学派。“哲学之父”常指泰勒斯，“历史之父”是希罗多德，“医学之父”是希波克拉底。","mcq":[{"q":"主张“水是万物本原”的哲学家是","o":["赫拉克利特","毕达哥拉斯","泰勒斯","德谟克利特"],"a":2,"w":"泰勒斯以水为本原；赫拉克利特为火，毕达哥拉斯为数，德谟克利特为原子。"}],"rel":[{"t":"米利都学派","n":"所创学派"},{"t":"本原（始基）","n":"追问的核心问题"},{"t":"朴素唯物主义","n":"其思想性质"},{"t":"赫拉克利特","n":"另一本原学说代表"}],"exam":[]},{"id":"b09-022","t":"德谟克利特","cid":"09e","p":2,"kind":"人物","alias":["原子论","德谟克里特","阿布德拉的德谟克利特"],"one":"提出原子论：万物由原子与虚空构成。","ans":"德谟克利特（约前460–约前370）是**古希腊哲学家**，生于色雷斯的阿布德拉，师承**留基伯**，**原子论**的集大成者。他认为**万物由不可分割的原子和虚空构成**，原子数量无限，在大小、形状、次序上各不相同，原子在虚空中运动、结合与分离形成万物，灵魂也由原子构成。他的学说属**朴素唯物主义**，对后来的伊壁鸠鲁、近代原子学说有重要影响。","pts":["原子与虚空构成万物","师承留基伯，集大成","朴素唯物主义，影响伊壁鸠鲁"],"mem":"“原子”本义是“不可再分”（a-tom）。画面：无数细小的颗粒在空中飞舞，碰在一起就成了万物。德谟克利特常与赫拉克利特成对记：一个原子，一个火。","mix":"古代原子论不是现代物理的原子，现代原子可再分；德谟克利特（原子）与赫拉克利特（火、流变）名字相近，不要混。","mcq":[{"q":"主张万物由原子和虚空构成的哲学家是","o":["赫拉克利特","泰勒斯","巴门尼德","德谟克利特"],"a":3,"w":"原子论由留基伯创立，德谟克利特发展完成。"}],"rel":[{"t":"本原（始基）","n":"其本原学说"},{"t":"朴素唯物主义","n":"学说性质"},{"t":"赫拉克利特","n":"名字相近，易混"},{"t":"泰勒斯","n":"最早的本原学说者"}],"exam":[]},{"id":"b09-023","t":"希波战争","cid":"09b","p":2,"kind":"事件","alias":["希波战争","波希战争","希波战争史"],"one":"前5世纪前期希腊城邦抗击波斯，马拉松、温泉关、萨拉米斯。","ans":"希波战争是**前5世纪前期希腊城邦抵抗波斯帝国入侵的战争**，希罗多德《历史》以此为主题。主要战役有**前490年马拉松战役**，雅典击败波斯军；**前480年温泉关战役**，斯巴达王列奥尼达率军殉国；同年**萨拉米斯海战**，希腊海军在地米斯托克利指挥下大胜，次年又取得普拉提亚战役胜利。战争以**希腊获胜**告终，雅典声望大增，随后组建**提洛同盟**，为雅典称霸与伯罗奔尼撒战争埋下伏笔。","pts":["前5世纪前期，希腊对波斯","马拉松、温泉关、萨拉米斯","希腊胜，雅典借提洛同盟称霸"],"mem":"战役顺序：马（490）、温（480）、萨（480）、普（479），口诀“马温萨普”。记结果：弱小的城邦联盟赢了庞大的帝国，所以雅典自信膨胀，后来才和斯巴达翻脸。","mix":"希波战争由希罗多德记述，伯罗奔尼撒战争由修昔底德记述，两位史家与两场战争不要错配；马拉松长跑的传说出自马拉松战役。","mcq":[{"q":"“马拉松战役”发生于下列哪场战争期间","o":["伯罗奔尼撒战争","特洛伊战争","布匿战争","希波战争"],"a":3,"w":"马拉松战役（前490）是希波战争中雅典击败波斯的战役。"}],"rel":[{"t":"马拉松战役","n":"首次重大胜利"},{"t":"希罗多德","n":"记述此战的史家"},{"t":"提洛同盟","n":"战后雅典组建的同盟"},{"t":"波斯帝国","n":"战争另一方"}],"more":"温泉关战役：斯巴达王列奥尼达率三百斯巴达人及盟军守隘口，全部战死。","exam":[]},{"id":"b09-024","t":"雅典民主","cid":"09a","p":1,"kind":"制度","alias":["雅典民主制","雅典民主政治","古希腊民主"],"one":"雅典经梭伦、克里斯提尼改革，在伯里克利时代达到鼎盛的公民直接民主。","ans":"雅典民主是**古希腊雅典城邦的公民直接民主制度**。**前594年梭伦改革按财产划分公民等级、废除债务奴隶制**；**前508年克里斯提尼改革按地域划分选区，设五百人议事会，并创立陶片放逐法**；**前5世纪中叶伯里克利时代**，公民大会成为最高权力机关，官职多由抽签产生并发给津贴，民主达到鼎盛。这一制度为**西方民主政治提供了最早的范例**，但**只有成年男性公民享有权利**，妇女、奴隶和外邦人被排除在外。","pts":["梭伦改革（前594）：财产分等级，废债务奴隶","克里斯提尼改革（前508）：地域选区，陶片放逐法","伯里克利时代鼎盛；公民范围有限"],"mem":"三个人物三个年份：梭伦 594（财产说话），克里斯提尼 508（地域说话），伯里克利 5世纪中叶（人人可当官）。口诀“梭产、克域、伯里全民”：梭伦看财产，克里斯提尼看地域，伯里克利拿津贴。局限用“三类人没票”收尾：妇女、奴隶、外邦人。","mix":"陶片放逐法的创立传统上归于克里斯提尼，首次实际使用在前487年左右。雅典是直接民主，现代国家多为代议制。","mcq":[{"q":"雅典前594年废除债务奴隶制、按财产划分公民等级的改革者是","o":["克里斯提尼","梭伦","伯里克利","德拉古"],"a":1,"w":"梭伦改革按财产划分等级并废除债务奴隶制；克里斯提尼改革在前508年。"},{"q":"陶片放逐法的创立者通常认为是","o":["伯里克利","梭伦","庇西特拉图","克里斯提尼"],"a":3,"w":"传统上认为陶片放逐法由克里斯提尼改革时创立，用以防止僭主政治。"}],"rel":[{"t":"梭伦改革","n":"雅典民主奠基"},{"t":"陶片放逐法","n":"防范僭主的制度"},{"t":"伯里克利","n":"民主鼎盛时的领袖"},{"t":"城邦","n":"民主所在的政治形态"},{"t":"三权分立","n":"西方后世分权思想"}],"more":"伯里克利名言（修昔底德所记《葬礼演说》）：我们的制度之所以被称为民主政治，是因为政权在全体公民手中。","exam":[]},{"id":"b09-025","t":"斯巴达","cid":"09a","p":2,"kind":"制度","alias":["斯巴达城邦","拉栖第梦","来库古立法"],"one":"伯罗奔尼撒半岛的军事化城邦，双王制，奴役黑劳士。","ans":"斯巴达是**古希腊伯罗奔尼撒半岛南部的城邦**，传说由**来库古**立法，实行军事贵族寡头统治。政体有**双王制**、长老会和监察官，公民男子七岁起接受国家军事训练，终身以作战为业；农业劳动由被征服的**黑劳士**承担，他们属于国家所有的奴隶。斯巴达领导**伯罗奔尼撒同盟**，在**伯罗奔尼撒战争**中击败雅典，前371年又败于底比斯，霸权随之衰落。它与重商、重文化的民主雅典形成对照。","pts":["来库古立法，双王制与长老会","全民军事化，黑劳士为国有奴隶","领导伯罗奔尼撒同盟，战胜雅典"],"mem":"对照记：雅典民主靠公民大会，斯巴达军营靠双王。一句话：“来库古立法，两王一老，黑劳士种地，公民只管打仗。”电影《300》里的列奥尼达就是斯巴达王，守温泉关。","mix":"黑劳士是国有奴隶，不是斯巴达公民；罗马的斯巴达克起义是奴隶起义，与斯巴达城邦只是名称相近，不要混。","mcq":[{"q":"古希腊城邦斯巴达的立法者传说是","o":["梭伦","克里斯提尼","来库古","伯里克利"],"a":2,"w":"来库古相传为斯巴达立法者；梭伦、克里斯提尼、伯里克利都是雅典人。"}],"rel":[{"t":"雅典民主","n":"与斯巴达对照的另一模式"},{"t":"伯罗奔尼撒战争","n":"斯巴达击败雅典的战争"},{"t":"提洛同盟","n":"雅典同盟，对手为伯罗奔尼撒同盟"},{"t":"斯巴达克起义","n":"名称相近，易混"}],"more":"斯巴达人以简朴著称，英语 spartan 即由此而来，意为简朴刻苦。","exam":[]},{"id":"b09-026","t":"亚历山大大帝","cid":"09b","p":2,"kind":"人物","alias":["亚历山大三世","亚历山大","马其顿的亚历山大","亚历山大大帝东征"],"one":"马其顿国王，亚里士多德之徒，东征建大帝国，开启希腊化时代。","ans":"亚历山大大帝（前356–前323）是**马其顿国王**，腓力二世之子，少年时受教于**亚里士多德**。他前336年继位，**前334年起东征**，击败波斯，征服埃及，远达印度河流域，建立**横跨欧亚非的大帝国**。他在各地兴建以自己命名的城市，其中**埃及的亚历山大里亚**最著名。前323年他病逝于巴比伦，帝国随即分裂，但希腊文化与东方文化的交融由此展开，进入**希腊化时代**。","pts":["马其顿国王，亚里士多德的学生","前334年东征，灭波斯帝国","开启希腊化时代，死后帝国分裂"],"mem":"师承链：苏格拉底，柏拉图，亚里士多德，亚历山大，一路“师徒接力”。年份：前334 开始东征，前323 去世，一共十来年就打下三大洲。","mix":"亚历山大是马其顿人，不是雅典人；其父腓力二世先征服希腊城邦。他死后分裂出托勒密（埃及）、塞琉古（西亚）、安提柯（马其顿）三大王国。","mcq":[{"q":"亚历山大大帝的老师是","o":["柏拉图","亚里士多德","苏格拉底","伊壁鸠鲁"],"a":1,"w":"亚历山大少年时由亚里士多德教导；柏拉图是亚里士多德的老师。"}],"rel":[{"t":"希腊化时代","n":"他东征开启的时代"},{"t":"亚里士多德","n":"老师"},{"t":"亚历山大里亚与亚历山大图书馆","n":"他所建名城"},{"t":"波斯帝国","n":"被他征服的帝国"}],"exam":[]},{"id":"b09-027","t":"奥林匹克运动会","cid":"09a","p":2,"kind":"常识","alias":["古代奥运会","奥运会","现代奥运会","奥林匹亚"],"one":"古代前776年起在奥林匹亚祭宙斯，现代1896年雅典首届。","ans":"奥林匹克运动会起源于**古希腊**，据传**始于前776年**，每四年在**奥林匹亚**举行一次，用以祭祀**宙斯**，比赛期间各城邦停战。古代奥运会于公元4世纪末被罗马皇帝废止。19世纪末法国人**顾拜旦**倡导复兴，1894年成立国际奥委会，**1896年在雅典举办第一届现代奥运会**。现代奥运会保留四年一届的传统，并成为世界性的综合体育盛会。","pts":["古代前776年，奥林匹亚，祭宙斯","顾拜旦倡导，1894年国际奥委会成立","1896年雅典首届现代奥运会"],"mem":"两个年份各挂一个地点：776 对奥林匹亚，1896 对雅典。顾拜旦是法国人，却把首届放回希腊，是向古希腊致敬。","mix":"古代奥运会地点奥林匹亚是祭宙斯的圣地，不是雅典；首届现代奥运会才在雅典。奥林匹斯山是众神所居，与奥林匹亚是两个地方。","mcq":[{"q":"首届现代奥林匹克运动会举办于","o":["1896年雅典","1900年巴黎","1894年奥林匹亚","1908年伦敦"],"a":0,"w":"首届现代奥运会1896年在雅典举行，顾拜旦倡导。"}],"rel":[{"t":"第一届现代奥运会","n":"同一史实的专条"},{"t":"马拉松战役","n":"马拉松赛跑由此而来"},{"t":"宙斯","n":"古代奥运会祭祀对象"},{"t":"中国首次参加奥运会","n":"中外奥运史对照"}],"exam":[]},{"id":"b09-028","t":"寓言","cid":"09c","p":2,"kind":"概念","exam":["2018名解"],"alias":["寓言","寓言体裁","《庄子·寓言》"],"one":"借故事或拟人形象说明道理的短小体裁。","ans":"寓言是**借假托的故事或拟人化的形象说明道理、给人教训的文学体裁**，篇幅短小，常带有讽刺和劝诫意味。西方寓言以**古希腊《伊索寓言》**为源头，名篇有《龟兔赛跑》《农夫和蛇》《狐狸和葡萄》，后来有**法国拉封丹**、**俄国克雷洛夫**继承发展。中国先秦诸子善用寓言说理，**《庄子》**《韩非子》中有“守株待兔”“刻舟求剑”等，“寓言”一词即出自**《庄子·寓言》**。","pts":["借故事说理的短小体裁","西方源头：伊索，后有拉封丹、克雷洛夫","中国先秦诸子，寓言出自庄子"],"mem":"三个关键词：体裁定义、伊索（西）、庄子（中）。中西各记一个名篇：《龟兔赛跑》对《守株待兔》。“寓”是寄托，把道理寄放在故事里。","mix":"“寓言”这个词最早见于《庄子·寓言》，但最早的寓言作家在西方是伊索；寓言与童话、神话不同，重在说理而非叙事本身。","mcq":[{"q":"“寓言”一词最早出自","o":["《伊索寓言》","《庄子》","《韩非子》","《论语》"],"a":1,"w":"“寓言”一词出自《庄子·寓言》；《韩非子》也有大量寓言，但词出于《庄子》。"}],"rel":[{"t":"伊索","n":"西方寓言源头"},{"t":"世界四大寓言家","n":"同类合称"},{"t":"《庄子》","n":"中国寓言重要来源"},{"t":"庄子名篇与寓言","n":"中国寓言实例"}]},{"id":"b09-029","t":"贺拉斯","cid":"09g","p":1,"kind":"人物","exam":["2018名解"],"alias":["贺拉修斯"],"one":"古罗马诗人、文论家，《诗艺》作者，提出“寓教于乐”。","ans":"贺拉斯（前65—前8）是**古罗马奥古斯都时代的诗人、文艺理论家**，与维吉尔、奥维德并称**古罗马三大诗人**。他的诗作有《歌集》《讽刺诗集》《书札》，“及时行乐”（carpe diem）出自其诗。书信体的**《诗艺》**是继亚里士多德《诗学》之后最重要的古典文论，提出**“寓教于乐”**和**“合式”（得体）**原则，主张学习古希腊。该书深刻影响了文艺复兴和**法国古典主义**，布瓦洛的《诗的艺术》即承其余绪。","pts":["古罗马奥古斯都时代诗人，三大诗人之一","《诗艺》：寓教于乐、合式","影响文艺复兴与法国古典主义"],"mem":"对比记：亚里士多德《诗学》讲“模仿+净化”，贺拉斯《诗艺》讲“寓教于乐+合式”。画面：罗马诗人写了一封长信（书信体）教皮索父子怎样写诗，这封信就是《诗艺》。三大诗人通行顺序“维吉尔、贺拉斯、奥维德”。","mix":"《诗学》（亚里士多德，希腊）、《诗艺》（贺拉斯，罗马）、《诗的艺术》（布瓦洛，17世纪法国）三书名相近，选择题常拿来互换；《埃涅阿斯纪》属维吉尔，《变形记》属奥维德。","mcq":[{"q":"“寓教于乐”的提出者是","o":["亚里士多德","贺拉斯","布瓦洛","维吉尔"],"a":1,"w":"见贺拉斯《诗艺》。"},{"q":"下列作品中，作者是贺拉斯的是","o":["《埃涅阿斯纪》","《变形记》","《诗学》","《诗艺》"],"a":3,"w":"《埃涅阿斯纪》维吉尔，《变形记》奥维德，《诗学》亚里士多德。"}],"rel":[{"t":"《诗艺》","n":"代表文论"},{"t":"古罗马三大诗人","n":"同列者维吉尔、奥维德"},{"t":"《诗学》","n":"前驱文论"},{"t":"布瓦洛《诗的艺术》","n":"后世继承者"}],"more":"作品：《歌集》《讽刺诗集》《书札》（含《诗艺》）。\n名句：抓住今天（carpe diem）。｜《歌集》"},{"id":"b09-030","t":"原始印欧语","cid":"09a","p":2,"kind":"概念","exam":["2019名解"],"alias":["PIE","印欧语","印欧祖语"],"one":"语言学家构拟的印欧语系共同祖语，无文字记录。","ans":"原始印欧语是**语言学家用历史比较法构拟出的印欧语系共同祖语**，没有文字记录，一般推测使用于约**公元前4000年**前后，年代与发源地均有争议。它的后代包括希腊语、拉丁语及罗曼语族、**日耳曼语族**（英语、德语）、斯拉夫语族、**印度-伊朗语族**（梵语、波斯语）等。**1786年**英国学者**威廉·琼斯**指出梵语与希腊语、拉丁语同源，推动了**历史比较语言学**的建立。","pts":["构拟的共同祖语，无文字","后代：希腊语、拉丁语、日耳曼、斯拉夫、印度-伊朗","琼斯1786年指出梵语同源"],"mem":"三个关键词连成线：构拟（没人见过）、分支（英德法俄印波斯同一家）、琼斯（1786 发现梵语像希腊拉丁）。英语 mother、拉丁语 mater、梵语 matar 长得像，就是同源的活例子。","mix":"汉语属汉藏语系，不在印欧语系内；原始印欧语是推测出来的，不是某个有文献的古代语言（梵语、希腊语、拉丁语都是有文献的后代语言）。","mcq":[{"q":"最早指出梵语与希腊语、拉丁语同源的英国学者是","o":["索绪尔","乔姆斯基","格林兄弟","威廉·琼斯"],"a":3,"w":"琼斯1786年的论断是历史比较语言学的起点；索绪尔、乔姆斯基是后来的语言学家。"}],"rel":[{"t":"拉丁语","n":"印欧语系重要分支"},{"t":"索绪尔","n":"现代语言学奠基人"},{"t":"乔姆斯基","n":"语言学另一学派代表"},{"t":"古希腊文明","n":"希腊语属印欧语系"}],"more":"例证：英语 father，拉丁语 pater，希腊语 pater，梵语 pitar，对应整齐。"},{"id":"b09-031","t":"宿命论","cid":"09d","p":2,"kind":"概念","exam":["2019名解"],"alias":["命定论","天命论","宿命"],"one":"认为命运由神意或天命预先决定、人力无法改变。","ans":"宿命论是**认为人的命运和世间一切事件由神意、天命或命运预先决定、人力无法改变的观点**。古希腊悲剧如**《俄狄浦斯王》**体现了命运观，中国有“**死生有命，富贵在天**”之说，宗教中有**加尔文的预定论**。宿命论**否认人的主观能动性**。它与**决定论**不同：决定论强调事物受因果规律支配，不必然否定人的作用。","pts":["预先决定，无法改变","希腊命运悲剧、中国天命观","区别于决定论，否认主观能动性"],"mem":"一句话：宿命论是“命已写好，你改不了”。区分决定论：决定论说“有因必有果”，宿命论说“不管怎样结果都一样”。例子：俄狄浦斯越躲越应验。","mix":"决定论承认规律与因果，宿命论则否认人的作用；“预定论”是加尔文宗教教义，近似宿命论但属神学术语。","mcq":[{"q":"下列作品最能体现古希腊命运观的是","o":["《西厢记》","《俄狄浦斯王》","《堂吉诃德》","《哈姆雷特》"],"a":1,"w":"《俄狄浦斯王》中神谕无论如何躲避都应验，是命运悲剧的典型。"}],"rel":[{"t":"《俄狄浦斯王》","n":"命运观典型"},{"t":"俄狄浦斯","n":"命运悲剧主角"},{"t":"索福克勒斯","n":"剧作家"},{"t":"古希腊三大悲剧家","n":"命运悲剧传统"}]},{"id":"b09-032","t":"二元论","cid":"09h","p":1,"kind":"概念","exam":["2019名解"],"alias":["心物二元论"],"one":"主张物质与精神是两个独立本原的学说，笛卡尔为代表。","ans":"二元论是**认为世界有物质和精神两个彼此独立的本原的哲学学说**，以17世纪法国哲学家**笛卡尔的“心物二元论”**为代表。笛卡尔把世界分为**广延的物质实体和思维的精神实体**，二者互不依赖，人是两者的结合。二元论**介于唯物主义与唯心主义之间**，试图调和两者，但在解释心与身如何相互作用时陷入困难，最终**倾向唯心主义**，也引发了心身问题的长期争论，斯宾诺莎、莱布尼茨等人的学说即是对它的回应。宗教上也指善恶二元的观念，如古波斯的琐罗亚斯德教、摩尼教。","pts":["物质与精神两个独立本原","笛卡尔心物二元论，调和唯物与唯心","最终倾向唯心主义；宗教上指善恶二元"],"mem":"画面：一个人住两个房间，一间装身体（有广延，占空间），一间装灵魂（会思维），中间那扇门，笛卡尔猜在松果腺。对比：唯物论“只要物质”，唯心论“只要精神”，二元论“两个都要”。","mix":"哲学上的二元论（物质/精神）与宗教上的善恶二元论（琐罗亚斯德教、摩尼教）同名异义；也不要与辩证法的“对立统一”混淆。","mcq":[{"q":"提出“心物二元论”的哲学家是","o":["洛克","休谟","黑格尔","笛卡尔"],"a":3,"w":"笛卡尔区分思维实体与广延实体。"},{"q":"二元论认为世界的本原是","o":["只有物质","只有精神","水","物质和精神两个并立的实体"],"a":3,"w":"二元论主张物质与精神各自独立，并列为本原。"}],"rel":[{"t":"笛卡尔","n":"代表人物"},{"t":"唯物主义与唯心主义","n":"二元论介于两者之间"},{"t":"经验论与唯理论","n":"笛卡尔属唯理论"},{"t":"斯宾诺莎与莱布尼茨","n":"对二元论的回应"}],"more":"笛卡尔：“我思故我在”；《谈谈方法》《第一哲学沉思集》。"},{"id":"b09-033","t":"经验论与唯理论","cid":"09h","p":1,"kind":"流派","alias":["经验主义","唯理主义","经验论","唯理论"],"one":"近代认识论两派：经验论重感觉经验，唯理论重理性推理，康德调和。","ans":"经验论与唯理论是**17至18世纪欧洲近代哲学认识论的两大派别**，争论知识的来源。**经验论认为知识来源于感觉经验**，代表人物是英国的培根、霍布斯、洛克（提出“白板说”）、贝克莱和休谟；**唯理论认为可靠的知识来自理性的演绎推理**，代表人物是法国的笛卡尔（“我思故我在”）、荷兰的斯宾诺莎和德国的莱布尼茨。两派各执一端，经验论发展到休谟走向怀疑论。**康德在《纯粹理性批判》中试图调和两派**，开启德国古典哲学。","pts":["近代认识论两派：感觉经验与理性演绎","经验论：培根、霍布斯、洛克、贝克莱、休谟","唯理论：笛卡尔、斯宾诺莎、莱布尼茨；康德调和"],"members":[["培根","英国经验论始祖，归纳法"],["霍布斯","《利维坦》"],["洛克","“白板说”"],["贝克莱","“存在就是被感知”"],["休谟","怀疑论，《人性论》"],["笛卡尔","“我思故我在”，天赋观念"],["斯宾诺莎","荷兰，《伦理学》"],["莱布尼茨","德国，单子论"]],"mem":"画面：英国人“眼见为实”（岛国重经验：培、霍、洛、贝、休），大陆人“想通为准”（像几何证明一样推理：笛、斯、莱）。首字串“培霍洛贝休”“笛斯莱”为自编。对立的一对关键词：洛克“白板”对笛卡尔“天赋观念”。","mix":"贝克莱属经验论，同时是主观唯心主义；霍布斯有时也被归入唯物主义；康德不属任何一派，他是调和者。","mcq":[{"q":"下列哲学家中，属于大陆唯理论的是","o":["洛克","贝克莱","莱布尼茨","休谟"],"a":2,"w":"莱布尼茨与笛卡尔、斯宾诺莎同属唯理论。"},{"q":"提出“白板说”的哲学家是","o":["洛克","笛卡尔","培根","斯宾诺莎"],"a":0,"w":"洛克认为心灵如同白板，知识来自经验。"}],"rel":[{"t":"弗朗西斯·培根","n":"经验论始祖"},{"t":"笛卡尔","n":"唯理论代表"},{"t":"洛克","n":"白板说"},{"t":"休谟","n":"经验论的怀疑论"},{"t":"康德","n":"调和两派"}],"more":"《新工具》（培根）｜《人类理解论》（洛克）｜《人性论》（休谟）｜《谈谈方法》（笛卡尔）｜《伦理学》（斯宾诺莎）｜《单子论》（莱布尼茨）","exam":[]},{"id":"b09-034","t":"辩证法","cid":"09e","p":1,"kind":"概念","exam":["2019名解"],"alias":["唯物辩证法","朴素辩证法","唯心主义辩证法"],"one":"关于普遍联系和永恒发展的学说，与形而上学相对。","ans":"辩证法是**关于普遍联系和永恒发展的学说**，与**孤立、静止看问题的形而上学**相对。古代有**古希腊赫拉克利特、中国《老子》（“反者道之动”）和《易经》的朴素辩证法**；近代**黑格尔建立了唯心主义辩证法体系**；**马克思、恩格斯批判继承黑格尔，创立唯物辩证法**，概括出**对立统一、质量互变、否定之否定**三大规律，成为马克思主义哲学的核心方法，也是分析矛盾、把握事物发展的基本思维方式。","pts":["普遍联系与永恒发展，对立于形而上学","赫拉克利特、老子，黑格尔体系","唯物辩证法三大规律"],"mem":"三个阶段：朴素辩证法（赫拉克利特、老子）→ 唯心辩证法（黑格尔）→ 唯物辩证法（马克思、恩格斯）。三大规律口诀“对质否”：对立统一、质量互变、否定之否定。类比记：黑格尔把辩证法“倒着站”，马克思把它“正过来”。","mix":"古希腊“辩证法”原意是对话论辩的技艺（如苏格拉底的问答），与现代哲学含义有别；黑格尔辩证法是唯心的，马克思主义的是唯物的。","mcq":[{"q":"建立唯心主义辩证法体系的哲学家是","o":["黑格尔","费尔巴哈","康德","赫拉克利特"],"a":0,"w":"黑格尔建立了唯心主义辩证法体系，马克思恩格斯批判继承后创立唯物辩证法。"},{"q":"下列不属于唯物辩证法三大规律的是","o":["对立统一规律","质量互变规律","否定之否定规律","正反合规律"],"a":3,"w":"“正反合”是对黑格尔辩证法的通俗概括，不属于唯物辩证法三大规律。"}],"rel":[{"t":"赫拉克利特","n":"古希腊朴素辩证法"},{"t":"黑格尔","n":"唯心主义辩证法"},{"t":"德国古典哲学","n":"辩证法的近代形态"},{"t":"老子","n":"中国朴素辩证法"},{"t":"朴素唯物主义","n":"常与朴素辩证法结合"}],"more":"老子：反者道之动。祸兮福之所倚，福兮祸之所伏。｜《道德经》"},{"id":"b09-035","t":"希腊化时代","cid":"09b","p":2,"kind":"概念","alias":["希腊化","希腊化文明"],"one":"前334年亚历山大东征至前30年，希腊与东方文化交融。","ans":"希腊化时代指**前334年亚历山大东征至前30年罗马灭托勒密埃及**的时期，是**希腊文化与东方文化交融**的时代。文化中心转到埃及的**亚历山大里亚**，那里有**亚历山大图书馆**和灯塔。科学上有**欧几里得几何**、**阿基米德力学**；哲学上有**斯多葛学派**和**伊壁鸠鲁学派**；希伯来《圣经》在此译成希腊文，即**七十子译本**。希腊文化因此传播到西亚和北非，并为罗马所继承。","pts":["前334至前30年，亚历山大东征到罗马灭埃及","中心亚历山大里亚","科学与哲学：欧几里得、阿基米德、斯多葛"],"mem":"起止两个数：334（东征）到 30（托勒密埃及亡）。一个地点：亚历山大里亚。三个成就：数学（欧几里得）、力学（阿基米德）、哲学转向个人（斯多葛、伊壁鸠鲁）。","mix":"希腊化时代不同于古典时代（前5至前4世纪，雅典城邦为中心）；希腊化时代的中心不在雅典，而在亚历山大里亚等东方新城。","mcq":[{"q":"下列属于希腊化时代成就的是","o":["《伊利亚特》成书","《十二铜表法》颁布","七十子译本","《神曲》创作"],"a":2,"w":"七十子译本在托勒密埃及的亚历山大里亚译成，是希腊化时期的标志性成果。"}],"rel":[{"t":"亚历山大大帝","n":"开启者"},{"t":"亚历山大里亚与亚历山大图书馆","n":"学术中心"},{"t":"斯多葛学派","n":"希腊化哲学"},{"t":"七十子译本","n":"希伯来圣经译成希腊文"}],"exam":[]},{"id":"b09-036","t":"理念论","cid":"09f","p":2,"kind":"概念","alias":["理念说","相论","形式论","理型"],"one":"柏拉图哲学核心：永恒的理念才是真实存在，个别事物只是分有理念。","ans":"理念论是**柏拉图哲学的核心学说**。他认为可感的个别事物变动不居、有生有灭，只是**理念（形式）的摹本**，永恒不变的理念才是真实的存在。个别的床、马、美的事物都因**“分有”**相应的理念而成为其所是，众理念之上还有最高的“善”的理念。这一学说在《理想国》中以**洞穴比喻**加以说明，把世界分成可感世界与理念世界，开创了西方哲学的**唯心主义传统**，亚里士多德则批评它使理念与事物相分离。","pts":["可感事物变动，理念永恒才是真实","个别事物分有理念，是理念的摹本","《理想国》洞穴比喻；亚里士多德批评"],"mem":"画面：一张画出来的床是木匠床的影子，木匠床又是“床的理念”的影子。记法：现实是影子，理念是本体。“理念”不是个人理想，而是客观独立的原型，别按字面理解。","mix":"“理念”在日常中指想法，柏拉图的 idea 指永恒的原型（形式）；理念论属客观唯心主义，与德谟克利特的原子论（唯物）相对。","mcq":[{"q":"关于柏拉图“理念论”的表述，正确的是","o":["万物的本原是水","个别事物分有永恒的理念","一切知识来自感觉经验","世界是不断燃烧的火"],"a":1,"w":"柏拉图认为个别事物“分有”理念，理念永恒不变；水、火分别是泰勒斯、赫拉克利特的主张。"}],"rel":[{"t":"柏拉图","n":"理念论创立者"},{"t":"洞穴比喻","n":"理念论的形象说明"},{"t":"亚里士多德","n":"批评理念论"}],"exam":[]},{"id":"b09-037","t":"洞穴比喻","cid":"09f","p":2,"kind":"概念","alias":["洞穴寓言","洞穴隐喻","柏拉图洞穴"],"one":"《理想国》第七卷的寓言，比喻从现象走向真理的认识与教育过程。","ans":"洞穴比喻出自**柏拉图《理想国》第七卷**，是阐释理念论的著名寓言。一群囚徒自幼被锁在洞穴中，只能面对洞壁，把身后火光投下的**影子**当作真实。其中一人挣脱锁链，走出洞穴，在强光中最终看见**太阳**，即“善”的理念。他回洞告知同伴，却不被相信。这一寓言比喻**从现象到真理的认识过程**，说明教育是引导灵魂转向，也含有哲学家应治理城邦的意思。","pts":["出自《理想国》第七卷","囚徒把洞壁影子当真实，走出洞见太阳","比喻认识上升与教育作用"],"mem":"画面记忆：看电影。囚徒在洞里看的是“皮影戏”，走出洞才见到真人和太阳。影子对应可感现象，洞外对应理念世界，太阳对应“善”。","mix":"培根的“四假象”里有“洞穴假象”，指个人局限，与柏拉图洞穴比喻同名而不同义。","mcq":[{"q":"“洞穴比喻”出自柏拉图的","o":["《理想国》","《申辩篇》","《会饮篇》","《斐多篇》"],"a":0,"w":"洞穴比喻见《理想国》第七卷；《申辩篇》《斐多篇》记苏格拉底之死。"}],"rel":[{"t":"理念论","n":"比喻所要说明的学说"},{"t":"《理想国》","n":"出处"},{"t":"弗朗西斯·培根","n":"“洞穴假象”同名异义"}],"exam":[]},{"id":"b09-038","t":"净化说","cid":"09d","p":2,"kind":"概念","alias":["卡塔西斯","陶冶说","宣泄说","净化"],"one":"亚里士多德《诗学》：悲剧引起怜悯与恐惧使情感净化。","ans":"净化说是**亚里士多德在《诗学》中提出的悲剧理论**。他认为悲剧通过**引起观众的怜悯和恐惧**，使这类情感得到**净化**（希腊语 **katharsis**，也译“陶冶”“宣泄”），观众由此获得愉悦和心理平衡。这一说法回应了**柏拉图**认为悲剧助长情感、败坏公民的批评，肯定了**悲剧的社会功能**，成为西方悲剧理论和戏剧教育的重要基础。","pts":["亚里士多德《诗学》提出","悲剧引起怜悯和恐惧","情感得到净化（卡塔西斯）"],"mem":"关键词“怜悯、恐惧、净化”，三个词一句话：看悲剧，怜悯恐惧一发泄，心里反而干净。柏拉图赶走诗人，亚里士多德为悲剧辩护。","mix":"《诗学》另一核心是模仿说；净化说谈悲剧效果，模仿说谈艺术本质。净化不是“教化道德”，重点是情感的宣泄与平复。","mcq":[{"q":"“净化说”出自亚里士多德哪部著作","o":["《诗学》","《理想国》","《形而上学》","《政治学》"],"a":0,"w":"净化说见于《诗学》，用于解释悲剧效果。"}],"rel":[{"t":"《诗学》","n":"出处"},{"t":"亚里士多德","n":"提出者"},{"t":"模仿说","n":"《诗学》另一核心"},{"t":"古希腊三大悲剧家","n":"悲剧实践者"}],"exam":[]},{"id":"b09-039","t":"模仿说","cid":"09d","p":2,"kind":"概念","alias":["摹仿说","艺术模仿论","模仿论"],"one":"艺术是对现实的模仿，柏拉图贬低，亚里士多德肯定。","ans":"模仿说是**古希腊文艺理论的基本观念**，认为**艺术是对现实的模仿**。**柏拉图**在《理想国》中把现实看成理念的影子，艺术是**“影子的影子”**，与真理隔了三层，因此贬低诗和绘画；**亚里士多德**在《诗学》中肯定模仿，认为诗模仿的是**可能发生的事**，比记录已发生事件的历史**更带普遍性**、更具哲学意味。该学说长期影响西方文论，是**现实主义传统**的源头之一。","pts":["艺术模仿现实","柏拉图：隔三层，贬低","亚里士多德：揭示普遍性，肯定"],"mem":"床的例子：理念的床（神造），木匠的床（模仿理念），画家的床（模仿木匠的床）。画家离真理隔三层，所以柏拉图瞧不上；亚里士多德则说模仿是人的天性。","mix":"柏拉图与亚里士多德都用“模仿”，但评价相反；模仿说谈艺术本质，净化说谈悲剧效果。","mcq":[{"q":"主张“诗比历史更富有哲学意味”的是","o":["柏拉图","苏格拉底","亚里士多德","贺拉斯"],"a":2,"w":"亚里士多德《诗学》认为诗模仿可能发生之事，更具普遍性。"}],"rel":[{"t":"柏拉图","n":"贬低模仿"},{"t":"亚里士多德","n":"肯定模仿"},{"t":"《诗学》","n":"出处"},{"t":"净化说","n":"《诗学》另一核心"}],"exam":[]},{"id":"b09-040","t":"俄狄浦斯","cid":"09c","p":2,"kind":"人物","alias":["俄狄浦斯王","伊底帕斯","俄狄浦斯情结"],"one":"《俄狄浦斯王》主人公，弑父娶母，弗洛伊德据此命名情结。","ans":"俄狄浦斯是**希腊神话中忒拜国王**，索福克勒斯悲剧**《俄狄浦斯王》**的主人公。他出生前神谕预言他将**杀父娶母**，被父母遗弃后由他人养大；他在途中杀死了不相识的生父，后来**解开斯芬克斯之谜**被拥立为王，娶了生母。真相大白后，他刺瞎双眼，自我放逐。他是**命运悲剧**的典型，弗洛伊德据此提出**“俄狄浦斯情结”**（恋母情结），用以解释儿童心理。","pts":["忒拜国王，弑父娶母","解开斯芬克斯之谜","弗洛伊德据此提出俄狄浦斯情结"],"mem":"三步线：神谕（杀父娶母），拼命躲避，偏偏应验。越逃越近，这就是“命运悲剧”。弗洛伊德借他命名心理学术语，女孩版叫厄勒克特拉情结。","mix":"俄狄浦斯情结指男孩恋母，是弗洛伊德的术语，与剧中人物本人的故事不是一回事；悲剧作者是索福克勒斯，不是欧里庇得斯或埃斯库罗斯。","mcq":[{"q":"提出“俄狄浦斯情结”的心理学家是","o":["荣格","阿德勒","皮亚杰","弗洛伊德"],"a":3,"w":"弗洛伊德据索福克勒斯剧中人物提出俄狄浦斯情结。"}],"rel":[{"t":"《俄狄浦斯王》","n":"他的故事所在剧作"},{"t":"斯芬克斯之谜","n":"他解开的谜"},{"t":"弗洛伊德与精神分析","n":"情结提出者"},{"t":"索福克勒斯","n":"剧作者"}],"exam":[]},{"id":"b09-041","t":"阿喀琉斯之踵","cid":"09c","p":2,"kind":"常识","alias":["阿基里斯之踵","阿喀琉斯","阿基里斯","阿喀琉斯的脚踵"],"one":"阿喀琉斯全身刀枪不入，唯脚踵致命，喻致命弱点。","ans":"“阿喀琉斯之踵”出自**希腊神话**：英雄阿喀琉斯是《伊利亚特》中希腊联军最勇猛的战士，传说他幼时被母亲忒提斯**握着脚踵浸入冥河**，全身刀枪不入，**唯有被握住的脚踵**成为弱点。特洛伊战争中，帕里斯一箭射中他的脚踵，他因此丧命。后来这个典故用来**比喻最致命的弱点**。《伊利亚特》的开篇主题则是“阿喀琉斯的愤怒”。","pts":["神话：脚踵被母亲握住，唯一弱点","被帕里斯射中脚踵而死","比喻致命弱点"],"mem":"画面：母亲拎着婴儿的脚踵往冥河里一浸，那只被捏住的脚踵没沾水。所以“踵”就是“唯一没被保护的地方”。","mix":"“阿喀琉斯之踵”的典故重在致命弱点；《伊利亚特》的主题却是阿喀琉斯的愤怒，作品本身没有直接写到他中箭而亡。","mcq":[{"q":"“阿喀琉斯之踵”比喻的是","o":["过人的勇气","不可战胜的力量","致命的弱点","偶然的失误"],"a":2,"w":"阿喀琉斯全身只有脚踵没被冥河水浸到，喻致命弱点。"}],"rel":[{"t":"荷马史诗","n":"他出现于《伊利亚特》"},{"t":"特洛伊战争","n":"他的战场"},{"t":"潘多拉的盒子","n":"同类希腊神话典故"},{"t":"斯芬克斯之谜","n":"同类希腊神话典故"}],"exam":[]},{"id":"b09-042","t":"潘多拉的盒子","cid":"09c","p":2,"kind":"常识","alias":["潘多拉","潘多拉魔盒","潘多拉之盒","普罗米修斯盗火"],"one":"宙斯派潘多拉携盒下凡，灾祸飞出，只剩希望。","ans":"“潘多拉的盒子”是**希腊神话**中的典故，见于**赫西俄德**的《神谱》与《工作与时日》。**普罗米修斯盗火**给人类后，宙斯为惩罚人类，令神匠造出第一个女人**潘多拉**，把她送到人间；她打开神所赠的盒子（原为罐子），**灾祸与疾病飞出**，只有**希望**留在盒底。后来这个典故比喻**灾祸之源**，也用来说明一件事情带来的难以收拾的后果。","pts":["普罗米修斯盗火，宙斯惩罚人类","潘多拉打开盒子，灾祸飞出，只剩希望","比喻灾祸之源"],"mem":"因果线：盗火，惩罚，潘多拉，盒子。口诀：“盗火招祸，开盒放灾，留下希望。”","mix":"“盒子”本是罐子，后世误译沿用；盗火的是普罗米修斯，开盒子的是潘多拉，不要张冠李戴。","mcq":[{"q":"“潘多拉的盒子”打开后，留在盒中的是","o":["灾祸","疾病","智慧","希望"],"a":3,"w":"盒中灾祸飞出，只有希望留下。"}],"rel":[{"t":"宙斯","n":"惩罚者"},{"t":"赫西俄德","n":"典故出处作者"},{"t":"普罗米修斯","n":"盗火者"},{"t":"阿喀琉斯之踵","n":"同类典故"}],"exam":[]},{"id":"b09-043","t":"斯芬克斯之谜","cid":"09c","p":2,"kind":"常识","alias":["斯芬克斯","司芬克斯","人面狮身","狮身人面怪"],"one":"狮身人面怪问谜语，谜底是人，被俄狄浦斯解开。","ans":"斯芬克斯之谜出自**希腊神话**。**斯芬克斯**是忒拜城外的狮身人面怪物，拦路出谜：**什么东西早上四条腿、中午两条腿、晚上三条腿？** 答不出者被吃掉。**俄狄浦斯**答出谜底是**人**：婴儿爬行，成年直立，老年拄杖。斯芬克斯因此跳崖自杀，俄狄浦斯被拥立为忒拜王。它常被用来比喻**难解的谜**，也象征人对自身的认识，与埃及的狮身人面像名称相同、来源不同。","pts":["狮身人面怪，拦路出谜","谜底是人：早四中二晚三","被俄狄浦斯解开，后喻难解之谜"],"mem":"谜语一句话：“四，二，三，是什么？”答案“人”。三个年龄：爬、走、拄拐。顺序“早中晚”对应“婴儿、成年、老年”。","mix":"埃及的斯芬克斯是狮身人面像（见板块10），希腊的是有翼的女性怪物；谜底是人，不是动物；解谜者是俄狄浦斯，不是赫拉克勒斯。","mcq":[{"q":"斯芬克斯之谜的谜底是","o":["人","太阳","时间","命运"],"a":0,"w":"早晨四条腿指婴儿爬行，中午两条腿指成人，晚上三条腿指老人拄杖。"}],"rel":[{"t":"俄狄浦斯","n":"解谜者"},{"t":"《俄狄浦斯王》","n":"剧作依据"},{"t":"索福克勒斯","n":"剧作家"},{"t":"古希腊文明","n":"所属神话传统"}],"exam":[]},{"id":"b09-044","t":"维吉尔","cid":"09g","p":2,"kind":"人物","alias":["维吉尔","Virgil","Vergil","《牧歌》","《农事诗》"],"one":"古罗马诗人，《埃涅阿斯纪》作者，是但丁《神曲》中的向导。","ans":"维吉尔（前70–前19）是**古罗马奥古斯都时代的诗人**，与贺拉斯、奥维德并称古罗马三大诗人。他早年作《牧歌》，后作《农事诗》，晚年用十余年写成**史诗《埃涅阿斯纪》**，讲述**特洛伊英雄埃涅阿斯**逃出陷落的特洛伊、辗转建国意大利的故事，为罗马的起源立传。这部**文人史诗**模仿荷马史诗，是西方文人史诗的典范。**但丁《神曲》**把维吉尔写成引导自己游历地狱和炼狱的向导，可见其地位。","pts":["前70–前19，奥古斯都时代诗人","《埃涅阿斯纪》《牧歌》《农事诗》","但丁《神曲》中的向导"],"mem":"三部作品按“牧、农、战”记：《牧歌》写牧人，《农事诗》写农事，《埃涅阿斯纪》写战争与建国。联想：《神曲》里带但丁走的人就是维吉尔。","mix":"贺拉斯作《诗艺》，奥维德作《变形记》；《神曲》中引导但丁进入天堂的是贝雅特丽齐，维吉尔只到炼狱。","mcq":[{"q":"《神曲》中引导但丁游历地狱和炼狱的诗人是","o":["荷马","奥维德","贺拉斯","维吉尔"],"a":3,"w":"维吉尔，《埃涅阿斯纪》的作者；天堂由贝雅特丽齐引导。"}],"rel":[{"t":"《埃涅阿斯纪》","n":"代表作"},{"t":"古罗马三大诗人","n":"所属合称"},{"t":"《神曲》","n":"出场的向导"},{"t":"荷马史诗","n":"模仿的对象"}],"more":"作品：《牧歌》《农事诗》《埃涅阿斯纪》\n《埃涅阿斯纪》共十二卷，未及修订作者即去世。","exam":[]},{"id":"b09-045","t":"奥维德","cid":"09g","p":3,"kind":"人物","exam":[],"alias":[],"one":"古罗马诗人，《变形记》汇集希腊罗马神话","ans":"古罗马诗人，《变形记》汇集希腊罗马神话","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"= 奥维德 | C | 前43–约17 | 古罗马诗人 |\n作 《变形记》（神话故事集） / 《爱的艺术》\n混 卡夫卡也有小说《变形记》","todo":1},{"id":"b09-046","t":"欧几里得《几何原本》","cid":"09f","p":2,"kind":"作品","alias":["几何原本","欧几里得","欧几里德","《几何原本》"],"one":"古希腊几何学集大成之作，公理化体系，利玛窦、徐光启译前六卷。","ans":"《几何原本》是**古希腊数学家欧几里得**在前3世纪前后编成的几何学著作，共十三卷。全书从少数定义、公设和公理出发，用逻辑推出大量定理，建立了**公理化演绎体系**，是西方科学思维的典范。1607年，**意大利传教士利玛窦口译、徐光启笔录**，译出前六卷，“**几何**”一词由此定名。该书是明末西学东渐的重要成果，也是中国翻译史上科技翻译的早期代表。","pts":["欧几里得编，公理化演绎体系","1607年利玛窦口译、徐光启笔录前六卷","“几何”译名由此而来，西学东渐"],"mem":"年份与分工：1607，“利口徐笔”，利玛窦口述，徐光启落笔，只译前六卷（后九卷由李善兰、伟烈亚力在1857年补译）。","mix":"后九卷由清代李善兰与英国人伟烈亚力在1857年译出，不是徐光启所译；徐光启与利玛窦还合作译过《测量法义》。","mcq":[{"q":"1607年，与利玛窦合作译出《几何原本》前六卷的中国人是","o":["李善兰","徐光启","严复","林则徐"],"a":1,"w":"利玛窦口译、徐光启笔录；李善兰是后来补译后九卷者之一。"}],"rel":[{"t":"利玛窦","n":"口译者"},{"t":"徐光启","n":"笔录者"},{"t":"中国翻译史四次高潮","n":"明末科技翻译"}],"more":"“几何”译名由徐光启、利玛窦确定。\n欧几里得被称为“几何之父”。","exam":[]},{"id":"b09-047","t":"阿里斯托芬","cid":"09d","p":1,"kind":"人物","alias":["喜剧之父","阿里斯多芬"],"one":"古希腊“喜剧之父”，旧喜剧代表，作有《鸟》《蛙》《云》。","ans":"阿里斯托芬（约前446至约前385）是**古希腊雅典剧作家，被称为“喜剧之父”**，**古希腊旧喜剧的代表**。他生活在**伯罗奔尼撒战争时期**，以讽刺时政和人物著称。代表作有**《鸟》《蛙》《云》《阿卡奈人》**，还有主张反战的**《吕西斯忒拉忒》**；其中《云》**讽刺了苏格拉底**，《蛙》写酒神下冥界评判埃斯库罗斯与欧里庇得斯。剧中常有大胆幽默的政治讽刺，保存下来的完整剧本有十一部，是研究雅典社会和西方喜剧传统的重要材料。","pts":["雅典剧作家，“喜剧之父”，旧喜剧代表","《鸟》《蛙》《云》《阿卡奈人》","讽刺时政，《云》讽刺苏格拉底"],"mem":"三部名作“鸟、蛙、云”连起来：鸟飞过，蛙叫着，云里还挂着一个苏格拉底（《云》里他坐在吊篮里讲学）。对举记：悲剧三位“埃索欧”，喜剧一位阿里斯托芬。","mix":"《蛙》是阿里斯托芬的喜剧，莫言另有长篇小说《蛙》，注意区分。后来的“新喜剧”代表是米南德，风格由政治讽刺转向家庭生活。","mcq":[{"q":"被称为古希腊“喜剧之父”的是","o":["阿里斯托芬","米南德","索福克勒斯","莫里哀"],"a":0,"w":"阿里斯托芬，旧喜剧代表；米南德是新喜剧代表；莫里哀是法国喜剧作家。"},{"q":"下列属于阿里斯托芬作品的是","o":["《美狄亚》","《俄狄浦斯王》","《安提戈涅》","《鸟》"],"a":3,"w":"《鸟》《蛙》《云》是阿里斯托芬喜剧；其余三部是悲剧。"}],"rel":[{"t":"古希腊三大悲剧家","n":"与悲剧家对举"},{"t":"米南德与新喜剧","n":"后来的新喜剧"},{"t":"苏格拉底","n":"《云》的讽刺对象"},{"t":"莫里哀","n":"后世欧洲喜剧大家"},{"t":"狄俄尼索斯（酒神）","n":"戏剧起源于酒神祭"}],"more":"主要作品：《阿卡奈人》《骑士》《云》《马蜂》《和平》《鸟》《吕西斯忒拉忒》《蛙》等。","exam":[]},{"id":"b09-048","t":"伯里克利","cid":"09a","p":2,"kind":"人物","alias":["伯里克利时代","伯里克勒斯"],"one":"前5世纪中叶雅典领导人，雅典民主与文化的鼎盛期。","ans":"伯里克利（约前495–前429）是**前5世纪中叶雅典的政治领袖**，长期连选连任**十将军之一**。他推行**公职津贴制**，使贫穷公民也能参政，把雅典民主推向高峰；又利用提洛同盟的盟金修建**帕特农神庙**，聘菲狄亚斯等人，使雅典成为**希腊文化中心**。他在**伯罗奔尼撒战争**初期病逝于瘟疫。修昔底德记录了他著名的**阵亡将士葬礼演说**，被后人视为对雅典民主的经典颂扬。","pts":["前5世纪中叶雅典领袖，连选将军","公职津贴，民主极盛，建帕特农神庙","葬礼演说见修昔底德"],"mem":"一个人三件事：发津贴（民主）、修神庙（文化）、打斯巴达（战争）。“伯里克利时代”就是雅典的黄金时代，后面紧跟的是战争与衰落。","mix":"梭伦（前594）、克里斯提尼（前508）是民主的奠基者，伯里克利是民主的极盛期，三人先后顺序不要错位。","mcq":[{"q":"下列人物中，与雅典民主鼎盛时期联系最紧密的是","o":["梭伦","伯里克利","来库古","亚历山大"],"a":1,"w":"伯里克利时代是雅典民主和文化的黄金时代；来库古是斯巴达立法者，亚历山大是马其顿国王。"}],"rel":[{"t":"雅典民主","n":"他使其达到鼎盛"},{"t":"帕特农神庙","n":"他任内主持兴建"},{"t":"伯罗奔尼撒战争","n":"战争初期去世"},{"t":"修昔底德陷阱","n":"同出修昔底德的叙述"}],"exam":[]},{"id":"b09-049","t":"提洛同盟","cid":"09b","p":2,"kind":"制度","alias":["提洛同盟","雅典同盟","德利安同盟"],"one":"希波战争后雅典为首的海上同盟，后成雅典称霸工具。","ans":"提洛同盟是**希波战争后前478年由雅典领导建立的海上同盟**，因总部及金库设在**提洛岛**得名，成员主要是爱琴海沿岸和岛屿城邦，目的是共同防御波斯。盟邦须缴纳**贡金**或提供战舰，前454年金库迁到雅典后，同盟逐渐成为**雅典控制盟邦、扩张势力的工具**，形成雅典帝国。它与斯巴达领导的**伯罗奔尼撒同盟**对立，最终引发**伯罗奔尼撒战争**，同盟在雅典战败后解体。","pts":["前478年，雅典领导，总部提洛岛","盟邦缴贡金，金库迁雅典","成为雅典帝国工具，引发伯战"],"mem":"提洛岛在爱琴海中央，“提洛”对“伯罗奔尼撒”：海上对陆上，雅典对斯巴达。逻辑线：防波斯而立，波斯退了，雅典就把盟友当臣民，斯巴达不服，于是开战。","mix":"提洛同盟（雅典，海上）与伯罗奔尼撒同盟（斯巴达，陆上）不要对调；提洛同盟成立于希波战争后期，不是战争前。","mcq":[{"q":"提洛同盟的领导城邦是","o":["雅典","斯巴达","底比斯","科林斯"],"a":0,"w":"提洛同盟由雅典领导，与斯巴达领导的伯罗奔尼撒同盟对立。"}],"rel":[{"t":"希波战争","n":"成立的背景"},{"t":"伯罗奔尼撒战争","n":"同盟对立引发的战争"},{"t":"雅典民主","n":"盟主的政体"},{"t":"修昔底德陷阱","n":"新兴大国与守成大国之争"}],"exam":[]},{"id":"b09-050","t":"陶片放逐法","cid":"09a","p":2,"kind":"制度","alias":["陶片放逐","贝壳放逐法"],"one":"克里斯提尼创设，公民投票放逐危及民主者十年。","ans":"陶片放逐法是**雅典民主制中的一项制度**，一般认为由**克里斯提尼**在前508年前后改革时创设。每年公民大会可决定是否举行投票，公民把想放逐者的名字刻写在**陶片**上，得票超过**六千**即放逐，**期限十年**，但不没收财产，也不剥夺公民权。它用来防止野心家**僭取权力**，保护民主，后来也被政治斗争滥用。","pts":["克里斯提尼创设","陶片上写名字，公民投票","放逐十年，防僭主"],"mem":"画面：公民捡起一块碎陶片，刻上名字扔进瓮里。记两个数：十年，六千票。“陶片”就是当时的选票。","mix":"放逐不是死刑也不没收财产，只是离境十年；创设者克里斯提尼不是梭伦。","mcq":[{"q":"陶片放逐法的创设者一般认为是","o":["梭伦","克里斯提尼","伯里克利","德拉古"],"a":1,"w":"陶片放逐法随克里斯提尼改革创设；梭伦的是解负令，伯里克利是津贴制。"}],"rel":[{"t":"克里斯提尼改革","n":"创设该制度的改革"},{"t":"雅典民主","n":"制度所属体系"},{"t":"梭伦改革","n":"更早的改革"},{"t":"伯里克利","n":"民主极盛期人物"}],"exam":[]},{"id":"b09-051","t":"赫西俄德","cid":"09c","p":3,"kind":"人物","exam":[],"alias":[],"one":"古希腊诗人，《神谱》系统叙述诸神谱系，《工作与时日》写农事","ans":"古希腊诗人，《神谱》系统叙述诸神谱系，《工作与时日》写农事","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b09-052","t":"萨福","cid":"09c","p":2,"kind":"人物","alias":["莎孚","萨福体","第十位缪斯","累斯博斯诗人"],"one":"古希腊女抒情诗人，被柏拉图称为第十位缪斯。","ans":"萨福（约前630–约前570）是**古希腊女抒情诗人**，出生于**累斯博斯岛**，以抒发个人情感的诗歌著称，诗作多写爱情与友谊。其作品大多散佚，仅存**残篇**，所用诗节后世称**“萨福体”**。她是西方文学史上最早的重要女诗人，被**柏拉图**称为**“第十位缪斯”**，对后世西方抒情诗影响深远。","pts":["古希腊女抒情诗人，累斯博斯岛","作品多散佚，仅存残篇","柏拉图称第十位缪斯"],"mem":"九位缪斯加萨福就是十位。口诀：“九缪斯，加萨福，诗坛十位女神数。”","mix":"萨福是诗人而不是缪斯本人；荷马是史诗诗人，萨福是抒情诗人；古希腊另一位诗人阿那克里翁也写抒情诗，不要混。","mcq":[{"q":"柏拉图称之为“第十位缪斯”的古希腊诗人是","o":["荷马","萨福","赫西俄德","品达"],"a":1,"w":"柏拉图以“第十位缪斯”称赞女诗人萨福。"}],"rel":[{"t":"荷马史诗","n":"史诗与抒情诗对照"},{"t":"赫西俄德","n":"同属古风时期诗人"},{"t":"柏拉图","n":"称她为第十位缪斯"},{"t":"古希腊文明","n":"所属文明"}],"exam":[]},{"id":"b09-053","t":"伊索","cid":"09c","p":2,"kind":"人物","alias":["伊索寓言","埃索普","Aesop"],"one":"相传为奴隶出身的古希腊寓言作家，《伊索寓言》。","ans":"伊索是**约前6世纪的古希腊寓言作家**，相传出身奴隶，后获自由，以讲故事闻名。后人搜集编成**《伊索寓言》**，多用动物拟人，故事短小，寓意浅显，名篇有**《龟兔赛跑》《农夫和蛇》《狐狸和葡萄》《狼来了》**。他是**西方寓言的源头**，与法国拉封丹、俄国克雷洛夫、德国莱辛并称**世界四大寓言家**，作品影响了欧洲各国的寓言创作。","pts":["古希腊寓言作家，相传奴隶出身","《伊索寓言》：龟兔赛跑、农夫和蛇","与拉封丹、克雷洛夫、莱辛并称四大寓言家"],"mem":"四大寓言家口诀：“伊拉克莱”，伊索、拉封丹、克雷洛夫、莱辛。名篇配动物：龟、蛇、狐、狼。","mix":"《伊索寓言》是后人搜集编成，不是伊索亲笔成书；他与荷马一样生平多有传说成分。","mcq":[{"q":"下列寓言家中，被称为西方寓言源头的是","o":["拉封丹","伊索","克雷洛夫","莱辛"],"a":1,"w":"伊索是古希腊寓言作家，拉封丹、克雷洛夫、莱辛是后世继承者。"}],"rel":[{"t":"寓言","n":"他开创的体裁"},{"t":"世界四大寓言家","n":"合称"},{"t":"《庄子》","n":"中国寓言重要来源"},{"t":"古希腊文明","n":"所属文明"}],"exam":[]},{"id":"b09-054","t":"希波克拉底","cid":"09f","p":2,"kind":"人物","alias":["希波克拉底誓言","医学之父","体液说"],"one":"古希腊医生，“医学之父”，提出体液说，誓言为医德规范。","ans":"希波克拉底（约前460–前370）是**古希腊科斯岛的医生**，被誉为**“医学之父”**。他主张疾病源于自然原因而非神的惩罚，把医学从巫术和宗教中分离出来。他提出**四体液说**，认为血液、黏液、黄胆汁、黑胆汁失衡导致疾病。以他命名的《希波克拉底文集》汇集了当时的医学著作，其中的**“希波克拉底誓言”**要求医生为病人利益行医、保守秘密，是西方医德规范的源头。","pts":["古希腊科斯岛医生，医学之父","四体液说，疾病有自然原因","希波克拉底誓言，医德规范源头"],"mem":"记“四液”：血、黏、黄胆、黑胆，对应四种气质。口诀：医学之父希波克拉底，誓言管医德，体液管病因。","mix":"中国的“医圣”是张仲景，“药王”是孙思邈，不要与希腊的“医学之父”混淆。","mcq":[{"q":"被称为“医学之父”、留下医德誓言的古希腊人是","o":["阿基米德","希罗多德","毕达哥拉斯","希波克拉底"],"a":3,"w":"希波克拉底，其誓言为医德规范；阿基米德是物理学家，希罗多德是史学家。"}],"rel":[{"t":"阿基米德","n":"古希腊科学家对照"},{"t":"古希腊文明","n":"所属文明"},{"t":"希腊化时代","n":"其后科学中心移向亚历山大里亚"}],"exam":[]},{"id":"b09-055","t":"毕达哥拉斯","cid":"09e","p":2,"kind":"人物","alias":["毕达哥拉斯学派","毕达哥拉斯定理","勾股定理（西方）"],"one":"数是万物本原，毕达哥拉斯学派；西方称勾股定理为毕达哥拉斯定理。","ans":"毕达哥拉斯（约前570–约前495）是**古希腊哲学家、数学家**，生于萨摩斯岛，后在意大利南部创立**毕达哥拉斯学派**，兼有宗教教团性质。他们主张**数是万物的本原**，认为宇宙和谐，音律也可用数的比例表示，并相信灵魂轮回。西方把**勾股定理**称为**毕达哥拉斯定理**，但这一定理在中国《周髀算经》中也有记载。学派推动了数学和理性思考的发展。","pts":["数是万物本原","学派兼具宗教色彩","西方称勾股定理为毕达哥拉斯定理"],"mem":"本原对照记：泰勒斯水，赫拉克利特火，毕达哥拉斯数。定理对照：中国商高（勾股），西方毕达哥拉斯。","mix":"定理在中国称勾股定理，在西方称毕达哥拉斯定理；是否由毕达哥拉斯本人证明，学界有争议；数本原说与泰勒斯的水不同，数不是具体物质。","mcq":[{"q":"主张“数是万物本原”的是","o":["毕达哥拉斯","泰勒斯","赫拉克利特","德谟克利特"],"a":0,"w":"毕达哥拉斯学派以数为本原，是与具体物质本原不同的思路。"}],"rel":[{"t":"本原（始基）","n":"其数本原说"},{"t":"泰勒斯","n":"水本原对照"},{"t":"赫拉克利特","n":"火本原对照"},{"t":"阿基米德","n":"希腊数学传统"}],"exam":[]},{"id":"b09-056","t":"斯多葛学派","cid":"09f","p":3,"kind":"流派","exam":[],"alias":[],"one":"希腊化时期芝诺创立，主张顺应自然与理性、恬淡寡欲，影响罗马的塞涅卡、马可·奥","ans":"希腊化时期芝诺创立，主张顺应自然与理性、恬淡寡欲，影响罗马的塞涅卡、马可·奥勒留","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b09-057","t":"伊壁鸠鲁","cid":"09f","p":3,"kind":"人物","exam":[],"alias":[],"one":"希腊化时期哲学家，原子论者，主张快乐（心灵宁静）是最高的善","ans":"希腊化时期哲学家，原子论者，主张快乐（心灵宁静）是最高的善","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b09-058","t":"缪斯","cid":"09c","p":3,"kind":"常识","exam":[],"alias":[],"one":"希腊神话中掌管文艺和科学的九位女神","ans":"希腊神话中掌管文艺和科学的九位女神","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b09-059","t":"线形文字B","cid":"09a","p":3,"kind":"常识","exam":[],"alias":[],"one":"迈锡尼文明的音节文字，1952年文特里斯释读，证明是早期希腊语；线形文字A至","ans":"迈锡尼文明的音节文字，1952年文特里斯释读，证明是早期希腊语；线形文字A至今未释读","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b09-061","t":"西塞罗","cid":"09g","p":3,"kind":"人物","exam":[],"alias":[],"one":"古罗马政治家、演说家、散文家，称希罗多德为“历史之父”；其翻译观主张“作为演","ans":"古罗马政治家、演说家、散文家，称希罗多德为“历史之父”；其翻译观主张“作为演说家而非解释者”，是西方意译观的源头；翻译史考点","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b09-062","t":"七十子译本","cid":"09g","p":2,"kind":"作品","alias":["七十子希腊文本","七十士译本","七十子圣经","LXX","Septuagint","七十子希腊文《圣经》"],"one":"前3世纪起在亚历山大里亚把希伯来《圣经》译成希腊文的译本。","ans":"七十子译本是**前3世纪起在埃及亚历山大里亚完成的希伯来《圣经》希腊文译本**。相传由**七十二位犹太学者**在托勒密王朝统治者支持下翻译，因此名为“七十子”，拉丁文作 Septuagint。起因是亚历山大里亚的犹太人已不通希伯来文。它是**西方第一部重要的宗教典籍译本**，也是早期规模较大的翻译活动，后来成为早期基督教会使用的《旧约》，对基督教传播和《圣经》翻译传统影响深远。","pts":["前3世纪起在亚历山大里亚翻译","希伯来圣经译成希腊文，相传72位学者","西方早期大规模翻译，旧约来源"],"mem":"数字：72人翻译，名称却叫“七十”，取整数。罗马数字 LXX 就是 70。记“亚历山大里亚＋希腊文＋圣经”三个关键词，翻译史考点常问“第一部”。","mix":"耶柔米的拉丁文《圣经》（武加大译本，4世纪末）和马丁·路德的德语《圣经》是后来的译本，不是七十子译本。","mcq":[{"q":"前3世纪起在亚历山大里亚译成希腊文的《圣经》译本是","o":["武加大译本","钦定本","路德译本","七十子译本"],"a":3,"w":"七十子译本是希伯来《圣经》的希腊文译本，武加大是拉丁文译本。"}],"rel":[{"t":"《圣经》","n":"所译典籍"},{"t":"亚历山大里亚与亚历山大图书馆","n":"翻译地点"},{"t":"马丁·路德与德语《圣经》","n":"后世译经对照"},{"t":"《七十子希腊文本》","n":"同一译本"}],"exam":[]},{"id":"c-053","t":"古希腊三贤","cid":"09f","p":1,"kind":"合称","alias":["希腊三贤","古希腊三哲","希腊三哲"],"one":"苏格拉底、柏拉图、亚里士多德，师徒三代的古希腊哲学高峰。","ans":"古希腊三贤指**苏格拉底、柏拉图、亚里士多德**，是**古典时期雅典哲学的三代师徒**。苏格拉底述而不作，用**助产术**追问美德，主张“美德即知识”，前399年被雅典法庭判处死刑；柏拉图是他的学生，著《理想国》，提出**理念论**，创办**阿卡德米学园**；亚里士多德是柏拉图的学生，创办**吕克昂学园**，创立**形式逻辑**，著《诗学》《政治学》。苏格拉底使哲学转向人自身，后两人建立起系统的哲学体系，**奠定了西方哲学的基本问题与方法**。","pts":["苏格拉底、柏拉图、亚里士多德，师徒相承","苏格拉底助产术，柏拉图理念论，亚里士多德形式逻辑","使哲学转向人，奠定西方哲学体系"],"members":[["苏格拉底","述而不作；助产术；“认识你自己”“美德即知识”"],["柏拉图","《理想国》；理念论；阿卡德米学园"],["亚里士多德","《诗学》《政治学》；形式逻辑；吕克昂学园"]],"mem":"师承链“苏→柏→亚”，一代教一代，最后一环又教出亚历山大。自编三字记法：苏“问”（助产术追问），柏“想”（理念论、理想国），亚“分”（分类、逻辑、百科）。","mix":"三贤不含前苏格拉底的泰勒斯、赫拉克利特、德谟克利特，也不含智者学派；亚历山大大帝的老师是亚里士多德，与柏拉图无直接师承。","mcq":[{"q":"下列哲学家中，不属于“古希腊三贤”的是","o":["苏格拉底","德谟克利特","柏拉图","亚里士多德"],"a":1,"w":"德谟克利特是前苏格拉底时期的原子论者。"},{"q":"古希腊三贤中，创办吕克昂学园的是","o":["苏格拉底","柏拉图","亚里士多德","伊壁鸠鲁"],"a":2,"w":"柏拉图办的是阿卡德米学园。"}],"rel":[{"t":"苏格拉底","n":"三贤之始"},{"t":"柏拉图","n":"三贤之中"},{"t":"亚里士多德","n":"三贤之集大成者"},{"t":"助产术（苏格拉底方法）","n":"苏格拉底的方法"},{"t":"古希腊文明","n":"所属文明"}],"more":"苏格拉底（前469—前399）、柏拉图（前427—前347）、亚里士多德（前384—前322）。","exam":[]},{"id":"c-054","t":"古罗马三大诗人","cid":"09g","p":2,"kind":"合称","alias":["罗马三大诗人","维吉尔、贺拉斯、奥维德"],"one":"奥古斯都时代的维吉尔、贺拉斯、奥维德。","ans":"古罗马三大诗人指**奥古斯都时代的维吉尔、贺拉斯、奥维德**，是罗马文学“黄金时代”的代表。维吉尔著**史诗《埃涅阿斯纪》**，为罗马建国立传；贺拉斯著**《诗艺》和《颂歌》**，提出寓教于乐和“合式”原则；奥维德著**《变形记》**，汇集希腊罗马神话传说，成为后世艺术取材的宝库。三人使拉丁文学在继承希腊的基础上形成自己的风格，影响了**文艺复兴和古典主义**。","pts":["维吉尔、贺拉斯、奥维德","奥古斯都时代，罗马黄金时代","《埃涅阿斯纪》《诗艺》《变形记》"],"members":[["维吉尔","《埃涅阿斯纪》《牧歌》《农事诗》"],["贺拉斯","《诗艺》《颂歌》"],["奥维德","《变形记》《爱的艺术》"]],"mem":"首字口诀“维贺奥”：维写罗马建国，贺写诗歌规矩，奥写神话变形。画面：维吉尔牵着但丁，贺拉斯拿着诗艺教你写，奥维德把神变成花鸟。","mix":"荷马是希腊人，不在其列；卢克莱修（《物性论》）、卡图卢斯虽是罗马诗人，但三大诗人通行说法是维贺奥。","mcq":[{"q":"下列诗人中，不属于古罗马三大诗人的是","o":["荷马","维吉尔","贺拉斯","奥维德"],"a":0,"w":"荷马是古希腊诗人；三大诗人是维吉尔、贺拉斯、奥维德。"}],"rel":[{"t":"维吉尔","n":"成员"},{"t":"贺拉斯","n":"成员"},{"t":"奥维德","n":"成员"},{"t":"古希腊三大悲剧家","n":"希腊罗马文学三三合称"}],"exam":[]},{"id":"c-055","t":"中国三大英雄史诗","cid":"09i","p":1,"kind":"合称","alias":["三大英雄史诗","中国少数民族三大史诗","三大史诗"],"one":"藏族《格萨尔王传》、蒙古族《江格尔》、柯尔克孜族《玛纳斯》。","ans":"中国三大英雄史诗指**藏族《格萨尔王传》、蒙古族《江格尔》和柯尔克孜族《玛纳斯》**，是**中国少数民族民间英雄史诗**的代表，三者都靠说唱艺人口头传唱，至今仍在活态传承。《格萨尔王传》讲述岭国国王格萨尔降妖伏魔、统一各部，有一百多部、百万余诗行，被认为是世界上最长的史诗；《江格尔》讲述江格尔与勇士们保卫理想家园宝木巴；《玛纳斯》讲述玛纳斯及其子孙的英雄业绩。三部史诗均已列入国家级非遗名录，其中**《格萨尔》《玛纳斯》于2009年入选联合国教科文组织人类非遗代表作名录**。","pts":["藏族《格萨尔王传》、蒙古族《江格尔》、柯尔克孜族《玛纳斯》","说唱艺人口头传唱，活态传承","均入国家级非遗，《格萨尔》《玛纳斯》2009年入选人类非遗"],"members":[["《格萨尔王传》","藏族；岭国国王格萨尔；世界最长史诗"],["《江格尔》","蒙古族（卫拉特）；江格尔与宝木巴"],["《玛纳斯》","柯尔克孜族；玛纳斯及其七代子孙"]],"mem":"民族与书名配对：藏→格，蒙→江，柯→玛（自编“藏格、蒙江、柯玛”）。再配关键词：格萨尔“岭国”，江格尔“宝木巴”，玛纳斯“八代”，各取一个地名或数字，选择题里一眼能认。","mix":"彝族《阿诗玛》是叙事长诗，不在三大之列；蒙古族另有《格斯尔》，即《格萨尔王传》的蒙古族版本，不要把它当成第四部。","mcq":[{"q":"下列作品中，不属于中国三大英雄史诗的是","o":["《格萨尔王传》","《江格尔》","《玛纳斯》","《阿诗玛》"],"a":3,"w":"《阿诗玛》是彝族撒尼人的叙事长诗。"},{"q":"下列民族与其英雄史诗对应正确的是","o":["藏族—《江格尔》","蒙古族—《玛纳斯》","柯尔克孜族—《玛纳斯》","柯尔克孜族—《格萨尔王传》"],"a":2,"w":"藏族《格萨尔王传》，蒙古族《江格尔》，柯尔克孜族《玛纳斯》。"}],"rel":[{"t":"《格萨尔王传》","n":"藏族"},{"t":"《江格尔》","n":"蒙古族"},{"t":"《玛纳斯》","n":"柯尔克孜族"},{"t":"史诗","n":"上位概念"},{"t":"印度两大史诗","n":"东方史诗对照"}],"more":"三部史诗均列入国家级非物质文化遗产代表性项目名录。","exam":[]},{"id":"a09-001","t":"克里特文明（米诺斯文明）","cid":"09a","p":2,"kind":"概念","alias":["米诺斯文明","克里特岛文明","克诺索斯","米诺斯迷宫"],"one":"爱琴文明前期，兴盛于克里特岛，克诺索斯王宫，线形文字A。","ans":"克里特文明又称**米诺斯文明**，约从**前2000年**起兴盛于**克里特岛**，是**爱琴文明的前一阶段**。中心是**克诺索斯王宫**，结构复杂，被后人与**米诺斯王和迷宫**的传说联系起来；居民使用**线形文字A**，至今未能释读。约前15世纪，克里特被来自希腊大陆的**迈锡尼人**取代，其文化为迈锡尼文明所继承。","pts":["约前2000年起，克里特岛，克诺索斯","米诺斯王与迷宫传说","线形文字A未释读，后为迈锡尼取代"],"mem":"顺序口诀：先克里特，后迈锡尼，再黑暗时代。克里特的“迷宫”与米诺斯（Minos）同名，记住“迷宫在克里特”。线形文字：A 未解，B 已解（希腊语，迈锡尼用）。","mix":"线形文字A属克里特，尚未释读；线形文字B属迈锡尼，已释读为早期希腊语。特洛伊战争传说附着于迈锡尼时代，不属克里特。","mcq":[{"q":"线形文字A属于下列哪种文明","o":["迈锡尼文明","两河流域文明","古埃及文明","克里特文明"],"a":3,"w":"线形文字A属克里特文明，至今未释读；线形文字B属迈锡尼文明。"}],"rel":[{"t":"迈锡尼文明","n":"继起的爱琴文明"},{"t":"古希腊文明","n":"所属大背景"},{"t":"特洛伊战争","n":"附着于迈锡尼时代"},{"t":"古希腊三大柱式","n":"后世希腊建筑对照"}],"exam":[]},{"id":"a09-002","t":"梭伦改革","cid":"09a","p":2,"kind":"事件","alias":["梭伦立法","解负令","卸负令"],"one":"前594年梭伦颁布解负令，废债务奴隶，奠定雅典民主。","ans":"梭伦改革是**前594年雅典执政官梭伦**进行的改革，属于雅典民主的起点。他颁布**解负令**，废除债务奴隶制，解放因债务沦为奴隶者；又按财产把公民分成**四个等级**，各级享有不同的政治权利，并设立**四百人议事会**和**公民陪审法庭**，让平民参与国家事务。改革削弱了贵族特权，为**克里斯提尼改革**和**伯里克利**时代的民主打下基础。","pts":["前594年，解负令，废债务奴隶","按财产分四等级，设四百人议事会","奠定雅典民主，早于克里斯提尼"],"mem":"雅典民主三步走：梭伦打底（594），克里斯提尼建制（508），伯里克利登顶（约450）。梭伦的“解负”就是替欠债的人卸下身上的担子。","mix":"梭伦改革重财产等级与债务，克里斯提尼改革重地域划分与十部落、陶片放逐；两者常被混作一场改革。","mcq":[{"q":"废除债务奴隶制的“解负令”由谁颁布","o":["梭伦","克里斯提尼","伯里克利","来库古"],"a":0,"w":"解负令是梭伦前594年改革的核心措施。"}],"rel":[{"t":"克里斯提尼改革","n":"接续的民主改革"},{"t":"雅典民主","n":"改革奠定其基础"},{"t":"伯里克利","n":"民主极盛期人物"},{"t":"斯巴达","n":"同期的另一城邦模式"}],"exam":[]},{"id":"a09-003","t":"克里斯提尼改革","cid":"09a","p":3,"kind":"事件","exam":[],"alias":[],"one":"前508年前后按地域重划十个部落，设五百人议事会，创陶片放逐法。","ans":"前508年前后按地域重划十个部落，设五百人议事会，创陶片放逐法。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-004","t":"帕特农神庙","cid":"09a","p":2,"kind":"常识","alias":["雅典卫城","巴台农神庙"],"one":"雅典卫城上祭雅典娜的神庙，多立克柱式代表。","ans":"帕特农神庙是**雅典卫城上供奉雅典娜的神庙**，**前447年**动工、前432年大体完工，建于**伯里克利**时期。神庙采用**多立克柱式**，外形庄重均衡，由伊克蒂诺、卡里克拉特设计，**菲狄亚斯**主持雕刻。它是**古希腊建筑的代表作**，象征雅典民主与文化的鼎盛，也是西方古典建筑的典范。其部分雕刻被19世纪初英国人运走，今存大英博物馆，归属至今有争议。","pts":["雅典卫城，祭雅典娜","伯里克利时期，多立克柱式","菲狄亚斯主持雕刻"],"mem":"“帕特农”意为处女，指处女神雅典娜。画面：卫城山顶一排粗壮的多立克柱，结实朴素，对比后起的爱奥尼亚（卷涡）和科林斯（花叶）。","mix":"多立克柱最朴素，爱奥尼亚柱顶有卷涡，科林斯柱顶是毛茛叶；帕特农用的是多立克式。雅典卫城不是罗马斗兽场所在，后者在罗马。","mcq":[{"q":"帕特农神庙供奉的是","o":["宙斯","阿波罗","雅典娜","波塞冬"],"a":2,"w":"帕特农神庙是祭祀雅典城守护神雅典娜的神庙。"}],"rel":[{"t":"古希腊三大柱式","n":"神庙用多立克式"},{"t":"伯里克利","n":"主持兴建的领导人"},{"t":"雅典娜","n":"供奉的女神"},{"t":"古罗马斗兽场","n":"古罗马建筑对照"}],"exam":[]},{"id":"a09-005","t":"古希腊三大柱式","cid":"09a","p":3,"kind":"合称","exam":[],"alias":[],"one":"多立克式（粗壮无柱础）、爱奥尼亚式（秀美，柱头有涡卷）、科林斯式（柱头饰莨苕","ans":"多立克式（粗壮无柱础）、爱奥尼亚式（秀美，柱头有涡卷）、科林斯式（柱头饰莨苕叶）。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-006","t":"马拉松战役","cid":"09b","p":2,"kind":"事件","alias":["马拉松战役","马拉松会战","马拉松之战"],"one":"前490年雅典击败波斯，马拉松赛跑传说的由来。","ans":"马拉松战役发生于**前490年**，是**希波战争**中的重要战役。波斯军队在雅典东北的**马拉松平原**登陆，**雅典**军队在将军米尔提亚德指挥下以少胜多，击败波斯军。相传一名传令兵从马拉松跑回雅典报捷后力竭而死，**现代马拉松赛跑**即由此而来，**1896年首届现代奥运会**设立此项目，全程标准距离后来定为42.195公里。这场胜利增强了希腊人抵抗波斯的信心。","pts":["前490年，雅典败波斯","传令兵跑回雅典报捷的传说","现代马拉松赛跑来源，1896年入奥运"],"mem":"画面：一个士兵从马拉松一口气跑到雅典，喊出“我们胜利了”后倒下。年份口诀：490 马拉松，480 温泉关与萨拉米斯，相差十年。","mix":"传令兵报捷是传说，说法不一；马拉松战役在前490年，温泉关与萨拉米斯在前480年，不要混。","mcq":[{"q":"现代马拉松赛跑的起源与下列哪场战役有关","o":["马拉松战役","萨拉米斯海战","温泉关战役","普拉提亚战役"],"a":0,"w":"马拉松赛跑来自传令兵从马拉松跑回雅典报捷的传说。"}],"rel":[{"t":"希波战争","n":"所属战争"},{"t":"希罗多德","n":"记述此战的史家"},{"t":"马拉松","n":"后世体育项目"},{"t":"奥林匹克运动会","n":"1896年起设此项目"}],"exam":[]},{"id":"a09-007","t":"温泉关战役与萨拉米斯海战","cid":"09b","p":3,"kind":"事件","exam":[],"alias":[],"one":"前480年斯巴达王列奥尼达率军扼守温泉关战死；同年雅典将领地米斯托克利在萨拉","ans":"前480年斯巴达王列奥尼达率军扼守温泉关战死；同年雅典将领地米斯托克利在萨拉米斯海战大败波斯海军。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-008","t":"亚历山大里亚与亚历山大图书馆","cid":"09b","p":2,"kind":"常识","alias":["亚历山大图书馆","亚历山大里亚","亚历山大城"],"one":"埃及的希腊化名城与学术中心，托勒密王朝都城。","ans":"亚历山大里亚是**亚历山大大帝约前331年在埃及建立的城市**，后为**托勒密王朝**的都城，是**希腊化时代的学术中心**。托勒密王朝在此设立缪斯神庙和**亚历山大图书馆**，是古代最大的图书馆，聚集大批学者，欧几里得、埃拉托色尼等都与之相关；城中的**法洛斯灯塔**列入古代世界七大奇迹。相传**七十子译本**在此译成。图书馆最终毁于何时，说法不一。","pts":["亚历山大建于埃及，托勒密王朝都城","图书馆是古代最大学术中心","七十子译本相传在此译成"],"mem":"一座城三个招牌：图书馆（读书）、灯塔（航海）、译本（翻译）。翻译史上要记：希伯来圣经在这里变成希腊文，这是西方早期大规模翻译活动。","mix":"亚历山大里亚在埃及，不在希腊或马其顿；图书馆毁灭有多种说法（凯撒战火、后世宗教冲突等），不宜断言某一个原因。","mcq":[{"q":"相传《七十子译本》译成于","o":["雅典","罗马","亚历山大里亚","耶路撒冷"],"a":2,"w":"七十子译本是在托勒密王朝统治下的亚历山大里亚译出的。"}],"rel":[{"t":"希腊化时代","n":"所属时代"},{"t":"七十子译本","n":"相传在此译成"},{"t":"亚历山大大帝","n":"创建者"},{"t":"阿基米德","n":"曾游学该城"}],"exam":[]},{"id":"a09-009","t":"阿基米德","cid":"09f","p":2,"kind":"人物","alias":["阿基米德原理","浮力定律","杠杆原理","尤里卡"],"one":"叙拉古数学家、物理学家，浮力定律和杠杆原理的发现者。","ans":"阿基米德（约前287–前212）是**古希腊叙拉古（今意大利西西里岛）的数学家和物理学家**。他发现了**浮力定律**（阿基米德原理），相传是在浴盆中想到辨别王冠真假的方法，惊呼“尤里卡”。他还系统阐明了**杠杆原理**，传说他说过“给我一个支点，我就能撬动地球”。他在几何学上计算了圆周率的近似值和球体体积。前212年罗马军队攻陷叙拉古时，他被士兵杀死，是**古代科学的代表人物**。","pts":["叙拉古人，数学家、物理学家","浮力定律、杠杆原理","给我一个支点，我就能撬动地球"],"mem":"画面：浴缸里水溢出来，他跳出来喊“Eureka（我发现了）”；再画一根长杠杆顶着地球。两个画面对应浮力与杠杆。","mix":"“尤里卡”是希腊语“我发现了”，后用作发现的欢呼；欧几里得是几何学公理化的代表，阿基米德偏重力学与求积，二人常被一起考。","mcq":[{"q":"下列科学成就中，属于阿基米德的是","o":["《几何原本》","四体液说","勾股定理","浮力定律与杠杆原理"],"a":3,"w":"《几何原本》属欧几里得，四体液说属希波克拉底，勾股定理在西方称毕达哥拉斯定理。"}],"rel":[{"t":"欧几里得《几何原本》","n":"同为希腊化时期科学代表"},{"t":"希波克拉底","n":"古希腊科学医学对照"},{"t":"亚历山大里亚与亚历山大图书馆","n":"阿基米德曾游学于此"}],"exam":[]},{"id":"a09-010","t":"奥林匹斯十二主神","cid":"09c","p":1,"kind":"合称","alias":["十二主神","奥林匹斯诸神","奥林匹斯山诸神","十二神"],"one":"居于奥林匹斯山的十二位主神，以宙斯为首。","ans":"奥林匹斯十二主神是**古希腊神话中居于奥林匹斯山的十二位主神**，以**众神之王宙斯**为首。通行名单为**宙斯、赫拉、波塞冬、德墨忒耳、雅典娜、阿波罗、阿耳忒弥斯、阿瑞斯、阿芙洛狄忒、赫淮斯托斯、赫耳墨斯**，第十二位说法不一，或为**赫斯提亚，或为狄俄尼索斯**。他们分管天空、海洋、农业、智慧、光明、狩猎、战争、爱情、锻造与商旅等。罗马神话与之一一对应，如宙斯对朱庇特、雅典娜对密涅瓦，成为欧洲文艺中的常用典故。","pts":["居奥林匹斯山，宙斯为首","十一位固定，第十二位赫斯提亚或狄俄尼索斯","罗马名对应，如宙斯对朱庇特"],"members":[["宙斯","众神之王，掌天空与雷电；罗马名朱庇特"],["赫拉","宙斯之妻，婚姻女神；朱诺"],["波塞冬","海神；尼普顿"],["德墨忒耳","农业女神；刻瑞斯"],["雅典娜","智慧与战争女神，雅典城守护神；密涅瓦"],["阿波罗","光明、音乐、预言之神；罗马名同"],["阿耳忒弥斯","狩猎与月亮女神；狄安娜"],["阿瑞斯","战神；马尔斯"],["阿芙洛狄忒","爱与美之神；维纳斯"],["赫淮斯托斯","火与锻造之神；伏尔甘"],["赫耳墨斯","信使与商旅之神；墨丘利"],["赫斯提亚或狄俄尼索斯","第十二位，两说并存；维斯塔或巴克斯"]],"mem":"先背固定的十一位，再补第十二位。按职责配对：宙斯（天）、波塞冬（海）、德墨忒耳（田）；赫拉（婚姻）；雅典娜（智慧）、阿波罗（光明）、阿耳忒弥斯（狩猎月亮）；阿瑞斯（战争）、阿芙洛狄忒（爱美）；赫淮斯托斯（锻造）、赫耳墨斯（信使）。冥王哈得斯是宙斯的兄弟，但住冥界，不算十二主神。","mix":"冥王哈得斯不在十二主神之列，因居冥界。第十二位有赫斯提亚和狄俄尼索斯两说。阿芙洛狄忒（希腊）即维纳斯（罗马），不要把希腊名与罗马名混答。","mcq":[{"q":"下列哪位神不属于奥林匹斯十二主神的通行名单","o":["雅典娜","阿波罗","哈得斯","赫耳墨斯"],"a":2,"w":"冥王哈得斯居冥界，不列入十二主神。"},{"q":"希腊神话中的智慧女神、雅典城的守护神是","o":["赫拉","雅典娜","阿芙洛狄忒","德墨忒耳"],"a":1,"w":"雅典娜为智慧与战争女神，雅典城因她得名。"}],"rel":[{"t":"希腊神话","n":"十二主神所属体系"},{"t":"希腊神祇的罗马名对应","n":"希腊罗马名对照"},{"t":"雅典娜","n":"十二主神之一"},{"t":"狄俄尼索斯（酒神）","n":"第十二位候选"},{"t":"中国古代神话","n":"中西神系对照"}],"more":"罗马名对应：宙斯—朱庇特，赫拉—朱诺，波塞冬—尼普顿，雅典娜—密涅瓦，阿芙洛狄忒—维纳斯，阿瑞斯—马尔斯，赫耳墨斯—墨丘利。","exam":[]},{"id":"a09-011","t":"宙斯","cid":"09c","p":2,"kind":"人物","alias":["朱庇特","众神之王","奥林匹斯主神"],"one":"希腊众神之王，克洛诺斯之子，居奥林匹斯山，掌雷电。","ans":"宙斯是**希腊神话中的众神之王**，**克洛诺斯与瑞亚之子**。他推翻父亲后，与兄弟波塞冬、哈迪斯分掌天空、海洋与冥界，自己居**奥林匹斯山**，手持**雷电**，为**十二主神之首**。其妻是赫拉，**雅典娜**据说从他头颅中诞生。宙斯又是古代**奥运会**所祭祀的神，**菲狄亚斯**为他雕造的**奥林匹亚宙斯神像**列入古代世界七大奇迹。罗马神话中的对应神是**朱庇特**。","pts":["众神之王，居奥林匹斯山，掌雷电","克洛诺斯之子，与波塞冬、哈迪斯分治三界","罗马名朱庇特，古代奥运会祭神"],"mem":"三兄弟分三界：宙斯天，波塞冬海，哈迪斯冥。记雷电：宙斯手里总有一束闪电。罗马名朱庇特，对应木星。","mix":"宙斯是希腊名，朱庇特是罗马名；与宙斯同属十二主神的波塞冬管海，不要混；奥林匹斯山（神居）与奥林匹亚（祭祀地）不是一个地方。","mcq":[{"q":"希腊神话中掌管雷电的众神之王是","o":["宙斯","波塞冬","阿波罗","阿瑞斯"],"a":0,"w":"宙斯掌雷电，波塞冬管海，阿波罗为太阳与艺术之神，阿瑞斯为战神。"}],"rel":[{"t":"希腊神祇的罗马名对应","n":"罗马名朱庇特"},{"t":"奥林匹克运动会","n":"古代奥运会祭宙斯"},{"t":"雅典娜","n":"自其头颅诞生"},{"t":"潘多拉的盒子","n":"宙斯惩罚人类"}],"exam":[]},{"id":"a09-012","t":"普罗米修斯","cid":"09c","p":1,"kind":"人物","alias":["普罗米修斯盗火","盗火者"],"one":"希腊神话中盗天火给人类、受宙斯惩罚的泰坦神，反抗强权的象征。","ans":"普罗米修斯是**古希腊神话中的泰坦神，人类的恩主**。他**盗取天火赐给人类**，触怒宙斯，被**锁在高加索山崖，每日遭鹰啄食肝脏**，后由英雄赫拉克勒斯解救。他的故事见于**赫西俄德《神谱》和埃斯库罗斯的悲剧《被缚的普罗米修斯》**，浪漫主义诗人**雪莱写有诗剧《解放了的普罗米修斯》**。**马克思称他是“哲学日历中最高尚的圣者和殉道者”**，普罗米修斯因此成为**反抗强权、为人类牺牲的象征**，是神话、悲剧与浪漫主义三条线交汇的形象。","pts":["盗天火给人类，被宙斯锁崖受鹰啄肝","埃斯库罗斯《被缚的普罗米修斯》，雪莱《解放了的普罗米修斯》","马克思称其为最高尚的圣者和殉道者"],"mem":"一个画面：山崖、锁链、一只鹰，肝脏白天被啄、夜里又长好。两部作品用“被”和“解放”区分：被缚的（埃斯库罗斯，古希腊悲剧），解放了的（雪莱，英国浪漫主义）。名句挂马克思：最高尚的圣者和殉道者。","mix":"《被缚的普罗米修斯》属埃斯库罗斯，不属索福克勒斯、欧里庇得斯；《解放了的普罗米修斯》是雪莱的诗剧。潘多拉的故事与普罗米修斯盗火有关：宙斯为报复而送去潘多拉。","mcq":[{"q":"悲剧《被缚的普罗米修斯》的作者是","o":["埃斯库罗斯","索福克勒斯","欧里庇得斯","阿里斯托芬"],"a":0,"w":"埃斯库罗斯，“悲剧之父”，另有《俄瑞斯忒亚》三部曲。"},{"q":"诗剧《解放了的普罗米修斯》的作者是","o":["拜伦","济慈","华兹华斯","雪莱"],"a":3,"w":"雪莱，英国浪漫主义诗人；与埃斯库罗斯的《被缚的普罗米修斯》常被混淆。"}],"rel":[{"t":"埃斯库罗斯","n":"《被缚的普罗米修斯》作者"},{"t":"雪莱","n":"《解放了的普罗米修斯》作者"},{"t":"潘多拉的盒子","n":"宙斯报复人类的故事"},{"t":"希腊神话","n":"所属神话体系"},{"t":"中国古代神话","n":"中国有燧人氏取火之说"}],"more":"马克思：普罗米修斯是哲学日历中最高尚的圣者和殉道者。｜《博士论文》序言","exam":[]},{"id":"a09-013","t":"狄俄尼索斯（酒神）","cid":"09c","p":2,"kind":"人物","alias":["酒神","狄奥尼索斯","狄俄尼索斯","巴克斯","酒神节"],"one":"酒神，罗马称巴克斯；酒神节演剧是悲剧喜剧的起源。","ans":"狄俄尼索斯是**希腊神话中的酒神**，宙斯与塞墨勒之子，象征酿酒、狂欢与生命力，罗马人称其为**巴克斯**。古希腊人在**雅典酒神节**祭祀他，歌队演唱**酒神颂**，并在节日中演出戏剧，这成为**悲剧和喜剧的起源**。**尼采**在《悲剧的诞生》中以**酒神精神**（狂放、非理性）与**日神精神**（阿波罗，理性、秩序）对举，来阐释希腊艺术。","pts":["酒神，罗马称巴克斯","酒神节演剧，悲剧与喜剧的起源","尼采以酒神精神对日神精神"],"mem":"两个神对举：日神阿波罗讲秩序与形式，酒神狄俄尼索斯讲狂欢与冲动。口诀：“日神造形，酒神醉舞。”戏剧诞生于酒神节。","mix":"酒神精神是尼采《悲剧的诞生》的核心术语，日神精神与之对举；酒神是狄俄尼索斯，不是宙斯；罗马名巴克斯，不要与朱庇特混。","mcq":[{"q":"古希腊悲剧和喜剧的起源与下列哪位神的祭祀有关","o":["阿波罗","雅典娜","赫尔墨斯","狄俄尼索斯"],"a":3,"w":"戏剧起源于酒神狄俄尼索斯的祭祀活动。"}],"rel":[{"t":"尼采","n":"以酒神精神阐释悲剧"},{"t":"古希腊三大悲剧家","n":"在酒神节上演剧"},{"t":"希腊神祇的罗马名对应","n":"罗马名巴克斯"},{"t":"阿里斯托芬","n":"喜剧诞生于同一节日"}],"exam":[]},{"id":"a09-014","t":"阿波罗（日神）","cid":"09c","p":3,"kind":"人物","exam":[],"alias":[],"one":"光明、音乐、诗歌、预言之神；德尔斐阿波罗神庙刻有“认识你自己”。","ans":"光明、音乐、诗歌、预言之神；德尔斐阿波罗神庙刻有“认识你自己”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-015","t":"雅典娜","cid":"09c","p":3,"kind":"人物","exam":[],"alias":[],"one":"智慧与战争女神，从宙斯头中诞生，帕特农神庙供奉；罗马称密涅瓦。","ans":"智慧与战争女神，从宙斯头中诞生，帕特农神庙供奉；罗马称密涅瓦。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-016","t":"阿芙洛狄忒（维纳斯）","cid":"09c","p":3,"kind":"人物","exam":[],"alias":[],"one":"爱与美之神，罗马称维纳斯；金苹果之争中被帕里斯评为最美。","ans":"爱与美之神，罗马称维纳斯；金苹果之争中被帕里斯评为最美。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-017","t":"金苹果之争","cid":"09c","p":2,"kind":"常识","alias":["金苹果","不和的苹果","帕里斯的裁判","厄里斯的金苹果"],"one":"厄里斯投下“给最美者”的金苹果，引发特洛伊战争。","ans":"金苹果之争是**希腊神话中特洛伊战争的起因**。在英雄佩琉斯与忒提斯的婚宴上，**纷争女神厄里斯**因未受邀请，投下一只刻有**“给最美者”**的金苹果，**赫拉、雅典娜、阿芙洛狄忒**三位女神争夺。特洛伊王子**帕里斯**被请来裁判，他把苹果判给**阿芙洛狄忒**，换得她许诺的**海伦**，随后拐走斯巴达王后海伦，引发希腊联军远征，**特洛伊战争**爆发。后来这个典故喻**争端的根源**。","pts":["厄里斯投金苹果“给最美者”","三女神争，帕里斯判给阿芙洛狄忒","换得海伦，引发特洛伊战争"],"mem":"三位女神：赫拉（权力）、雅典娜（智慧与战争）、阿芙洛狄忒（爱与美），帕里斯选了爱，就得了海伦，也丢了城。逻辑线：苹果，裁判，海伦，战争。","mix":"“金苹果”指厄里斯所投的这只，与赫拉克勒斯十二件大功中摘取的赫斯珀里得斯金苹果是两个故事。","mcq":[{"q":"金苹果之争中，帕里斯把金苹果判给了","o":["赫拉","雅典娜","阿芙洛狄忒","厄里斯"],"a":2,"w":"帕里斯选择阿芙洛狄忒，换取海伦。"}],"rel":[{"t":"特洛伊战争","n":"该典故引发的战争"},{"t":"荷马史诗","n":"战争背景"},{"t":"希腊神祇的罗马名对应","n":"阿芙洛狄忒罗马名维纳斯"},{"t":"特洛伊木马","n":"战争结局"}],"exam":[]},{"id":"a09-018","t":"特洛伊木马","cid":"09c","p":2,"kind":"常识","alias":["木马计","木马","特洛伊木马计","木马屠城"],"one":"奥德修斯献计，希腊人藏身木马攻陷特洛伊。","ans":"特洛伊木马是**特洛伊战争中希腊人攻陷特洛伊城的计谋**，由**奥德修斯**献计。希腊联军围城十年不下，便造一匹巨大的**木马**，将精兵藏于**马腹**，假装撤兵。特洛伊人将木马拖入城内，夜里希腊人从马腹中出来，**里应外合**攻破城池。这一情节在**维吉尔《埃涅阿斯纪》第二卷**中有详细描写。后来“特洛伊木马”**比喻内部潜伏的破坏者**，也指计算机中的木马病毒。","pts":["奥德修斯献计，木马藏兵","特洛伊人拉入城，里应外合","维吉尔第二卷详述，今喻潜伏威胁"],"mem":"画面：城外留下一座大木马，城里人当战利品拖进去，半夜马肚子打开。谚语“送礼的希腊人也要提防”，出自维吉尔笔下拉奥孔的警告。","mix":"木马计详细见于《埃涅阿斯纪》第二卷，《伊利亚特》写到阿喀琉斯之死之前就结束了，没有木马；《奥德赛》只是简略提及。","mcq":[{"q":"详细描写“特洛伊木马”情节的古罗马史诗是","o":["《伊利亚特》","《神曲》","《埃涅阿斯纪》","《变形记》"],"a":2,"w":"《埃涅阿斯纪》第二卷借埃涅阿斯之口讲述木马陷城。"}],"rel":[{"t":"特洛伊战争","n":"所属战争"},{"t":"奥德修斯","n":"献计者"},{"t":"《埃涅阿斯纪》","n":"第二卷详述"},{"t":"荷马史诗","n":"战争背景史诗"}],"exam":[]},{"id":"a09-019","t":"奥德修斯","cid":"09c","p":2,"kind":"人物","alias":["尤利西斯","奥德修","伊塔卡国王","奥德赛主角"],"one":"伊塔卡国王，献木马计，《奥德赛》写其十年漂泊返乡。","ans":"奥德修斯是**希腊神话中伊塔卡的国王**，特洛伊战争中以**足智多谋**著称，**献木马计**攻陷特洛伊。荷马史诗**《奥德赛》**写他战后**漂泊十年**才返回家乡：途中遇到**独眼巨人**、塞壬女妖等，最终回到妻子**珀涅罗珀**身边，惩办求婚者。拉丁名**尤利西斯**，爱尔兰作家**乔伊斯**的小说《尤利西斯》借用了这一结构，把一天的都柏林生活对应史诗中的漂泊。","pts":["伊塔卡国王，足智多谋，献木马计","《奥德赛》：十年漂泊返乡","拉丁名尤利西斯，乔伊斯小说借用"],"mem":"对照记：阿喀琉斯是力量，奥德修斯是智慧；《伊利亚特》写战争，《奥德赛》写回家。奥德修斯（Odysseus）对应 Ulysses。","mix":"《伊利亚特》以阿喀琉斯的愤怒为主线，《奥德赛》以奥德修斯返乡为主线；奥德修斯与埃涅阿斯同属特洛伊战争中人物，但埃涅阿斯是特洛伊一方。","mcq":[{"q":"小说《尤利西斯》借用了哪部史诗的结构","o":["《奥德赛》","《伊利亚特》","《埃涅阿斯纪》","《神曲》"],"a":0,"w":"乔伊斯《尤利西斯》对应《奥德赛》，尤利西斯即奥德修斯的拉丁名。"}],"rel":[{"t":"荷马史诗","n":"他所在史诗"},{"t":"特洛伊木马","n":"他献的计策"},{"t":"《尤利西斯》","n":"现代回响"},{"t":"乔伊斯","n":"小说作者"}],"exam":[]},{"id":"a09-020","t":"西西弗斯","cid":"09c","p":2,"kind":"人物","alias":["西绪福斯","推石上山","西西弗","西西弗斯神话"],"one":"受罚推石上山、石落复推的人物，加缪借以阐释荒诞。","ans":"西西弗斯是**希腊神话中的科林斯国王**，因欺骗诸神而受罚：他必须把一块巨石推上山顶，**巨石到顶又滚落**，如此**永无止息**。这个形象成为**无望而重复的劳作**的象征。法国作家**加缪**在《西西弗神话》（1942）中以他阐释**荒诞哲学**，提出面对荒诞既不逃避也不自杀，而是**清醒地反抗**，并写下“必须想象西西弗斯是幸福的”，使这一神话进入20世纪存在主义文学。","pts":["受罚推石上山，石落复推","象征无望而重复的劳作","加缪《西西弗神话》阐释荒诞与反抗"],"mem":"画面：石头推到山顶，一松手滚下去，再从头来。加缪的态度是：推石头本身就是意义，所以西西弗斯幸福。","mix":"普罗米修斯是盗火被缚在高加索山，西西弗斯是推石头；两个受罚的神话人物不要张冠李戴。加缪是荒诞哲学代表，萨特是存在主义代表。","mcq":[{"q":"加缪《西西弗神话》中，西西弗斯被罚做的是","o":["背负天空","推巨石上山","永远渴而不得饮水","日日被鹰啄肝"],"a":1,"w":"西西弗斯被罚推石上山，石到山顶又滚落。"}],"rel":[{"t":"加缪","n":"《西西弗神话》作者"},{"t":"存在主义","n":"荒诞观所属思潮"},{"t":"普罗米修斯","n":"另一受罚的神话人物"},{"t":"古希腊文明","n":"神话出处"}],"exam":[]},{"id":"a09-021","t":"赫拉克勒斯","cid":"09c","p":2,"kind":"人物","alias":["赫拉克勒斯","大力神","海格力斯","赫丘利","十二件大功","赫拉克勒斯之柱"],"one":"宙斯之子，完成十二件大功；罗马称赫丘利。","ans":"赫拉克勒斯是**希腊神话中最著名的英雄**，**宙斯与凡间女子阿尔克墨涅之子**，以**神力**闻名，罗马称**赫丘利**。他因受赫拉迫害，在疯狂中杀死妻儿，为赎罪为国王服役，完成**十二件大功**，如杀死涅墨亚狮子、勒拿九头蛇，擒冥界三头犬等。传说他在大西洋口立起**赫拉克勒斯之柱**，指**直布罗陀海峡两岸的岬角**，古人视为已知世界的西界。","pts":["宙斯之子，大力英雄","十二件大功","赫拉克勒斯之柱，直布罗陀海峡"],"mem":"“十二”凑成整数：十二大功，对应十二主神。罗马名赫丘利（Hercules），英语沿用。口诀：“力气大，功十二，立柱在海峡。”","mix":"赫拉克勒斯是半神英雄，不是奥林匹斯十二主神之一；“赫拉克勒斯之柱”是地理指称，在直布罗陀海峡，不是希腊本土的神庙立柱。","mcq":[{"q":"“赫拉克勒斯之柱”指的是","o":["博斯普鲁斯海峡","苏伊士运河两岸","爱琴海入口","直布罗陀海峡两岸的岬角"],"a":3,"w":"古人视直布罗陀海峡为已知世界的西界，传说由赫拉克勒斯所立。"}],"rel":[{"t":"宙斯","n":"其父"},{"t":"希腊神祇的罗马名对应","n":"罗马名赫丘利"},{"t":"奥德修斯","n":"同为希腊英雄"},{"t":"古希腊文明","n":"所属神话传统"}],"exam":[]},{"id":"a09-022","t":"那喀索斯","cid":"09c","p":3,"kind":"人物","exam":[],"alias":[],"one":"爱上自己水中倒影的美少年，化为水仙花；英语narcissism（自恋）由此而","ans":"爱上自己水中倒影的美少年，化为水仙花；英语narcissism（自恋）由此而来。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-023","t":"伊卡洛斯","cid":"09c","p":3,"kind":"人物","exam":[],"alias":[],"one":"代达罗斯之子，用蜡粘羽翼飞行，飞近太阳蜡化坠海；喻狂妄冒进。","ans":"代达罗斯之子，用蜡粘羽翼飞行，飞近太阳蜡化坠海；喻狂妄冒进。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-024","t":"皮格马利翁","cid":"09c","p":3,"kind":"人物","exam":[],"alias":[],"one":"塞浦路斯国王（雕刻家）爱上自己雕的少女像，爱神使之复活；“皮格马利翁效应”指","ans":"塞浦路斯国王（雕刻家）爱上自己雕的少女像，爱神使之复活；“皮格马利翁效应”指期望效应；萧伯纳剧作《卖花女》原名《皮格马利翁》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-025","t":"达摩克利斯之剑","cid":"09c","p":3,"kind":"常识","exam":[],"alias":[],"one":"叙拉古僭主狄奥尼修斯让廷臣达摩克利斯坐在头顶用一根马鬃悬剑的宝座上，喻安逸中","ans":"叙拉古僭主狄奥尼修斯让廷臣达摩克利斯坐在头顶用一根马鬃悬剑的宝座上，喻安逸中潜藏的危险；见西塞罗著作。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-026","t":"希腊神祇的罗马名对应","cid":"09c","p":2,"kind":"常识","alias":["希腊罗马神名对照","希腊神话罗马名","罗马神话名"],"one":"希腊神名与罗马神名一一对应，行星多用罗马名。","ans":"古罗马人把本土神与**希腊神祇**一一对应，形成两套名称。对应有：**宙斯/朱庇特，赫拉/朱诺，波塞冬/尼普顿，雅典娜/密涅瓦，阿芙洛狄忒/维纳斯，阿瑞斯/玛尔斯，赫耳墨斯/墨丘利，狄俄尼索斯/巴克斯，厄洛斯/丘比特**。阿波罗在罗马沿用原名。西方文学中两套名称并用；英语行星名**木星、金星、火星、水星、海王星**等多用罗马名。","pts":["宙斯/朱庇特，赫拉/朱诺","雅典娜/密涅瓦，阿芙洛狄忒/维纳斯","行星名多用罗马名"],"mem":"口诀按“天、海、智、爱、战”记：宙斯朱庇特（天），波塞冬尼普顿（海），雅典娜密涅瓦（智），阿芙洛狄忒维纳斯（爱），阿瑞斯玛尔斯（战）。行星：木 Jupiter，金 Venus，火 Mars，水 Mercury，海 Neptune。","mix":"选择题常把希腊名与罗马名混作对应错位，如把雅典娜对到维纳斯；阿波罗两套体系用同一个名字。","mcq":[{"q":"古希腊神话中的雅典娜，在古罗马神话中对应的是","o":["维纳斯","朱诺","狄安娜","密涅瓦"],"a":3,"w":"雅典娜对应密涅瓦；维纳斯对应阿芙洛狄忒；朱诺对应赫拉。"}],"rel":[{"t":"宙斯","n":"首神，罗马名朱庇特"},{"t":"雅典娜","n":"罗马名密涅瓦"},{"t":"狄俄尼索斯（酒神）","n":"罗马名巴克斯"},{"t":"希腊神话","n":"两套神话体系基础"}],"more":"更多对应：赫菲斯托斯/伏尔甘，阿尔忒弥斯/狄安娜，德墨忒尔/刻瑞斯，克洛诺斯/萨图尔努斯，哈迪斯/普路托。","exam":[]},{"id":"a09-027","t":"两希文明（希腊传统与希伯来传统）","cid":"09c","p":1,"kind":"概念","alias":["两希","两希文明","两希传统","希腊希伯来"],"one":"古希腊文化与希伯来基督教文化，并称西方文明两大源头。","ans":"两希文明指**古希腊文明与希伯来文明**，二者并称**西方文明的两大源头**。**古希腊传统重理性与人本**，在哲学、科学、戏剧、民主政治等方面奠基；**希伯来传统以《圣经》为载体，重信仰与宗教伦理**，强调一神信仰、原罪与救赎，后经**基督教**传入欧洲。两种传统在**罗马帝国后期由基督教神学融合**，中世纪经院哲学是典型表现，也在西方文学中交织：古典神话与《圣经》故事同为典故来源。理解**理性与信仰、人本与神本**的张力，是读懂西方文化的钥匙。","pts":["古希腊与希伯来并称西方文明源头","希腊重理性人本，希伯来重信仰宗教伦理","基督教神学融合二者，影响中世纪与近代"],"mem":"一个对照表：希腊“理性、人本、多神、城邦民主”，希伯来“信仰、神本、一神、《圣经》”。口诀“智与信”：希腊讲智，希伯来讲信。交大考过古希腊（2017至2019名解）和希伯来（2014名解），答题时可以互相点到。","mix":"两希不等于“希腊和罗马”：罗马是继承者和传播者，不是第三个源头。《圣经》的《旧约》本是希伯来经典，《新约》产生于基督教。","mcq":[{"q":"西方文明的“两希”源头是","o":["希腊与罗马","希腊与希伯来","罗马与希伯来","希腊与埃及"],"a":1,"w":"两希指古希腊与希伯来，罗马是继承与传播者。"},{"q":"下列属于希伯来传统的是","o":["《圣经》","《荷马史诗》","《理想国》","《诗学》"],"a":0,"w":"《圣经》是希伯来与基督教传统的经典；其余三项属希腊传统。"}],"rel":[{"t":"希伯来","n":"两希之一"},{"t":"古希腊文明","n":"两希之一"},{"t":"《圣经》","n":"希伯来传统的载体"},{"t":"《七十子希腊文本》","n":"两种传统相遇的译本"},{"t":"基督教成为罗马国教","n":"融合的政治背景"}],"more":"19世纪英国批评家阿诺德在《文化与无政府状态》中对举“希腊精神”与“希伯来精神”。","exam":[]},{"id":"a09-028","t":"《俄狄浦斯王》","cid":"09d","p":2,"kind":"作品","alias":["俄狄浦斯王","《俄狄浦斯》","伊底帕斯王"],"one":"索福克勒斯所作命运悲剧，亚里士多德视为悲剧典范。","ans":"《俄狄浦斯王》是**古希腊悲剧家索福克勒斯**约前429年前后创作的悲剧，被亚里士多德《诗学》视为**悲剧典范**。剧情写忒拜城遭瘟疫，国王**俄狄浦斯**追查杀死前王的凶手，结果发现凶手正是自己，**他杀父娶母**的神谕已经应验，于是刺瞎双眼自我放逐。全剧结构紧凑，**发现与突转**同时发生，是**“命运悲剧”**的代表，对西方戏剧及弗洛伊德的精神分析都有深远影响。","pts":["索福克勒斯作，约前429年前后","追查凶手发现是自己，杀父娶母","命运悲剧代表，《诗学》的典范"],"mem":"侦探剧结构：查案，线索全指向自己，真相揭晓。亚里士多德《诗学》用它说明“突转”和“发现”。口诀：“俄狄浦斯，查案查到自己头上”。","mix":"作者是索福克勒斯，不是欧里庇得斯或埃斯库罗斯；欧里庇得斯名作是《美狄亚》，埃斯库罗斯名作是《被缚的普罗米修斯》。","mcq":[{"q":"《俄狄浦斯王》的作者是","o":["埃斯库罗斯","索福克勒斯","欧里庇得斯","阿里斯托芬"],"a":1,"w":"《俄狄浦斯王》是索福克勒斯的代表作。"}],"rel":[{"t":"索福克勒斯","n":"作者"},{"t":"俄狄浦斯","n":"主人公"},{"t":"古希腊三大悲剧家","n":"同属一派"},{"t":"宿命论","n":"命运观体现"}],"exam":[]},{"id":"a09-029","t":"《安提戈涅》","cid":"09d","p":3,"kind":"作品","exam":[],"alias":[],"one":"索福克勒斯作，安提戈涅违抗国王克瑞翁禁令安葬兄长而被处死；黑格尔以之说明两种","ans":"索福克勒斯作，安提戈涅违抗国王克瑞翁禁令安葬兄长而被处死；黑格尔以之说明两种伦理力量的冲突。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-030","t":"《美狄亚》","cid":"09d","p":3,"kind":"作品","exam":[],"alias":[],"one":"美狄亚因丈夫伊阿宋背弃而杀子复仇。","ans":"美狄亚因丈夫伊阿宋背弃而杀子复仇。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-031","t":"《诗学》","cid":"09d","p":1,"kind":"作品","alias":["诗学","亚里士多德《诗学》"],"one":"亚里士多德著，西方第一部系统的文艺理论著作。","ans":"《诗学》是**古希腊哲学家亚里士多德的文艺理论著作**，被认为是**西方第一部系统的文艺理论著作**。书中提出**模仿说**，认为艺术是对现实的模仿，并认为诗比历史更带有普遍性；给悲剧下定义，指出悲剧**借引起怜悯与恐惧使情感得到净化（陶冶）**，并分析了悲剧的**六个要素：情节、性格、言词、思想、戏景、唱段**，其中**情节最重要，要求情节整一**。《诗学》奠定了西方戏剧理论，**贺拉斯《诗艺》继承发展，后人据此引申出三一律**，17世纪被法国古典主义奉为圭臬。","pts":["亚里士多德著，西方第一部系统文艺理论","模仿说、净化说，悲剧六要素，情节整一","影响贺拉斯《诗艺》与三一律"],"mem":"“一说两学”：一个“模仿说”，一个“净化说”（怜悯与恐惧），再加悲剧六要素。六要素口诀：“情性言思景唱”（情节、性格、言词、思想、戏景、唱段），情节排第一。对照柏拉图：柏拉图说艺术是影子的影子，亚里士多德说模仿能表现普遍真理，诗比历史更真实。","mix":"《诗学》只明确提出行动整一，三一律是后人引申；贺拉斯《诗艺》是古罗马作品，不是亚里士多德所作。亚里士多德的《政治学》《形而上学》是另外的著作。","mcq":[{"q":"提出悲剧能引起怜悯与恐惧并使情感得到净化的是","o":["柏拉图","贺拉斯","布瓦洛","亚里士多德"],"a":3,"w":"净化说出自亚里士多德《诗学》。"},{"q":"《诗学》认为悲剧六要素中最重要的是","o":["情节","性格","唱段","戏景"],"a":0,"w":"六要素中情节最重要，要求整一。"}],"rel":[{"t":"亚里士多德","n":"《诗学》作者"},{"t":"三一律","n":"后世据此引申"},{"t":"《诗艺》","n":"罗马的继承之作"},{"t":"古希腊三大悲剧家","n":"《诗学》分析的对象"},{"t":"《文心雕龙》","n":"中国的系统文论"}],"more":"悲剧定义要点：对一个严肃、完整、有一定长度的行动的模仿，通过引起怜悯与恐惧使这些情感得到净化。","exam":[]},{"id":"a09-032","t":"米南德与新喜剧","cid":"09d","p":3,"kind":"人物","exam":[],"alias":[],"one":"前4世纪后期雅典新喜剧代表，写日常家庭生活，影响古罗马普劳图斯、泰伦斯和后来","ans":"前4世纪后期雅典新喜剧代表，写日常家庭生活，影响古罗马普劳图斯、泰伦斯和后来的莫里哀。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-033","t":"米利都学派","cid":"09e","p":2,"kind":"流派","alias":["米利都学派","爱奥尼亚学派","泰勒斯学派"],"one":"西方第一个哲学派别，泰勒斯、阿那克西曼德、阿那克西美尼。","ans":"米利都学派是**前6世纪兴起于小亚细亚米利都城的古希腊哲学派别**，也是**西方最早的哲学派别**，因所处地区也称爱奥尼亚学派。代表人物有**泰勒斯、阿那克西曼德、阿那克西美尼**，他们都以某种**自然物质**为万物本原：泰勒斯主张**水**，阿那克西曼德主张**无定**，阿那克西美尼主张**气**。他们用自然本身解释自然，属**朴素唯物主义**，使哲学摆脱了神话。","pts":["最早的哲学派别，米利都","泰勒斯水、阿那克西曼德无定、阿那克西美尼气","朴素唯物主义，脱离神话"],"mem":"三人口诀：泰勒斯水，阿那克西曼德无定，阿那克西美尼气。名字长的“曼德”对应抽象的“无定”，“美尼”对应日常的“气”。","mix":"阿那克西曼德与阿那克西美尼名字相近，前者是无定，后者是气；赫拉克利特（火）属以弗所，不属米利都学派。","mcq":[{"q":"下列哲学家中，不属于米利都学派的是","o":["赫拉克利特","泰勒斯","阿那克西曼德","阿那克西美尼"],"a":0,"w":"赫拉克利特是以弗所人，主张火为本原。"}],"rel":[{"t":"泰勒斯","n":"学派创始人"},{"t":"本原（始基）","n":"核心问题"},{"t":"朴素唯物主义","n":"学派思想性质"},{"t":"赫拉克利特","n":"其后以弗所哲学家"}],"exam":[]},{"id":"a09-034","t":"本原（始基）","cid":"09e","p":2,"kind":"概念","alias":["始基","万物本原","阿尔克","arche"],"one":"古希腊哲学追问的万物起源与构成。","ans":"本原又译始基，指**古希腊哲学家追问的万物起源与构成的根本**，希腊语 arche。早期哲学家提出各种答案：**泰勒斯说水，阿那克西美尼说气，赫拉克利特说火，毕达哥拉斯说数，德谟克利特说原子**，恩培多克勒又提出土、水、气、火四根。这类追问标志着**哲学从神话中独立**，用自然解释自然。以具体物质为本原的观点属**朴素唯物主义**。","pts":["万物起源与构成的根本","水气火数原子各说","标志哲学脱离神话"],"mem":"一串本原：水（泰勒斯）、气（阿那克西美尼）、火（赫拉克利特）、数（毕达哥拉斯）、原子（德谟克利特）。口诀：“泰水阿气赫火毕数德原子”。","mix":"数（毕达哥拉斯）不是物质，故不算朴素唯物主义，常单独记；阿那克西曼德的“无定”也不是具体物质。","mcq":[{"q":"主张“火是万物本原”的哲学家是","o":["泰勒斯","毕达哥拉斯","德谟克利特","赫拉克利特"],"a":3,"w":"赫拉克利特以火为本原，并提出万物流变。"}],"rel":[{"t":"朴素唯物主义","n":"以物质为本原的立场"},{"t":"泰勒斯","n":"水本原"},{"t":"赫拉克利特","n":"火本原"},{"t":"德谟克利特","n":"原子论"}],"exam":[]},{"id":"a09-035","t":"逻各斯","cid":"09e","p":2,"kind":"概念","alias":["逻各斯","Logos","道（逻各斯）"],"one":"赫拉克利特用来指万物变化的普遍规律，后为斯多葛与基督教借用。","ans":"逻各斯是**古希腊哲学概念**，希腊语 logos，本意为言说、理性、尺度。**赫拉克利特**用它指**万物变化所遵循的普遍规律**，即宇宙秩序。**斯多葛派**把逻各斯看作支配世界的理性，**基督教**《约翰福音》开篇“**太初有道**”的“道”即逻各斯，指上帝之言。这一概念贯穿西方思想史，常与中国哲学的**“道”**对照。","pts":["赫拉克利特：万物遵循的普遍规律","斯多葛派的世界理性","《约翰福音》“太初有道”"],"mem":"三站接力：赫拉克利特（规律），斯多葛（理性），基督教（上帝之言）。中西对举：逻各斯对“道”，都有规律、言说两层意思。","mix":"logos 与“逻辑”（logic）同源；《约翰福音》的“道”即逻各斯，常与老子的“道”对照，但两者不是同一概念。","mcq":[{"q":"《约翰福音》“太初有道”中的“道”对应希腊哲学的","o":["努斯","逻各斯","原子","理念"],"a":1,"w":"“道”原文为 logos，即逻各斯。"}],"rel":[{"t":"赫拉克利特","n":"最早的使用者"},{"t":"斯多葛学派","n":"借用并发展"},{"t":"《圣经》","n":"《约翰福音》出处"},{"t":"老子","n":"中国“道”对照"}],"exam":[]},{"id":"a09-036","t":"爱利亚学派与巴门尼德","cid":"09e","p":2,"kind":"流派","alias":["爱利亚学派","巴门尼德","存在论","埃利亚学派"],"one":"爱利亚学派主张“存在”唯一不变，与赫拉克利特流变对立。","ans":"爱利亚学派是**前5世纪活动于意大利南部爱利亚城的古希腊哲学派别**，**巴门尼德**为其代表，色诺芬尼为先驱，**芝诺**为弟子。巴门尼德在哲学诗中提出**“存在者存在，非存在者不存在”**，主张**“存在”是唯一、不生不灭、不动不变的整体**，感官所见的变化和多样只是“意见”，只有理性思维才能把握真理。他与**赫拉克利特的流变**学说对立，开创了西方**本体论**的传统。","pts":["爱利亚城，巴门尼德代表","存在唯一不动不变","感官是意见，与流变学说对立"],"mem":"一动一静：赫拉克利特“万物皆流”，巴门尼德“存在不动”。口诀：“赫流巴静”。弟子芝诺用悖论替老师辩护。","mix":"赫拉克利特强调变化，巴门尼德否认变化；巴门尼德的“存在”不同于一般具体事物，是抽象的“是”。","mcq":[{"q":"主张“存在”唯一、不动不变的是","o":["赫拉克利特","德谟克利特","巴门尼德","泰勒斯"],"a":2,"w":"巴门尼德认为存在不动不变，赫拉克利特主张流变。"}],"rel":[{"t":"赫拉克利特","n":"主张流变的对立者"},{"t":"芝诺悖论","n":"弟子的论证"},{"t":"本原（始基）","n":"哲学追问对照"},{"t":"逻各斯","n":"同一时期概念"}],"exam":[]},{"id":"a09-037","t":"芝诺悖论","cid":"09e","p":2,"kind":"概念","alias":["芝诺","飞矢不动","阿基里斯追龟","阿基里斯追不上乌龟"],"one":"爱利亚学派芝诺的运动悖论：阿基里斯追不上乌龟，飞矢不动。","ans":"芝诺悖论是**古希腊爱利亚学派哲学家芝诺**（约前490–约前430）提出的一组论证，意在**否定运动和多**，以支持老师**巴门尼德**的“存在不动”之说。著名的有**“阿基里斯追不上乌龟”**：追者每次到达对方出发点时，对方已前进一段，永远追不上；**“飞矢不动”**：飞行中的箭在每一瞬间都占据一个确定位置，因此静止。这些悖论推动了对**无限、连续与运动**的思考，亚里士多德在《物理学》中加以讨论。","pts":["爱利亚学派芝诺提出","阿基里斯追不上乌龟、飞矢不动","否定运动，支持巴门尼德"],"mem":"画面：乌龟先跑一步，阿基里斯去追，每追到它原来的位置，它又前进一点，没完没了。中国对照：《庄子·天下》“飞鸟之影未尝动也”与“一尺之棰，日取其半，万世不竭”。","mix":"芝诺悖论是为巴门尼德辩护，不是证明现实中追不上；中国惠施、公孙龙的辩题（如“白马非马”）属名辩之学，思路相近但不是同一学派。","mcq":[{"q":"“阿基里斯追不上乌龟”属于下列哪位哲学家的悖论","o":["赫拉克利特","芝诺","德谟克利特","毕达哥拉斯"],"a":1,"w":"这一悖论是爱利亚学派芝诺为否定运动而提出的。"}],"rel":[{"t":"爱利亚学派与巴门尼德","n":"师承所属学派"},{"t":"惠施与公孙龙","n":"中国名辩对照"},{"t":"《庄子》","n":"《天下》篇相近命题"},{"t":"赫拉克利特","n":"主张流变的对立学说"}],"exam":[]},{"id":"a09-038","t":"恩培多克勒“四根说”","cid":"09e","p":3,"kind":"概念","exam":[],"alias":[],"one":"土、水、火、气四种元素在“爱”与“争”作用下聚散形成万物；可与五行说对照。","ans":"土、水、火、气四种元素在“爱”与“争”作用下聚散形成万物；可与五行说对照。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-039","t":"智者学派","cid":"09e","p":2,"kind":"流派","alias":["智者派","诡辩学派","普罗泰戈拉","高尔吉亚"],"one":"前5世纪雅典收费授徒的职业教师，哲学由自然转向人。","ans":"智者学派是**前5世纪活跃于雅典的一批职业教师**，以收费传授修辞、论辩和从政本领为业，代表人物有**普罗泰戈拉**和高尔吉亚。民主政治使公民必须在公民大会和法庭上说服他人，智者应运而生。普罗泰戈拉提出**“人是万物的尺度”**，主张真理因人而异，带有相对主义色彩。智者把哲学关注点从自然本原转向**人与社会**，是希腊哲学的转折点，也因相对主义和重辩术而受到苏格拉底、柏拉图批评。","pts":["前5世纪雅典收费教授修辞论辩的教师","普罗泰戈拉：人是万物的尺度","哲学由自然转向人，被苏格拉底批评"],"mem":"逻辑线：民主城邦要靠嘴说服人，于是有人开班收费教说话，这就是智者。再记一句话：泰勒斯们问“世界由什么做成”，智者问“人该怎么活、怎么说”。名句“人是万物的尺度”只记普罗泰戈拉一人。","mix":"智者（Sophist）后来带贬义，“诡辩”一词由此而来；苏格拉底同样讨论人，但他追求普遍的定义和美德，不收学费，与智者的相对主义对立。","mcq":[{"q":"提出“人是万物的尺度”的是","o":["苏格拉底","柏拉图","普罗泰戈拉","德谟克利特"],"a":2,"w":"这句话出自智者学派代表普罗泰戈拉。"}],"rel":[{"t":"苏格拉底","n":"批评智者的相对主义"},{"t":"泰勒斯","n":"此前追问自然本原"},{"t":"雅典民主","n":"智者出现的政治土壤"}],"exam":[]},{"id":"a09-040","t":"苏格拉底之死","cid":"09f","p":2,"kind":"事件","alias":["苏格拉底审判","苏格拉底受审","饮鸩","毒芹汁"],"one":"前399年，苏格拉底被雅典法庭判死刑，拒绝出逃，饮毒芹汁而死。","ans":"苏格拉底之死发生在**前399年的雅典**。他被指控**“不敬城邦的神”和“败坏青年”**，由500人的陪审法庭表决判处死刑。友人安排他越狱，他认为应服从城邦法律，**拒绝出逃**，在狱中**饮毒芹汁**而死。这一经过由弟子**柏拉图**写入《申辩篇》《克里托篇》和《斐多篇》。苏格拉底以生命坚持探求真理，被视为**为哲学殉道**的象征，也暴露了雅典民主制的缺陷。","pts":["前399年，罪名不敬神、败坏青年","拒绝出逃，饮毒芹汁而死","柏拉图《申辩篇》《斐多篇》记述"],"mem":"年份记“前399”，罪名记“两条”：不敬神、败坏青年。《申辩篇》是庭上辩护，《斐多篇》是临终谈灵魂不朽。联想法国画家大卫的名画《苏格拉底之死》。","mix":"苏格拉底本人述而不作，事迹来自柏拉图和色诺芬；“饮鸩”在西方是毒芹汁，不是中文语境的鸠毒。","mcq":[{"q":"关于苏格拉底之死，叙述正确的是","o":["被指控不敬神并败坏青年","死于希波战争的战场","被流放后病逝于马其顿","他在狱中写下了《理想国》"],"a":0,"w":"前399年他被雅典法庭判处死刑，饮毒芹汁而死。"}],"rel":[{"t":"苏格拉底","n":"事件主人公"},{"t":"柏拉图","n":"记述者"},{"t":"雅典民主","n":"判决所依的制度"}],"exam":[]},{"id":"a09-041","t":"助产术（苏格拉底方法）","cid":"09f","p":2,"kind":"概念","alias":["助产术","精神助产术","苏格拉底方法","反诘法","产婆术","诘问法"],"one":"苏格拉底以连续提问揭露矛盾、引导对方自己得出结论的方法。","ans":"助产术是**苏格拉底的对话方法**，又称**反诘法**。他自比母亲是助产婆，自己则是帮助别人“生产”思想的人。具体做法是**连续提问**，先让对方给出一个定义，再用反例揭露其中的矛盾，一步步引导对方自己得出正确的结论，而不是直接灌输答案。这种方法体现在柏拉图的早期对话中，是**启发式教学的源头**，常与孔子“不愤不启，不悱不发”相比较。","pts":["苏格拉底的提问对话法，又称反诘法","揭露矛盾，引导对方自己得出结论","启发式教学源头，可与孔子对照"],"mem":"类比：苏格拉底的母亲是助产婆，他说自己做的是帮人“接生”思想的事。中西对照：苏格拉底问到对方自己说不下去，孔子等学生“愤悱”再启发，两者都是不直接给答案。","mix":"助产术不是辩论取胜的技巧；智者重修辞说服，苏格拉底重求真。","mcq":[{"q":"苏格拉底通过不断提问、让对方自己发现真理的方法被称为","o":["洞穴比喻","形式逻辑","助产术","原子论"],"a":2,"w":"又称精神助产术或反诘法。"}],"rel":[{"t":"苏格拉底","n":"创立者"},{"t":"孔子的教育思想","n":"启发式教学中西对照"},{"t":"智者学派","n":"与重说服的智者相对"}],"exam":[]},{"id":"a09-042","t":"阿卡德米学园","cid":"09f","p":2,"kind":"常识","alias":["阿卡德米","柏拉图学园","学园","Academy","阿加德米"],"one":"柏拉图约前387年在雅典创办的学园，西方最早的高等学府之一。","ans":"阿卡德米学园是**柏拉图约前387年在雅典城外创办的学园**，因建在纪念英雄阿卡德摩斯的园地而得名。学园以数学、哲学和政治学为教学重点，据说门口写着“不懂几何者莫入”。**亚里士多德**曾在此学习近二十年，后另创吕克昂学园。学园延续约**900年**，直到529年被**东罗马皇帝查士丁尼**关闭。西方语言中的**“academy”（学院）一词**由此而来，学园是西方高等教育的重要源头。","pts":["柏拉图约前387年在雅典创办","亚里士多德曾在此学习近二十年","529年被查士丁尼关闭，academy词源"],"mem":"数字：前387创办，529关闭，前后约900年。词源一眼记：Academy＝阿卡德米，所以“学院”“科学院”都来自这座园子。","mix":"柏拉图的阿卡德米与亚里士多德的吕克昂（逍遥学派）是两座学园，别互换；前者在西北郊，后者在东郊。","mcq":[{"q":"英语中 academy 一词的来源，是柏拉图创办的","o":["吕克昂学园","伊壁鸠鲁花园","斯多葛画廊","阿卡德米学园"],"a":3,"w":"阿卡德米学园约前387年建于雅典，academy由此而来；吕克昂是亚里士多德所办。"}],"rel":[{"t":"柏拉图","n":"创办者"},{"t":"吕克昂学园与逍遥学派","n":"亚里士多德另立学园"},{"t":"中世纪大学","n":"西方高等教育后续"}],"exam":[]},{"id":"a09-043","t":"吕克昂学园与逍遥学派","cid":"09f","p":3,"kind":"常识","exam":[],"alias":[],"one":"亚里士多德在雅典创办，常边散步边讲学，故称逍遥学派。","ans":"亚里士多德在雅典创办，常边散步边讲学，故称逍遥学派。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-044","t":"形式逻辑与三段论","cid":"09f","p":2,"kind":"概念","alias":["三段论","形式逻辑","《工具论》","工具论"],"one":"亚里士多德创立的演绎推理，大前提、小前提、结论三部分。","ans":"形式逻辑由**亚里士多德**创立，他的逻辑著作后人汇编为**《工具论》**，意为认识事物的工具。其核心是**三段论**：由**大前提、小前提和结论**构成的演绎推理，典型例子是“凡人皆有死，苏格拉底是人，所以苏格拉底有死”。亚里士多德还总结了同一律、矛盾律、排中律等思维规律的雏形。形式逻辑是**西方科学思维和论证传统的基础**，直到近代培根提出归纳法，才与演绎法并立。","pts":["亚里士多德创立，著作汇编为《工具论》","三段论：大前提、小前提、结论","演绎推理，西方论证传统基础"],"mem":"万能例句背下来：凡人皆有死（大），苏格拉底是人（小），所以苏格拉底会死（结论）。书名“工具论”记“逻辑是求知的工具”。培根《新工具》对着它写，主张归纳。","mix":"培根《新工具》（归纳法）是针对亚里士多德《工具论》（演绎法）而起名；中国先秦墨家、名家也有逻辑思想，但不叫三段论。","mcq":[{"q":"以“凡人皆有死，苏格拉底是人，所以苏格拉底有死”为典型例子的推理形式是","o":["归纳法","类比","辩证法","三段论"],"a":3,"w":"亚里士多德创立的三段论属演绎推理。"}],"rel":[{"t":"亚里士多德","n":"创立者"},{"t":"弗朗西斯·培根","n":"归纳法对演绎法"},{"t":"经验论与唯理论","n":"近代归纳与演绎之争"}],"exam":[]},{"id":"a09-045","t":"吾爱吾师，吾更爱真理","cid":"09f","p":2,"kind":"常识","alias":["吾爱吾师吾更爱真理","吾爱吾师，但吾更爱真理"],"one":"亚里士多德名言，表达对老师柏拉图理念论的批评态度。","ans":"“吾爱吾师，吾更爱真理”是**亚里士多德的名言**，通常认为反映他对老师**柏拉图理念论**的态度。亚里士多德在阿卡德米学园随柏拉图学习近二十年，后来批评理念论使理念与个别事物相分离，主张**形式存在于具体事物之中**。这句话常被引用，表示**学术上尊敬老师而不盲从，把追求真理放在首位**，成为西方学术自由传统的格言，与中国“师不必贤于弟子”的说法相近。","pts":["亚里士多德名言","针对老师柏拉图的理念论","尊师而不盲从，真理优先"],"mem":"记“师徒对”：苏格拉底→柏拉图→亚里士多德三代师徒。这句话是第三代对第二代说的，口诀“亚爱真理”。中文对照：韩愈“弟子不必不如师”。","mix":"这句话的拉丁文流行版本出自后人概括，学界认为亚里士多德《尼各马可伦理学》中有近似意思；考试按“亚里士多德”作答即可。","mcq":[{"q":"“吾爱吾师，吾更爱真理”的说话者是","o":["亚里士多德","苏格拉底","柏拉图","伊壁鸠鲁"],"a":0,"w":"亚里士多德就理念论问题对老师柏拉图所说。"}],"rel":[{"t":"亚里士多德","n":"说话者"},{"t":"柏拉图","n":"其老师"},{"t":"理念论","n":"批评的对象"}],"exam":[]},{"id":"a09-046","t":"中道","cid":"09f","p":3,"kind":"概念","exam":[],"alias":[],"one":"《尼各马可伦理学》认为德性是过度与不及之间的适度。","ans":"《尼各马可伦理学》认为德性是过度与不及之间的适度。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-047","t":"犬儒学派与第欧根尼","cid":"09f","p":3,"kind":"流派","exam":[],"alias":[],"one":"主张摒弃世俗享受、回归自然；第欧根尼住木桶，对亚历山大说“请别挡住我的阳光”","ans":"主张摒弃世俗享受、回归自然；第欧根尼住木桶，对亚历山大说“请别挡住我的阳光”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-048","t":"柏拉图式爱情","cid":"09f","p":3,"kind":"概念","exam":[],"alias":[],"one":"源自柏拉图《会饮篇》，指超越肉体、追求精神交流的爱。","ans":"源自柏拉图《会饮篇》，指超越肉体、追求精神交流的爱。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-049","t":"新柏拉图主义","cid":"09f","p":3,"kind":"流派","exam":[],"alias":[],"one":"3世纪普罗提诺创立，以“太一”流溢说改造柏拉图哲学，影响奥古斯丁。","ans":"3世纪普罗提诺创立，以“太一”流溢说改造柏拉图哲学，影响奥古斯丁。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-050","t":"人是政治动物","cid":"09f","p":3,"kind":"常识","exam":[],"alias":[],"one":"亚里士多德称“人是天生的政治动物”；《政治学》比较各城邦政制，主张以中产阶级","ans":"亚里士多德称“人是天生的政治动物”；《政治学》比较各城邦政制，主张以中产阶级为基础的混合政体。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-051","t":"《埃涅阿斯纪》","cid":"09g","p":2,"kind":"作品","alias":["埃涅阿斯纪","埃涅伊德","Aeneid"],"one":"维吉尔所作文人史诗，写特洛伊英雄埃涅阿斯逃亡建国。","ans":"《埃涅阿斯纪》是**古罗马诗人维吉尔的史诗**，共十二卷，前29年起写作，至去世未完全定稿。全诗写**特洛伊英雄埃涅阿斯**在特洛伊陷落后率众逃亡，历经风浪，经迦太基抵达意大利，战胜当地部族，为日后**罗马建城**奠基。前半部分仿荷马《奥德赛》写漂泊，后半部分仿《伊利亚特》写战争。它是**西方文人史诗的典范**，歌颂罗马的使命与奥古斯都的统治，对但丁《神曲》、弥尔顿《失乐园》影响很大。","pts":["维吉尔作，十二卷文人史诗","埃涅阿斯逃出特洛伊，到意大利建国","为罗马起源立传，影响但丁"],"mem":"一条线：特洛伊陷落→逃亡漂泊→到意大利→为罗马奠基。对比荷马：《奥德赛》是回家（奥德修斯回伊萨卡），《埃涅阿斯纪》是出走建国，前六卷像奥德赛，后六卷像伊利亚特。","mix":"埃涅阿斯是特洛伊一方的英雄，不是希腊人；罗马建城者罗慕路斯是他的后裔。荷马史诗是民间史诗，本书是文人史诗。","mcq":[{"q":"《埃涅阿斯纪》的主人公是","o":["阿喀琉斯","埃涅阿斯","奥德修斯","贝奥武甫"],"a":1,"w":"埃涅阿斯是特洛伊英雄，逃出城后建国意大利；阿喀琉斯、奥德修斯是希腊英雄。"}],"rel":[{"t":"维吉尔","n":"作者"},{"t":"荷马史诗","n":"模仿的范本"},{"t":"民间史诗与文人史诗","n":"文人史诗的代表"},{"t":"特洛伊战争","n":"故事背景"}],"exam":[]},{"id":"a09-052","t":"《诗艺》","cid":"09g","p":2,"kind":"作品","alias":["诗艺","贺拉斯《诗艺》","致皮索书","诗的艺术（贺拉斯）"],"one":"贺拉斯以诗体书信写成的文论，提出寓教于乐和合式原则。","ans":"《诗艺》是**古罗马诗人贺拉斯的文学理论著作**，约成于前20年前后，以**诗体书信**形式写成，又称《致皮索书》。书中提出**“寓教于乐”**，要求诗既有益又有趣；提出**“合式”（得体）原则**，要求题材、人物、风格各得其宜；主张向希腊作家学习，推崇创作中的规则与技巧。它继承并发展了亚里士多德《诗学》，奠定了**古典主义文论**的基础，对17世纪法国布瓦洛《诗的艺术》影响很大。","pts":["贺拉斯作，诗体书信","寓教于乐，合式（得体）","继承《诗学》，影响古典主义"],"mem":"记两个关键词：教与乐，合与式。“寓教于乐”记“贺拉斯”，不要记成亚里士多德（他讲的是净化和模仿）。链条：亚里士多德《诗学》→贺拉斯《诗艺》→布瓦洛《诗的艺术》，三部“诗学”接力。","mix":"布瓦洛《诗的艺术》（1674）是17世纪法国古典主义的纲领，书名相近，不要混；亚里士多德《诗学》是希腊文论，贺拉斯是罗马。","mcq":[{"q":"提出“寓教于乐”的文论著作是","o":["亚里士多德《诗学》","贺拉斯《诗艺》","布瓦洛《诗的艺术》","柏拉图《理想国》"],"a":1,"w":"贺拉斯《诗艺》提出寓教于乐与合式原则。"}],"rel":[{"t":"贺拉斯","n":"作者"},{"t":"《诗学》","n":"继承的前作"},{"t":"布瓦洛《诗的艺术》","n":"后世古典主义继承"},{"t":"古典主义","n":"影响的文艺潮流"}],"exam":[]},{"id":"a09-053","t":"卢克莱修《物性论》","cid":"09g","p":3,"kind":"作品","exam":[],"alias":[],"one":"以长诗阐述伊壁鸠鲁原子论，古罗马唯物主义代表作。","ans":"以长诗阐述伊壁鸠鲁原子论，古罗马唯物主义代表作。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-054","t":"马可·奥勒留《沉思录》","cid":"09g","p":2,"kind":"作品","alias":["沉思录","马可·奥勒留","奥勒留","Meditations","自省录"],"one":"罗马皇帝马可·奥勒留的斯多葛派自省笔记，希腊文写成。","ans":"《沉思录》是**罗马皇帝马可·奥勒留的哲学笔记**，共十二卷，以**希腊文**写成。马可·奥勒留（121–180）是罗马**“五贤帝”**之一，同时是**斯多葛派哲学家**。书中多是他在军旅和政务之间写给自己的警句，主张顺应自然和理性，克制欲望，坦然面对命运与死亡，强调为公共利益尽责。该书是**斯多葛哲学的晚期代表作**，被视为“哲学家皇帝”的心灵记录，中文有何怀宏译本。","pts":["罗马五贤帝之一，斯多葛派","十二卷，希腊文写成的自省笔记","顺应自然、克制欲望、坦然面对命运"],"mem":"一句话：皇帝写给自己的自省笔记，核心是先管好自己的情绪和欲望。记两个反常：皇帝却是哲学家；罗马人却用希腊文写。他常被看作柏拉图“哲学王”理想的实例。","mix":"斯多葛派源于希腊（芝诺），罗马晚期代表还有塞涅卡、爱比克泰德；《沉思录》不是写给读者的著作，是自用笔记。","mcq":[{"q":"《沉思录》的作者马可·奥勒留所属的哲学派别是","o":["伊壁鸠鲁派","斯多葛派","怀疑论","智者学派"],"a":1,"w":"马可·奥勒留是罗马皇帝，也是斯多葛派哲学家。"}],"rel":[{"t":"斯多葛学派","n":"所属学派"},{"t":"伊壁鸠鲁","n":"希腊化哲学并峙"},{"t":"罗马共和国与帝国","n":"所处时代"}],"exam":[]},{"id":"a09-055","t":"塞涅卡","cid":"09g","p":3,"kind":"人物","exam":[],"alias":[],"one":"斯多葛派哲学家、悲剧作家，尼禄的老师。","ans":"斯多葛派哲学家、悲剧作家，尼禄的老师。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-056","t":"普鲁塔克《希腊罗马名人传》","cid":"09g","p":3,"kind":"作品","exam":[],"alias":[],"one":"又称《比较列传》，以希腊、罗马人物成对比较；莎士比亚的罗马剧多取材于此。","ans":"又称《比较列传》，以希腊、罗马人物成对比较；莎士比亚的罗马剧多取材于此。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-057","t":"拉丁语","cid":"09g","p":2,"kind":"常识","alias":["拉丁文","拉丁语系","罗曼语族"],"one":"古罗马语言，中世纪欧洲教会和学术通用语，罗曼语族的祖先。","ans":"拉丁语是**古罗马的语言**，属印欧语系的意大利语族。随着罗马征服地中海世界，拉丁语传遍西欧。西罗马帝国灭亡后，它成为**中世纪欧洲教会和学术的通用语言**，大学教学和学术著作长期使用拉丁文。口语拉丁语在各地演变为**意大利语、法语、西班牙语、葡萄牙语、罗马尼亚语**等罗曼语族语言。英语词汇也有大量来自拉丁语，学名、法律、医学术语至今沿用。","pts":["古罗马语言，印欧语系意大利语族","中世纪教会和学术通用语","派生罗曼语族，英语借词多"],"mem":"口诀“意法西葡罗”：意大利语、法语、西班牙语、葡萄牙语、罗马尼亚语，五个“罗曼语”都是拉丁语的后代，名字里的“罗”就是罗马。","mix":"英语属日耳曼语族，不是罗曼语族，但词汇大量借自拉丁语和法语；“死语言”指没有母语者，拉丁语仍用于教会和学术命名。","mcq":[{"q":"下列语言中，不属于由拉丁语演变而来的罗曼语族的是","o":["法语","西班牙语","德语","意大利语"],"a":2,"w":"德语属日耳曼语族；法、西、意都属罗曼语族。"}],"rel":[{"t":"罗马共和国与帝国","n":"拉丁语的使用者"},{"t":"欧洲中世纪","n":"通用学术语言时期"},{"t":"中世纪大学","n":"以拉丁语教学"}],"exam":[]},{"id":"a09-058","t":"唯物主义与唯心主义","cid":"09h","p":1,"kind":"概念","alias":["唯物论与唯心论","唯物论","唯心论"],"one":"哲学两大基本派别，依物质与意识何者第一性划分。","ans":"唯物主义与唯心主义是**哲学的两大基本派别**，划分标准是**思维和存在、意识和物质何者为第一性**这一哲学基本问题（恩格斯作了明确表述）。**认为物质第一性、意识是物质反映的是唯物主义**，历史上有朴素唯物主义（如泰勒斯、赫拉克利特）、机械唯物主义（如18世纪法国唯物论者、费尔巴哈）和辩证唯物主义三种形态；**认为意识第一性的是唯心主义**，分为**主观唯心主义**（如贝克莱“存在就是被感知”）和**客观唯心主义**（如柏拉图的理念、黑格尔的绝对精神）。","pts":["依物质与意识何者第一性划分","唯物：朴素、机械、辩证三形态","唯心：主观（贝克莱）与客观（柏拉图、黑格尔）"],"mem":"画面：“先有鸡还是先有蛋”，先有物质是唯物，先有精神是唯心。主观与客观的区分自编口诀“主贝客柏黑”：主观看贝克莱，客观看柏拉图、黑格尔。唯物三形态按时间“朴素→机械→辩证”。","mix":"此处“唯物”指物质第一性，与日常说的“重物质利益”无关；黑格尔有辩证法，但属客观唯心主义；二元论主张两个本原，介于两者之间。","mcq":[{"q":"下列哲学家中，属于主观唯心主义的是","o":["柏拉图","黑格尔","贝克莱","泰勒斯"],"a":2,"w":"贝克莱“存在就是被感知”，是主观唯心主义。"},{"q":"以水为万物本原的泰勒斯，其哲学属于","o":["朴素唯物主义","客观唯心主义","主观唯心主义","二元论"],"a":0,"w":"以具体物质为本原，属朴素唯物主义。"}],"rel":[{"t":"二元论","n":"介于两者之间"},{"t":"贝克莱","n":"主观唯心主义代表"},{"t":"黑格尔","n":"客观唯心主义集大成"},{"t":"费尔巴哈","n":"机械唯物主义代表"},{"t":"泰勒斯","n":"朴素唯物主义"}],"more":"恩格斯：全部哲学，特别是近代哲学的重大的基本问题，是思维和存在的关系问题。｜《路德维希·费尔巴哈和德国古典哲学的终结》","exam":[]},{"id":"a09-059","t":"形而上学","cid":"09h","p":1,"kind":"概念","alias":["第一哲学"],"one":"一指研究存在本身的“第一哲学”，二指与辩证法相对的孤立静止的方法。","ans":"形而上学有两层含义。**其一指研究存在本身和超感官本原的“第一哲学”**，亚里士多德的相关著作被后人编排在《物理学》之后（希腊文 meta ta physika），因而得名；中文译名取自《周易·系辞》“**形而上者谓之道，形而下者谓之器**”。**其二指与辩证法相对的思维方法**，即用孤立、静止、片面的观点看世界，这是黑格尔和马克思主义哲学所批评的用法。前者属哲学门类，后者属方法论，两种含义须分清。","pts":["第一哲学：研究存在本身与超感官本原","名称因编排在《物理学》之后；译名取自《周易》","与辩证法相对：孤立、静止、片面"],"mem":"拆字记：“形而上”在有形之上，管“道”；“形而下”是有形之物，管“器”。双义对照：古希腊那层是“学科”（物理学之后），近代批判的那层是“方法”（孤立静止，对立面是辩证法）。","mix":"同名异义是考点：亚里士多德《形而上学》指学科；日常或马列语境中“形而上学地看问题”指方法。“编排在《物理学》之后”的说法一般归于后世编者，非亚里士多德本人命名。","mcq":[{"q":"“形而上学”一词的中文译名取自","o":["《论语》","《周易·系辞》","《道德经》","《庄子》"],"a":1,"w":"“形而上者谓之道，形而下者谓之器”出自《周易·系辞上》。"},{"q":"亚里士多德《形而上学》名称的由来是","o":["它研究天上的神灵","它被编排在《物理学》之后","它由柏拉图命名","它写于《政治学》之前"],"a":1,"w":"meta ta physika 原意为“物理学之后”。"}],"rel":[{"t":"亚里士多德","n":"著《形而上学》"},{"t":"辩证法","n":"方法论上的对立面"},{"t":"《易传》（十翼）","n":"译名出处《系辞》"},{"t":"唯物主义与唯心主义","n":"哲学基本问题"}],"more":"名句：形而上者谓之道，形而下者谓之器。｜《周易·系辞上》","exam":[]},{"id":"a09-060","t":"奥古斯丁","cid":"09h","p":2,"kind":"人物","alias":["圣奥古斯丁","奥古斯丁《忏悔录》","《忏悔录》（奥古斯丁）","《上帝之城》"],"one":"北非希波主教，教父哲学代表，著《忏悔录》《上帝之城》。","ans":"奥古斯丁（354–430）是**4至5世纪北非希波的主教**，**教父哲学的主要代表**。他早年信奉摩尼教，后皈依基督教，运用柏拉图主义论证基督教教义。主要著作有自传体的**《忏悔录》**和在罗马城被攻陷后写成的**《上帝之城》**，后者提出“上帝之城”与“地上之城”两个世界的历史观，强调**原罪与恩典**。他奠定了中世纪基督教神学的基础，影响了后来的阿奎那和宗教改革。","pts":["354–430，北非希波主教，教父哲学","《忏悔录》《上帝之城》","柏拉图主义与基督教结合，原罪恩典"],"mem":"两本书一句话：《忏悔录》是“我”的皈依史，《上帝之城》是“人类”的历史观。柏拉图→奥古斯丁→阿奎那（亚里士多德）：教父哲学借柏拉图，经院哲学借亚里士多德。","mix":"卢梭另有《忏悔录》，注意区分；奥古斯丁与坎特伯雷首任大主教“圣奥古斯丁”是两人。","mcq":[{"q":"《忏悔录》《上帝之城》的作者是","o":["托马斯·阿奎那","奥古斯丁","但丁","卢梭"],"a":1,"w":"奥古斯丁是教父哲学代表；卢梭另有《忏悔录》，但《上帝之城》只属奥古斯丁。"}],"rel":[{"t":"托马斯·阿奎那","n":"后继的经院哲学集大成者"},{"t":"柏拉图","n":"借用其哲学"},{"t":"卢梭","n":"同名《忏悔录》作者"}],"exam":[]},{"id":"a09-061","t":"托马斯·阿奎那","cid":"09h","p":2,"kind":"人物","alias":["阿奎那","托马斯·阿奎纳","《神学大全》","神学大全"],"one":"13世纪意大利神学家，著《神学大全》，经院哲学集大成者。","ans":"托马斯·阿奎那（1225–1274）是**13世纪意大利的神学家和哲学家**，**经院哲学的集大成者**，属多明我会。他主要著作是**《神学大全》**。他吸收亚里士多德哲学，用理性论证基督教信仰，提出信仰与理性不相矛盾的观点，并提出**“五路证明”**论证上帝存在。他的体系后来成为**天主教会的官方哲学**，使基督教神学系统化，对西方思想影响深远。","pts":["13世纪意大利神学家，经院哲学集大成","《神学大全》","用亚里士多德哲学论证基督教信仰"],"mem":"配对：奥古斯丁＋柏拉图（教父哲学）；阿奎那＋亚里士多德（经院哲学）。书名“神学大全”记“全”：把神学、哲学装进一个体系。","mix":"阿奎那属经院哲学，奥古斯丁属教父哲学；“奥卡姆剃刀”的威廉是唯名论者，与阿奎那的唯实论立场不同。","mcq":[{"q":"用亚里士多德哲学论证基督教教义、著有《神学大全》的是","o":["奥古斯丁","阿奎那","奥卡姆","安瑟伦"],"a":1,"w":"阿奎那是经院哲学集大成者；奥古斯丁借重柏拉图主义。"}],"rel":[{"t":"经院哲学","n":"所属学派"},{"t":"奥古斯丁","n":"教父哲学前驱"},{"t":"亚里士多德","n":"借用其体系"}],"exam":[]},{"id":"a09-062","t":"奥卡姆剃刀","cid":"09h","p":2,"kind":"概念","alias":["奥卡姆的剃刀","简约原则","奥康剃刀","如无必要勿增实体"],"one":"“如无必要，勿增实体”，14世纪奥卡姆的威廉提出的简约原则。","ans":"奥卡姆剃刀是**14世纪英国经院哲学家奥卡姆的威廉**提出的原则，通行表述为**“如无必要，勿增实体”**。其含义是解释事物时不应假设多余的东西，在能说明问题的理论中应**选择最简单的一个**，因此被称为“剃刀”，剃去多余的假设。威廉属方济各会，立场是**唯名论**，认为共相只是名称。这一原则后来成为**科学方法中的简约原则**，在哲学、科学、统计和机器学习中被广泛引用。","pts":["14世纪奥卡姆的威廉提出","如无必要，勿增实体","简约原则；唯名论立场"],"mem":"画面：一把剃刀刮掉多余的胡须。“剃”掉的是多余的假设，不是真理本身。再记“奥卡姆”是英国地名，人物名叫威廉。","mix":"这句话不是奥卡姆原话的逐字引文，是后人概括；“剃刀”不是说简单的一定正确，只是在解释力相同时取简。","mcq":[{"q":"“如无必要，勿增实体”所表达的是","o":["苏格拉底方法","理念论","奥卡姆剃刀","三一律"],"a":2,"w":"奥卡姆的威廉提出，即简约原则。"}],"rel":[{"t":"经院哲学","n":"提出者所处传统"},{"t":"托马斯·阿奎那","n":"经院哲学前辈"},{"t":"弗朗西斯·培根","n":"同为英国科学方法先声"}],"exam":[]},{"id":"a09-063","t":"弗朗西斯·培根","cid":"09h","p":1,"kind":"人物","alias":["培根","弗兰西斯·培根","Francis Bacon"],"one":"英国经验论始祖，“知识就是力量”，著《新工具》倡归纳法。","ans":"弗朗西斯·培根（1561—1626）是**英国哲学家、散文家，英国经验论的始祖**，曾任大法官。他主张知识来自经验，提出“**知识就是力量**”，在《新工具》（1620）中针对亚里士多德的《工具论》倡导**归纳法**，并提出破除偏见的“四假象说”。他的《论说文集》（又译《培根随笔》）开创了英国随笔文学，《论读书》等篇流传甚广。马克思称他为“**英国唯物主义和整个现代实验科学的真正始祖**”。","pts":["英国经验论始祖，知识就是力量","《新工具》倡归纳法，对着亚里士多德《工具论》","《论说文集》开英国随笔之风"],"mem":"名字里藏逻辑：《新工具》对着亚里士多德的旧《工具论》，用归纳取代演绎。画面：培根像博物学家，先收集一大堆标本和事实再总结规律；笛卡尔则坐在炉子边靠推理。与笛卡尔对举：培根“归纳、经验”，笛卡尔“演绎、理性”。","mix":"弗朗西斯·培根（英国，17世纪初，经验论）不是13世纪的罗杰·培根，也不是20世纪同名的英国画家；“知识就是力量”通行说法出自其早年著作《沉思录》（1597）。","mcq":[{"q":"提出“知识就是力量”的哲学家是","o":["培根","笛卡尔","洛克","康德"],"a":0,"w":"培根是英国经验论始祖，《新工具》倡导归纳法。"},{"q":"培根在《新工具》中倡导的方法是","o":["演绎法","辩证法","归纳法","助产术"],"a":2,"w":"助产术属苏格拉底，辩证法属黑格尔，演绎法是唯理论的路径。"}],"rel":[{"t":"经验论与唯理论","n":"经验论始祖"},{"t":"笛卡尔","n":"唯理论对手"},{"t":"亚里士多德","n":"《新工具》针对其《工具论》"},{"t":"文艺复兴","n":"同时代背景"}],"more":"作品：《论说文集》（1597起，通行本58篇）｜《学术的进步》｜《新工具》（1620）｜《新大西岛》\n名句：读书使人充实，讨论使人机敏，写作使人精确。｜《论读书》","exam":[]},{"id":"a09-064","t":"笛卡尔","cid":"09h","p":1,"kind":"人物","alias":["勒内·笛卡尔","近代哲学之父"],"one":"法国唯理论奠基人，“我思故我在”，心物二元论，创解析几何。","ans":"笛卡尔（1596—1650）是**法国哲学家、数学家，欧洲近代唯理论的奠基人**，被称为“**近代哲学之父**”。他以**怀疑一切**为方法，提出“**我思故我在**”，认为理性是知识的可靠来源，并主张天赋观念；在本体论上提出**心物二元论**。代表作有《谈谈方法》（1637）和《第一哲学沉思集》（1641）。他还**创立解析几何**，建立了笛卡尔坐标系。他的理性主义影响了斯宾诺莎、莱布尼茨，并与英国经验论构成近代认识论的两大对立。","pts":["法国唯理论奠基人，近代哲学之父","我思故我在，心物二元论","创立解析几何；《谈谈方法》《第一哲学沉思集》"],"mem":"逻辑线：怀疑一切→唯有“正在怀疑的我”无法怀疑→我思故我在→以此为起点推演出其余知识。口诀“疑、思、在”。数学上他把代数引入几何，所以“笛卡尔坐标”和“解析几何”是一件事。","mix":"笛卡尔属唯理论（法国），培根、洛克属经验论（英国）；“我思故我在”不等于萨特的“存在先于本质”；二元论是他的本体论立场，唯理论是他的认识论立场。","mcq":[{"q":"提出“我思故我在”的哲学家是","o":["斯宾诺莎","休谟","笛卡尔","培根"],"a":2,"w":"出自笛卡尔，见《谈谈方法》。"},{"q":"下列学科中，由笛卡尔创立的是","o":["解析几何","微积分","射影几何","概率论"],"a":0,"w":"笛卡尔在《几何学》中建立了坐标几何。"}],"rel":[{"t":"二元论","n":"其本体论主张"},{"t":"经验论与唯理论","n":"唯理论代表"},{"t":"弗朗西斯·培根","n":"经验论对手"},{"t":"斯宾诺莎与莱布尼茨","n":"唯理论后继者"}],"more":"作品：《谈谈方法》（1637，附《几何学》）｜《第一哲学沉思集》（1641）｜《哲学原理》（1644）\n名句：我思故我在。","exam":[]},{"id":"a09-065","t":"斯宾诺莎与莱布尼茨","cid":"09h","p":3,"kind":"人物","exam":[],"alias":[],"one":"斯宾诺莎《伦理学》，泛神论；莱布尼茨单子论，与牛顿各自发明微积分，研究过《易","ans":"斯宾诺莎《伦理学》，泛神论；莱布尼茨单子论，与牛顿各自发明微积分，研究过《易经》与二进制。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-066","t":"洛克","cid":"09h","p":2,"kind":"人物","alias":["约翰·洛克","John Locke","白板说","《政府论》","《人类理解论》"],"one":"英国经验论哲学家，白板说，《政府论》提出天赋人权与分权。","ans":"约翰·洛克（1632–1704）是**英国哲学家**，**经验论**的代表，也是**自由主义政治思想之父**。在《人类理解论》中他提出**“白板说”**，认为人心如一块白板，一切观念来自经验。在《政府论》中他提出**天赋人权**（生命、自由、财产）和政府权力来自人民同意的主张，并提出**分权**思想。这些思想影响了**美国《独立宣言》**和法国启蒙思想家，也为教育学留下《教育漫话》。","pts":["英国经验论，白板说","《政府论》：天赋人权、分权","影响美国《独立宣言》"],"mem":"一块白板，三项权利：“白板”管认识论，“生命、自由、财产”管政治。《独立宣言》把“财产”换成了“追求幸福”，可以顺带记住。","mix":"经验论三人组：洛克、贝克莱、休谟；唯理论代表是笛卡尔等。霍布斯主张君主绝对权力，洛克主张有限政府，二人都讲社会契约，结论不同。","mcq":[{"q":"提出“白板说”的哲学家是","o":["笛卡尔","洛克","康德","莱布尼茨"],"a":1,"w":"洛克认为心灵如白板，一切观念来自经验。"}],"rel":[{"t":"经验论与唯理论","n":"经验论代表"},{"t":"社会契约论","n":"政治思想关联"},{"t":"《独立宣言》","n":"思想影响"},{"t":"洛克《教育漫话》","n":"教育著作"}],"exam":[]},{"id":"a09-067","t":"霍布斯《利维坦》","cid":"09h","p":2,"kind":"作品","alias":["利维坦","霍布斯","托马斯·霍布斯"],"one":"霍布斯1651年政治哲学著作，自然状态是一切人对一切人的战争。","ans":"《利维坦》是**英国哲学家托马斯·霍布斯1651年的政治哲学著作**，书名取自《圣经》中的海兽，比喻强大的国家。霍布斯认为人在自然状态下处于**“一切人反对一切人的战争”**，生活孤独、贫困、残忍而短寿，为求自保，人们订立**社会契约**，把权力交给一个主权者，从而建立国家。他主张主权者拥有**强大乃至绝对的权力**，是近代**社会契约论**的奠基之作，也是西方国家理论的经典。","pts":["霍布斯1651年著","自然状态是一切人对一切人的战争","订立契约建国，主张强大主权"],"mem":"一句话链条：战争状态→怕死→订立契约→国家（利维坦这头巨兽）。口诀：霍布斯悲观（人对人是狼），洛克乐观（天赋人权）。","mix":"洛克与卢梭同讲契约，但霍布斯得出的是强权国家，洛克得出的是有限政府，卢梭强调人民主权与公意。","mcq":[{"q":"“自然状态是一切人反对一切人的战争”出自","o":["洛克《政府论》","卢梭《社会契约论》","霍布斯《利维坦》","孟德斯鸠《论法的精神》"],"a":2,"w":"霍布斯在《利维坦》中提出。"}],"rel":[{"t":"社会契约论","n":"所属理论"},{"t":"洛克","n":"同讲契约结论不同"},{"t":"卢梭","n":"契约论另一代表"},{"t":"《圣经》","n":"书名取自圣经海兽"}],"exam":[]},{"id":"a09-068","t":"贝克莱","cid":"09h","p":3,"kind":"人物","exam":[],"alias":[],"one":"“存在就是被感知”。","ans":"“存在就是被感知”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-069","t":"休谟","cid":"09h","p":2,"kind":"人物","alias":["大卫·休谟","David Hume","《人性论》"],"one":"苏格兰经验论哲学家，怀疑因果必然性，惊醒康德的独断论迷梦。","ans":"大卫·休谟（1711–1776）是**18世纪苏格兰哲学家**，**英国经验论**的集大成者，代表作有**《人性论》**和《人类理解研究》。他把经验论推到彻底的**怀疑论**：认为人只能认识感觉印象，所谓**因果关系**不过是经验中反复出现的习惯性联想，并无逻辑上的必然性。康德自称是休谟**把他从“独断论的迷梦”中唤醒**，由此写出《纯粹理性批判》。他对近代认识论、道德哲学和经济学影响很大。","pts":["苏格兰经验论哲学家，《人性论》","怀疑因果必然性，彻底怀疑论","惊醒康德的独断论迷梦"],"mem":"经验论接力：洛克（白板）→贝克莱（存在即被感知）→休谟（连因果也怀疑）。再记一个因果：休谟怀疑→康德被惊醒→调和经验论和唯理论。","mix":"休谟是苏格兰人，常被误认为英格兰；他与亚当·斯密是好友。贝克莱说“存在就是被感知”，休谟说因果是习惯。","mcq":[{"q":"康德说被谁从“独断论的迷梦”中唤醒","o":["洛克","贝克莱","笛卡尔","休谟"],"a":3,"w":"康德称休谟的怀疑论使他从独断论迷梦中惊醒。"}],"rel":[{"t":"经验论与唯理论","n":"经验论代表"},{"t":"康德","n":"受其启发"},{"t":"贝克莱","n":"经验论前辈"}],"exam":[]},{"id":"a09-070","t":"德国古典哲学","cid":"09h","p":1,"kind":"流派","alias":["德国古典唯心主义"],"one":"18世纪末至19世纪中叶的德国哲学，康德至费尔巴哈，马克思主义来源之一。","ans":"德国古典哲学是**18世纪末至19世纪中叶德国的一批哲学思潮**，代表人物依次为**康德、费希特、谢林、黑格尔和费尔巴哈**。康德开创批判哲学，**黑格尔建立了庞大的客观唯心主义体系并系统阐述辩证法**，费尔巴哈则恢复了唯物主义。这一学派继承启蒙理性，把能动性与辩证思维引入哲学。**黑格尔的辩证法与费尔巴哈的唯物主义是马克思主义哲学的直接理论来源**，它与英国古典政治经济学、法国空想社会主义并称马克思主义的三个来源。","pts":["康德、费希特、谢林、黑格尔、费尔巴哈","康德开创，黑格尔集大成，费尔巴哈转向唯物","黑格尔辩证法与费尔巴哈唯物主义是马克思主义来源"],"members":[["康德","三大批判；人为自然立法"],["费希特","强调“自我”的能动性，《全部知识学的基础》"],["谢林","自然哲学、同一哲学"],["黑格尔","绝对精神，辩证法集大成"],["费尔巴哈","恢复唯物主义，《基督教的本质》"]],"mem":"逻辑线：康德划界（批判）→费希特讲“自我”（主观）→谢林讲“自然”与同一（客观）→黑格尔合成“绝对精神”（体系）→费尔巴哈把它倒回人和自然（唯物）。首字串自编“康费谢黑费”。","mix":"德国古典哲学不同于德国古典文学（歌德、席勒）；是否包括费尔巴哈有两种说法，通行（含恩格斯《费尔巴哈论》的叙述）算在内，也有只算到黑格尔的；尼采、叔本华不属于。","mcq":[{"q":"下列哲学家中，不属于德国古典哲学代表人物的是","o":["康德","黑格尔","尼采","费尔巴哈"],"a":2,"w":"尼采属19世纪非理性主义思潮。"},{"q":"马克思主义哲学的直接理论来源是","o":["洛克的经验论与休谟的怀疑论","笛卡尔的二元论与斯宾诺莎的一元论","尼采的权力意志与叔本华的意志论","黑格尔的辩证法与费尔巴哈的唯物主义"],"a":3,"w":"马克思主义批判继承了黑格尔辩证法的合理内核与费尔巴哈唯物主义的基本内核。"}],"rel":[{"t":"康德","n":"开创者"},{"t":"黑格尔","n":"集大成者"},{"t":"费尔巴哈","n":"唯物主义代表"},{"t":"辩证法","n":"黑格尔系统阐述"},{"t":"经验论与唯理论","n":"康德对其调和"}],"more":"马克思主义三个来源：德国古典哲学、英国古典政治经济学、法国空想社会主义。｜列宁《马克思主义的三个来源和三个组成部分》","exam":[]},{"id":"a09-071","t":"康德","cid":"09h","p":1,"kind":"人物","alias":["伊曼努尔·康德","批判哲学"],"one":"德国古典哲学开创者，三大批判，“人为自然立法”。","ans":"康德（1724—1804）是**德国哲学家，德国古典哲学的开创者**，一生居于柯尼斯堡。他的“**三大批判**”是《纯粹理性批判》《实践理性批判》《判断力批判》，其中《纯粹理性批判》**调和经验论与唯理论**，提出“**人为自然立法**”，被称为认识论上的**“哥白尼式革命”**。他区分现象与物自体，墓志铭是“头上的星空和心中的道德律”。他还提出**星云假说**，并在《答复这个问题：什么是启蒙》中号召“要有勇气运用你自己的理智”。","pts":["德国古典哲学开创者，三大批判","人为自然立法，认识论上的哥白尼式革命","星云假说；启蒙即运用自己的理智"],"mem":"三大批判对应“真善美”自编记法：纯粹理性管“真”（我能知道什么），实践理性管“善”（我应当做什么），判断力管“美”（审美与目的）。画面：哥白尼让地球绕着太阳转，康德让对象绕着认识的主体转。","mix":"康德不属经验论也不属唯理论，他是调和者；辩证法的集大成者是黑格尔而非康德；《精神现象学》是黑格尔的书。","mcq":[{"q":"下列著作中，不属于康德“三大批判”的是","o":["《精神现象学》","《纯粹理性批判》","《实践理性批判》","《判断力批判》"],"a":0,"w":"《精神现象学》是黑格尔的作品。"},{"q":"“人为自然立法”是下列哪位哲学家的主张","o":["休谟","康德","黑格尔","洛克"],"a":1,"w":"康德认为知性为自然界立法，被称为哥白尼式革命。"}],"rel":[{"t":"德国古典哲学","n":"开创者"},{"t":"经验论与唯理论","n":"调和两派"},{"t":"黑格尔","n":"后继者"},{"t":"启蒙运动","n":"《什么是启蒙》"},{"t":"哥白尼日心说","n":"“哥白尼式革命”的类比"}],"more":"作品：《纯粹理性批判》（1781）｜《实践理性批判》（1788）｜《判断力批判》（1790）｜《答复这个问题：什么是启蒙》（1784）\n名句：有两样东西，我对它们的思考越是深沉和持久，它们在我心灵中唤起的惊奇和敬畏就会日新月异，不断增长，这就是我头上的星空和我心中的道德律。｜《实践理性批判》","exam":[]},{"id":"a09-072","t":"黑格尔","cid":"09h","p":1,"kind":"人物","alias":["黑格爾","格奥尔格·威廉·弗里德里希·黑格尔"],"one":"德国古典哲学集大成者，客观唯心主义，绝对精神，系统阐述辩证法。","ans":"黑格尔（1770—1831）是**德国哲学家，德国古典哲学的集大成者**，**客观唯心主义**代表，曾任柏林大学教授。他认为世界的本原是**“绝对精神”**，其自我发展经历逻辑、自然、精神三个阶段；他最大的贡献是**系统阐述了辩证法**，认为事物在矛盾运动中发展，提出“凡是合乎理性的东西都是现实的，凡是现实的东西都是合乎理性的”。代表作有《精神现象学》《逻辑学》《法哲学原理》《美学》。马克思主义吸取其辩证法的**“合理内核”**，摒弃其唯心体系。","pts":["客观唯心主义，绝对精神","系统阐述辩证法，德国古典哲学集大成","《精神现象学》《逻辑学》《美学》；马克思吸取合理内核"],"mem":"画面：绝对精神走三步，先在“逻辑”里自己思考，再外化成“自然”，最后回到“精神”（艺术、宗教、哲学），像螺旋上升。“正题、反题、合题”是后人概括的通行三段式。马克思把他“倒立”的辩证法重新“倒过来”，就是唯物辩证法。","mix":"黑格尔有辩证法，但世界观是唯心的；费尔巴哈是唯物的，但方法偏形而上学；“正反合”并非黑格尔本人的常用表述，属通行概括。《美学》是其身后由学生整理的讲演录。","mcq":[{"q":"黑格尔哲学的核心概念是","o":["物自体","绝对精神","权力意志","理念论"],"a":1,"w":"理念论属柏拉图，物自体属康德，权力意志属尼采。"},{"q":"马克思主义哲学从黑格尔那里批判继承的“合理内核”是","o":["辩证法","绝对精神","客观唯心主义体系","物自体"],"a":0,"w":"马克思主义吸取辩证法，摒弃唯心体系。"}],"rel":[{"t":"德国古典哲学","n":"集大成者"},{"t":"康德","n":"前驱"},{"t":"费尔巴哈","n":"批判黑格尔"},{"t":"辩证法","n":"系统阐述者"},{"t":"唯物主义与唯心主义","n":"客观唯心主义代表"}],"more":"作品：《精神现象学》（1807）｜《逻辑学》（1812—1816）｜《法哲学原理》（1821）｜《美学》\n名句：凡是合乎理性的东西都是现实的；凡是现实的东西都是合乎理性的。｜《法哲学原理》序言\n美是理念的感性显现。｜《美学》","exam":[]},{"id":"a09-073","t":"费尔巴哈","cid":"09h","p":3,"kind":"人物","exam":[],"alias":[],"one":"人本主义唯物主义，《基督教的本质》；马克思写有《关于费尔巴哈的提纲》。","ans":"人本主义唯物主义，《基督教的本质》；马克思写有《关于费尔巴哈的提纲》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-074","t":"叔本华","cid":"09h","p":2,"kind":"人物","alias":["亚瑟·叔本华","Schopenhauer","《作为意志和表象的世界》","唯意志论"],"one":"德国哲学家，唯意志论和悲观主义，影响尼采与王国维。","ans":"叔本华（1788–1860）是**德国哲学家**，**唯意志论**的代表，开启19世纪**非理性主义**潮流。代表作是**《作为意志和表象的世界》**（1819），认为世界的本质是盲目的生存意志，人的欲望永无满足，因此人生本质是痛苦，形成**悲观主义**。他认为艺术和禁欲可以使人暂时摆脱意志的支配。他影响了尼采和弗洛伊德，也影响了中国学者**王国维**，后者用叔本华的悲剧论写成《红楼梦评论》。","pts":["德国唯意志论、悲观主义","《作为意志和表象的世界》","影响尼采，也影响王国维《红楼梦评论》"],"mem":"联想：欲望永远填不满，于是痛苦；唯一出路是艺术或放下欲望。“意志”不是“意志坚强”，是盲目的生命冲动。中国联系：王国维的《红楼梦评论》（1904）用他解读贾宝玉出家。","mix":"尼采后来批评叔本华的悲观，提出“权力意志”；黑格尔重理性，叔本华反理性，二人同时代而对立。","mcq":[{"q":"王国维《红楼梦评论》所借用的西方哲学家主要是","o":["康德","叔本华","黑格尔","尼采"],"a":1,"w":"王国维以叔本华的悲观主义和悲剧论评《红楼梦》。"}],"rel":[{"t":"尼采","n":"受其影响又批评之"},{"t":"王国维","n":"中国接受者"},{"t":"黑格尔","n":"同时代对立的理性主义者"}],"exam":[]},{"id":"a09-075","t":"尼采","cid":"09h","p":1,"kind":"人物","alias":["尼采","弗里德里希·尼采","Nietzsche"],"one":"德国哲学家，“上帝死了”，权力意志与超人，提出日神与酒神精神。","ans":"尼采（1844—1900）是**德国哲学家，非理性主义（唯意志论）的代表**，曾任巴塞尔大学古典语言学教授。他在《悲剧的诞生》（1872）中提出**日神精神与酒神精神**，认为希腊悲剧源于二者的结合；以“**上帝死了**”宣告传统宗教和道德价值的崩塌，主张“**重估一切价值**”，提出**权力意志**与**超人**学说，代表作有《查拉图斯特拉如是说》。他的思想深刻影响了存在主义、精神分析和现代主义文学，鲁迅等中国作家也受其影响。","pts":["德国非理性主义哲学家，上帝死了","《悲剧的诞生》：日神精神与酒神精神","权力意志、超人、重估一切价值"],"mem":"逻辑线：上帝死了（旧价值失效）→重估一切价值→人应成为超人（权力意志驱动）。画面：两位神合演悲剧，日神阿波罗管梦、造型、秩序，酒神狄俄尼索斯管醉、音乐、狂欢，缺一不可。","mix":"叔本华讲悲观的“生存意志”，尼采讲肯定生命的“权力意志”；克尔凯郭尔是宗教存在主义者；“上帝死了”最早见于《快乐的科学》，《查拉图斯特拉如是说》使其广为人知。","mcq":[{"q":"提出日神精神与酒神精神的著作是","o":["《悲剧的诞生》","《诗学》","《精神现象学》","《纯粹理性批判》"],"a":0,"w":"尼采《悲剧的诞生》用日神与酒神解释希腊悲剧。"},{"q":"宣告“上帝死了”的哲学家是","o":["叔本华","黑格尔","克尔凯郭尔","尼采"],"a":3,"w":"“上帝死了”是尼采的名言。"}],"rel":[{"t":"叔本华","n":"意志论前驱"},{"t":"存在主义","n":"受其影响"},{"t":"狄俄尼索斯（酒神）","n":"酒神精神"},{"t":"阿波罗（日神）","n":"日神精神"},{"t":"鲁迅","n":"中国受其影响的作家"}],"more":"作品：《悲剧的诞生》（1872）｜《查拉图斯特拉如是说》（1883—1885）｜《善恶的彼岸》｜《论道德的谱系》\n名句：上帝死了。｜《快乐的科学》","exam":[]},{"id":"a09-076","t":"克尔凯郭尔","cid":"09h","p":3,"kind":"人物","exam":[],"alias":[],"one":"丹麦哲学家，强调个体的选择与焦虑，《非此即彼》。","ans":"丹麦哲学家，强调个体的选择与焦虑，《非此即彼》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-077","t":"海德格尔","cid":"09h","p":2,"kind":"人物","alias":["马丁·海德格尔","Heidegger","《存在与时间》","此在","向死而生"],"one":"德国哲学家，《存在与时间》，“此在”“向死而生”。","ans":"马丁·海德格尔（1889–1976）是**20世纪德国哲学家**，**存在主义和现象学**的重要人物，师从胡塞尔。代表作**《存在与时间》**（1927）追问“存在”的意义，提出以**“此在”**（人的存在）为入口，强调人是被抛入世界、**“向死而生”**的有限存在。后期他转向对语言和诗的思考，借荷尔德林的诗阐发**“人诗意地栖居”**，认为语言是“存在的家”。他深刻影响了萨特、福柯、德里达和现代阐释学。","pts":["德国，《存在与时间》，此在","向死而生","人诗意地栖居，语言是存在的家"],"mem":"三个关键词顺序：存在→此在→向死而生。“诗意地栖居”出自他对荷尔德林诗句的阐发，诗人是荷尔德林，阐发者是海德格尔。","mix":"“存在先于本质”是萨特的话，不是海德格尔的；海德格尔本人不愿被称为存在主义者。","mcq":[{"q":"《存在与时间》的作者是","o":["胡塞尔","萨特","海德格尔","尼采"],"a":2,"w":"海德格尔1927年著；胡塞尔是现象学创始人，萨特著《存在与虚无》。"}],"rel":[{"t":"存在主义","n":"所属思潮"},{"t":"胡塞尔与现象学","n":"老师与现象学"},{"t":"萨特","n":"同属存在主义"}],"exam":[]},{"id":"a09-078","t":"胡塞尔与现象学","cid":"09h","p":3,"kind":"流派","exam":[],"alias":[],"one":"“回到事情本身”，悬置判断；影响海德格尔、萨特。","ans":"“回到事情本身”，悬置判断；影响海德格尔、萨特。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-079","t":"实用主义","cid":"09h","p":2,"kind":"流派","alias":["实验主义","实用哲学","皮尔士","詹姆士"],"one":"19世纪末美国哲学，以实际效果检验真理，杜威、胡适是代表与传人。","ans":"实用主义是**19世纪末兴起于美国的哲学流派**，主要代表有**皮尔士、詹姆士和杜威**。它主张观念的意义和真理由**实际效果**来检验，有用即真，把知识看作人解决问题的工具。杜威将其应用于教育，提出“教育即生活”“学校即社会”，并于**1919年来华讲学**两年。他的学生**胡适**在中国传播实用主义，提出**“大胆假设，小心求证”**的治学方法。实用主义是美国最有影响的本土哲学。","pts":["19世纪末美国，皮尔士、詹姆士、杜威","以实际效果检验真理","杜威1919年来华，胡适传人"],"mem":"“皮詹杜”三人顺序记：皮尔士创始，詹姆士推广，杜威集大成。中国线：杜威→胡适→“大胆假设，小心求证”。","mix":"实用主义不是“功利主义”：前者讲真理以效果检验，后者讲行为以幸福最大化，二者名字相近、内容不同；胡适的“实验主义”就是实用主义。","mcq":[{"q":"与实用主义代表杜威有师承关系的中国学者是","o":["陈独秀","鲁迅","胡适","梁启超"],"a":2,"w":"胡适留美时师从杜威，回国后传播实用主义。"}],"rel":[{"t":"杜威","n":"集大成者"},{"t":"胡适","n":"中国传人"},{"t":"功利主义","n":"名称相近易混"}],"exam":[]},{"id":"a09-080","t":"功利主义","cid":"09h","p":2,"kind":"流派","alias":["功利论","效益主义","边沁","约翰·密尔","密尔","《论自由》","《群己权界论》"],"one":"边沁、密尔提出“最大多数人的最大幸福”，严复译密尔《论自由》。","ans":"功利主义是**19世纪英国的伦理学流派**，创始人是**杰里米·边沁**，约翰·密尔（又译穆勒）使之完善。其基本原则是**“最大多数人的最大幸福”**，以行为带来的快乐和痛苦的总和判断对错。边沁主张幸福可以计算，密尔则区分快乐的质与量，强调精神快乐高于肉体快乐。密尔的**《论自由》**是自由主义经典，**严复**将它译为**《群己权界论》**（1903），把功利主义与自由思想引入中国。","pts":["边沁、密尔，英国伦理学","最大多数人的最大幸福","严复译密尔《论自由》为《群己权界论》"],"mem":"一句话：行为对不对，看能不能带来“最大多数人的最大幸福”。翻译链：Mill《On Liberty》→严复《群己权界论》（“群”是社会，“己”是个人，“权界”是界限）。","mix":"不要与实用主义混：功利主义是伦理学，实用主义是认识论；“功利”在日常中带贬义，作为学说只是指以后果判断行为。","mcq":[{"q":"严复译为《群己权界论》的是密尔的","o":["《功利主义》","《论自由》","《政府论》","《国富论》"],"a":1,"w":"《论自由》，译于1903年。"}],"rel":[{"t":"严复","n":"译介者"},{"t":"实用主义","n":"名称相近易混"},{"t":"《天演论》","n":"严复另一译著"}],"more":"边沁（1748–1832）《道德与立法原理导论》；密尔（1806–1873）《功利主义》《论自由》。","exam":[]},{"id":"a09-081","t":"维特根斯坦与分析哲学","cid":"09h","p":2,"kind":"流派","alias":["维特根斯坦","分析哲学","语言转向","语言游戏","《逻辑哲学论》","《哲学研究》"],"one":"20世纪语言转向的代表，前期《逻辑哲学论》，后期“语言游戏”。","ans":"维特根斯坦（1889–1951）是**奥地利出生的英国哲学家**，**分析哲学**的核心人物，推动了哲学的**“语言转向”**，即把哲学问题归结为语言的使用与分析。前期代表作**《逻辑哲学论》**认为语言是世界的图像，提出“**凡不可说的，应当沉默**”。后期著作**《哲学研究》**批评自己早期的观点，提出**“语言游戏”**，认为词语的意义在于它在生活中的使用。分析哲学在英美长期占主导，罗素、弗雷格也是其源头人物。","pts":["奥地利出生，分析哲学、语言转向","前期《逻辑哲学论》：不可说者应沉默","后期《哲学研究》：语言游戏"],"mem":"前后期对比：前期“语言＝世界的图画”，后期“语言＝游戏，意义在用法”。名句记前期：凡不可说的，应当沉默。书名记“论”在前、“研究”在后。","mix":"分析哲学（英美）与大陆哲学（现象学、存在主义）是20世纪两大传统；维特根斯坦两个时期立场相反，常被当作“两个维特根斯坦”。","mcq":[{"q":"提出“语言游戏”概念的是维特根斯坦的","o":["《逻辑哲学论》","《存在与时间》","《哲学研究》","《纯粹理性批判》"],"a":2,"w":"后期《哲学研究》提出语言游戏；《逻辑哲学论》是前期著作。"}],"rel":[{"t":"海德格尔","n":"大陆哲学代表对照"},{"t":"结构主义","n":"同样关注语言"},{"t":"索绪尔","n":"语言学中的语言转向"}],"exam":[]},{"id":"a09-082","t":"弗洛伊德与精神分析","cid":"09h","p":1,"kind":"人物","alias":["弗洛伊德","精神分析","精神分析学派","本我自我超我","Freud"],"one":"奥地利精神分析创始人，潜意识、本我自我超我、俄狄浦斯情结。","ans":"弗洛伊德（1856—1939）是**奥地利精神病学家，精神分析学派创始人**。他在《梦的解析》（1900）中提出**潜意识**理论，认为梦是被压抑欲望的伪装满足；后来提出人格由**本我、自我、超我**构成，并提出**俄狄浦斯情结**。其学说强调**性本能与潜意识对人的行为的支配**。精神分析深刻影响了心理学、文学批评和艺术，**意识流文学与超现实主义**都以潜意识为重要源泉，荣格、阿德勒等人则由此分化出不同学派。","pts":["奥地利精神分析创始人，《梦的解析》","潜意识；本我、自我、超我；俄狄浦斯情结","影响意识流文学与超现实主义"],"mem":"冰山比喻：水面上一小块是意识，水下一大块是潜意识。三我自编记法：本我要爽（快乐原则），自我要稳（现实原则），超我要对（道德原则）。俄狄浦斯情结直接取名自索福克勒斯的悲剧《俄狄浦斯王》。","mix":"弗洛伊德讲个人潜意识，荣格讲集体无意识；《梦的解析》实际出版于1899年底，扉页署1900年，通行写1900年。","mcq":[{"q":"弗洛伊德提出的人格结构是","o":["日神、酒神、超人","真、善、美","本我、自我、超我","感性、知性、理性"],"a":2,"w":"本我、自我、超我是精神分析的人格三分。"},{"q":"《梦的解析》的作者是","o":["荣格","弗洛伊德","阿德勒","尼采"],"a":1,"w":"《梦的解析》是弗洛伊德的代表作。"}],"rel":[{"t":"荣格与集体无意识","n":"弟子与分歧"},{"t":"意识流","n":"文学受其影响"},{"t":"超现实主义","n":"艺术受其影响"},{"t":"《俄狄浦斯王》","n":"情结的名称来源"}],"more":"1856年5月6日生，2026年是诞辰170周年。\n作品：《梦的解析》（1899年底出版，署1900）｜《精神分析引论》｜《自我与本我》（1923）","exam":[]},{"id":"a09-083","t":"荣格与集体无意识","cid":"09h","p":3,"kind":"人物","exam":[],"alias":[],"one":"瑞士，分析心理学，集体无意识与原型，内倾与外倾。","ans":"瑞士，分析心理学，集体无意识与原型，内倾与外倾。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-084","t":"结构主义","cid":"09h","p":2,"kind":"流派","alias":["结构主义语言学","列维-斯特劳斯","罗兰·巴特","能指所指"],"one":"源于索绪尔语言学，研究深层结构，用于人类学和文学批评。","ans":"结构主义是**20世纪中期流行于法国的思潮**，源于**索绪尔的结构语言学**。索绪尔提出语言是符号系统，符号由**能指与所指**构成，并区分**共时与历时**。结构主义认为意义来自要素之间的关系，应寻找现象背后的**深层结构**。**列维-斯特劳斯**用它研究亲属关系和神话，**罗兰·巴特**用它分析文学与大众文化。它影响了人类学、文学批评和叙事学，后来被**后结构主义和解构主义**所超越。","pts":["源于索绪尔，能指与所指、共时与历时","寻找深层结构，意义来自关系","列维-斯特劳斯、罗兰·巴特；后被解构"],"mem":"关键词“关系大于实体”：一个词的意义不在词本身，在它与别的词的差别（猫≠帽）。人物链：索绪尔（语言）→列维-斯特劳斯（人类学）→巴特（文学）。","mix":"结构主义（找稳定结构）与后结构主义/解构主义（质疑结构的稳定，德里达）相继出现；容易与“结构功能主义”社会学混淆。","mcq":[{"q":"结构主义思潮的语言学源头是","o":["乔姆斯基","索绪尔","萨丕尔","维特根斯坦"],"a":1,"w":"索绪尔的结构语言学是结构主义的源头。"}],"rel":[{"t":"索绪尔","n":"思想源头"},{"t":"德里达与解构主义","n":"后继的批判"},{"t":"后现代主义","n":"同时代的思潮"}],"exam":[]},{"id":"a09-085","t":"后现代主义","cid":"09h","p":2,"kind":"流派","alias":["后现代","后现代思潮","利奥塔","元叙事","宏大叙事"],"one":"20世纪60年代后兴起，质疑宏大叙事、中心与确定性。","ans":"后现代主义是**20世纪60年代后兴起的文化与思想思潮**，在哲学、文学、建筑、艺术中都有表现。其核心是**质疑现代性确立的宏大叙事、理性中心和确定性**。法国哲学家**利奥塔**在《后现代状态》中把后现代定义为**“对元叙事的怀疑”**；**德里达**提出解构主义，消解文本的固定意义；**福柯**揭示知识与权力的关系。文学上有**黑色幽默**、元小说等，表现出荒诞、拼贴和反讽的特点。","pts":["20世纪60年代后兴起，质疑宏大叙事","利奥塔：对元叙事的怀疑","德里达解构、福柯；黑色幽默"],"mem":"一个“反”字串起来：反中心（德里达）、反宏大叙事（利奥塔）、反权威话语（福柯）。文学代表记“黑色幽默”，用荒诞写严肃。","mix":"后现代主义不是现代主义之后的“进步”，而是对现代性的反思；与后结构主义相互交叠，德里达和福柯常被两边引用。","mcq":[{"q":"“对元叙事的怀疑”是谁对后现代的定义","o":["利奥塔","萨特","哈贝马斯","弗洛伊德"],"a":0,"w":"利奥塔在《后现代状态》（1979）中提出。"}],"rel":[{"t":"德里达与解构主义","n":"代表思想"},{"t":"福柯","n":"代表人物"},{"t":"黑色幽默","n":"文学表现"},{"t":"结构主义","n":"前一思潮"}],"exam":[]},{"id":"a09-086","t":"福柯","cid":"09h","p":2,"kind":"人物","alias":["米歇尔·福柯","Foucault","知识考古学","规训与惩罚","疯癫与文明"],"one":"法国思想家，权力与话语，著《疯癫与文明》《规训与惩罚》；2026年诞辰100周年。","ans":"米歇尔·福柯（1926–1984）是**法国哲学家和思想史家**，**后现代思潮的代表**之一，1926年10月15日出生，**2026年是他诞辰100周年**。他用**“知识考古学”**研究知识的形成，用“谱系学”研究权力，提出**权力与话语**相互生成，知识受权力支配。代表作有**《疯癫与文明》《词与物》《规训与惩罚》**和《性经验史》。他以边沁的“全景监狱”为例说明现代社会的规训机制，对文学理论、社会学和历史学影响很大。","pts":["法国，1926–1984，2026年诞辰100周年","知识考古学，权力与话语","《疯癫与文明》《词与物》《规训与惩罚》"],"mem":"三书按主题记：疯癫（《疯癫与文明》）、知识（《词与物》）、监狱（《规训与惩罚》）。一个词：权力无处不在，渗入知识和身体。年份：1926生，2026满百年。","mix":"福柯常被划为后结构主义，他本人拒绝这个标签；全景监狱的设计者是边沁，福柯只是借用来分析。","mcq":[{"q":"《规训与惩罚》的作者是","o":["德里达","利奥塔","萨特","福柯"],"a":3,"w":"福柯著，以“全景监狱”分析现代规训权力。"}],"rel":[{"t":"后现代主义","n":"所属思潮"},{"t":"德里达与解构主义","n":"同时代法国思想家"},{"t":"功利主义","n":"边沁的全景监狱出处"}],"exam":[]},{"id":"a09-087","t":"德里达与解构主义","cid":"09h","p":3,"kind":"流派","exam":[],"alias":[],"one":"法国，消解二元对立和逻各斯中心主义，“文本之外别无他物”。","ans":"法国，消解二元对立和逻各斯中心主义，“文本之外别无他物”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-088","t":"法兰克福学派","cid":"09h","p":3,"kind":"流派","exam":[],"alias":[],"one":"德国社会批判理论；阿多诺、霍克海默“文化工业”，马尔库塞《单向度的人》，哈贝","ans":"德国社会批判理论；阿多诺、霍克海默“文化工业”，马尔库塞《单向度的人》，哈贝马斯“交往行为”“公共领域”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-089","t":"帕斯卡","cid":"09h","p":3,"kind":"人物","exam":[],"alias":[],"one":"17世纪法国，《思想录》“人是一根能思想的苇草”；帕斯卡定律，制造机械计算器","ans":"17世纪法国，《思想录》“人是一根能思想的苇草”；帕斯卡定律，制造机械计算器。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-090","t":"《玛纳斯》","cid":"09i","p":1,"kind":"作品","alias":["玛纳斯","玛纳斯史诗","玛纳斯奇"],"one":"柯尔克孜族英雄史诗，叙玛纳斯及其七代子孙事迹。","ans":"《玛纳斯》是**柯尔克孜族的英雄史诗**，主要流传于新疆柯尔克孜族聚居区，由**民间艺人（玛纳斯奇）口头演唱**代代相传。全诗共八部，以第一部主人公玛纳斯命名，叙述**玛纳斯及其七代子孙**为民族的自由和统一英勇奋战的故事，被视为柯尔克孜族生活的“百科全书”。著名演唱者**居素普·玛玛依**完整演唱了全部八部。史诗**2009年入选联合国教科文组织人类非物质文化遗产代表作名录**，与《格萨尔王传》《江格尔》并称**中国三大英雄史诗**。","pts":["柯尔克孜族英雄史诗，叙玛纳斯及七代子孙","玛纳斯奇口头演唱，居素普·玛玛依","2009年入选人类非遗，三大史诗之一"],"mem":"“一家八代打天下”：玛纳斯和七代子孙，共八部。人名挂钩：玛纳斯与演唱者居素普·玛玛依都带“玛”。民族挂钩：柯尔克孜族→玛纳斯，三大史诗里排最后。","mix":"《玛纳斯》属柯尔克孜族，不要与蒙古族《江格尔》、藏族《格萨尔王传》互换；吉尔吉斯斯坦也流传《玛纳斯》，吉尔吉斯与柯尔克孜是同一民族的不同汉译。","mcq":[{"q":"《玛纳斯》是哪个民族的英雄史诗","o":["哈萨克族","柯尔克孜族","蒙古族","藏族"],"a":1,"w":"《玛纳斯》属柯尔克孜族。"},{"q":"关于《玛纳斯》，下列说法正确的是","o":["讲述玛纳斯及其七代子孙的业绩","讲述岭国国王降妖伏魔","讲述宝木巴的保卫战","属于文人创作的长诗"],"a":0,"w":"岭国属《格萨尔》，宝木巴属《江格尔》。"}],"rel":[{"t":"中国三大英雄史诗","n":"三大史诗之一"},{"t":"《格萨尔王传》","n":"同为三大史诗"},{"t":"《江格尔》","n":"同为三大史诗"},{"t":"人类非遗代表作中国项目","n":"2009年入选"},{"t":"史诗","n":"所属体裁"}],"more":"2009年入选联合国教科文组织人类非物质文化遗产代表作名录。\n演唱者：居素普·玛玛依（完整演唱八部）。","exam":[]},{"id":"a09-091","t":"《江格尔》","cid":"09i","p":1,"kind":"作品","alias":["江格尔","江格尔汗","江格尔齐"],"one":"蒙古族卫拉特英雄史诗，江格尔汗与勇士保卫宝木巴。","ans":"《江格尔》是**蒙古族（卫拉特部）的英雄史诗**，主要流传于新疆的卫拉特蒙古人聚居区，也见于蒙古国和俄罗斯的卡尔梅克，由**被称为“江格尔齐”的民间艺人口头演唱**传承。史诗以**江格尔汗为首的勇士们保卫理想家园“宝木巴”**、抗击入侵之敌为主线，其中勇士洪古尔最为著名，歌颂团结、勇敢与对幸福乐土的追求。它与藏族《格萨尔王传》、柯尔克孜族《玛纳斯》并称**中国三大英雄史诗**，已列入国家级非物质文化遗产代表性项目名录。","pts":["蒙古族卫拉特英雄史诗，江格尔汗","勇士保卫理想家园宝木巴，洪古尔最著名","江格尔齐演唱，三大英雄史诗之一"],"mem":"三个关键词配成一句：江格尔汗坐镇“宝木巴”，演唱者叫“江格尔齐”。宝木巴相当于蒙古族的“理想国”，可与柏拉图《理想国》对照记。三大史诗对应：格萨尔—岭国，江格尔—宝木巴，玛纳斯—八代。","mix":"蒙古族另有《格斯尔》，是《格萨尔王传》在蒙古族中的版本，与卫拉特的《江格尔》不是一部；《玛纳斯》属柯尔克孜族。","mcq":[{"q":"《江格尔》中勇士们守卫的理想家园名叫","o":["岭国","桃花源","宝木巴","香巴拉"],"a":2,"w":"岭国属《格萨尔王传》。"},{"q":"《江格尔》的民间演唱艺人被称为","o":["玛纳斯奇","江格尔齐","阿肯","说书人"],"a":1,"w":"“齐”表示从事某事的人，江格尔齐即演唱《江格尔》的艺人。"}],"rel":[{"t":"中国三大英雄史诗","n":"三大史诗之一"},{"t":"《格萨尔王传》","n":"同为三大史诗"},{"t":"《玛纳斯》","n":"同为三大史诗"},{"t":"史诗","n":"所属体裁"},{"t":"《理想国》","n":"理想家园的中西对照"}],"more":"江格尔汗麾下有十二名雄狮大将，洪古尔最为著名。","exam":[]},{"id":"a09-092","t":"《吉尔伽美什》","cid":"09i","p":2,"kind":"作品","alias":["吉尔伽美什史诗","吉尔伽美什","吉尔迦美什"],"one":"两河流域史诗，现存最早的史诗之一，刻于泥板，含洪水故事。","ans":"《吉尔伽美什》是**古代两河流域（苏美尔—巴比伦）的史诗**，是**现存最早的史诗之一**，用**楔形文字刻在泥板上**，1853年起在尼尼微亚述巴尼拔图书馆遗址出土。全诗以乌鲁克国王吉尔伽美什为主人公，写他与好友**恩奇都**的友谊、恩奇都之死，以及他为寻求**永生**而远行。其中的**洪水故事**与《圣经》诺亚方舟相似。史诗反映人类对死亡和生命意义的思考，比荷马史诗早约一千多年。","pts":["两河流域，现存最早的史诗之一","楔形文字泥板，国王与恩奇都，求永生","洪水故事与《圣经》诺亚方舟相似"],"mem":"三个“最”和“泥”：最早、泥板、楔形文字。情节一句话：国王失去好友，去找永生，最后空手而归。洪水故事记“诺亚方舟的前身”。","mix":"它是民间流传、后经整理的史诗，不是荷马史诗；荷马史诗是西方文学源头，《吉尔伽美什》时间更早，但长期湮没，19世纪才重见天日。","mcq":[{"q":"含有与《圣经》诺亚方舟相似的洪水故事、被称为现存最早的史诗之一的是","o":["《吉尔伽美什》","《伊利亚特》","《摩诃婆罗多》","《贝奥武甫》"],"a":0,"w":"《吉尔伽美什》出自两河流域，刻于泥板。"}],"rel":[{"t":"楔形文字","n":"书写文字"},{"t":"两河流域","n":"产生地"},{"t":"《圣经》","n":"洪水故事相似"},{"t":"荷马史诗","n":"其后的希腊史诗"}],"exam":[]},{"id":"a09-093","t":"印度两大史诗","cid":"09i","p":1,"kind":"合称","alias":["《摩诃婆罗多》","《罗摩衍那》","摩诃婆罗多","罗摩衍那","薄伽梵歌"],"one":"古印度梵文史诗《摩诃婆罗多》与《罗摩衍那》。","ans":"印度两大史诗指古印度梵文史诗**《摩诃婆罗多》和《罗摩衍那》**。《摩诃婆罗多》相传为**毗耶娑**所作，以俱卢族与般度族争夺王位的大战为主线，篇幅浩大，是世界上最长的史诗之一，其中的**《薄伽梵歌》**是印度教的重要经典；《罗摩衍那》相传为**蚁垤**所作，讲述罗摩被放逐、妻子悉多被罗刹王罗波那劫走、罗摩在神猴哈奴曼帮助下救回悉多的故事。两部史诗是**古代印度文化的百科全书**，影响南亚、东南亚的文学艺术，**胡适等人认为哈奴曼影响了孙悟空形象**。","pts":["《摩诃婆罗多》（毗耶娑，含《薄伽梵歌》）与《罗摩衍那》（蚁垤）","前者写俱卢族与般度族大战，后者写罗摩救妻悉多","哈奴曼与孙悟空的关系：胡适主此说"],"members":[["《摩诃婆罗多》","相传毗耶娑作；俱卢族与般度族大战；含《薄伽梵歌》"],["《罗摩衍那》","相传蚁垤作；罗摩救妻悉多；神猴哈奴曼"]],"mem":"一部“大战”，一部“救妻”：《摩诃婆罗多》=两族打仗争王位（还包着一篇《薄伽梵歌》），《罗摩衍那》=罗摩去救被抢的妻子悉多。“衍那”意为行程，可记成“罗摩的旅程”。神猴哈奴曼一路相助，对应《西游记》里的孙悟空。","mix":"孙悟空原型有分歧：胡适主张来自哈奴曼（《罗摩衍那》），鲁迅则疑其源于中国的水怪无支祁；印度两大史诗与荷马史诗、《吉尔伽美什》分属不同文明。","mcq":[{"q":"《摩诃婆罗多》中包含的著名宗教哲学篇章是","o":["《奥义书》","《薄伽梵歌》","《吠陀》","《法华经》"],"a":1,"w":"《薄伽梵歌》出自《摩诃婆罗多》，是印度教重要经典。"},{"q":"胡适等人认为孙悟空形象受《罗摩衍那》中哪个角色影响","o":["罗摩","悉多","罗波那","哈奴曼"],"a":3,"w":"神猴哈奴曼助罗摩救出悉多。"}],"rel":[{"t":"史诗","n":"所属体裁"},{"t":"荷马史诗","n":"中印史诗源头对照"},{"t":"《西游记》","n":"孙悟空原型之争"},{"t":"胡适","n":"哈奴曼说"},{"t":"印度教","n":"《薄伽梵歌》是其经典"}],"more":"《摩诃婆罗多》：十万颂左右，含《薄伽梵歌》。\n《罗摩衍那》：七篇，主角罗摩、悉多、哈奴曼。","exam":[]},{"id":"a09-094","t":"中世纪欧洲英雄史诗","cid":"09i","p":2,"kind":"合称","alias":["欧洲中世纪英雄史诗","中世纪英雄史诗","欧洲五大英雄史诗"],"one":"英国《贝奥武甫》、法国《罗兰之歌》、德国《尼伯龙根之歌》、西班牙《熙德之歌》、古罗斯《伊戈尔远征记》。","ans":"中世纪欧洲英雄史诗指**中世纪欧洲各民族以本民族英雄为主人公的史诗**，通行的五部是英国**《贝奥武甫》**、法国**《罗兰之歌》**、德国**《尼伯龙根之歌》**、西班牙**《熙德之歌》**和古罗斯**《伊戈尔远征记》**。它们多由民间口头传说发展而来，后由文人记录整理，用各民族语言写成。内容反映**封建骑士时代**的战争、忠诚和荣誉，也体现民族意识的形成，是欧洲各国民族文学的源头。","pts":["五部：英、法、德、西、古罗斯","贝奥武甫、罗兰之歌、尼伯龙根之歌、熙德之歌、伊戈尔远征记","封建时代英雄，各民族文学源头"],"members":[["《贝奥武甫》","英国，古英语，最早的古英语长诗"],["《罗兰之歌》","法国，罗兰在龙塞斯瓦列斯战死"],["《尼伯龙根之歌》","德国，齐格弗里德与复仇"],["《熙德之歌》","西班牙，抗击摩尔人的英雄熙德"],["《伊戈尔远征记》","古罗斯，伊戈尔远征波洛伏齐人"]],"mem":"国名顺序“英法德西俄”配书名首字“贝罗尼熙伊”：英贝、法罗、德尼、西熙、俄伊。画面：一路向东：英国、法国、德国、西班牙（回头看）、古罗斯。","mix":"《吉尔伽美什》是上古史诗，荷马史诗是古希腊史诗，《埃涅阿斯纪》是罗马文人史诗，都不属于中世纪欧洲英雄史诗；《格萨尔王传》等则是中国史诗。","mcq":[{"q":"下列史诗中，不属于中世纪欧洲英雄史诗的是","o":["《罗兰之歌》","《熙德之歌》","《贝奥武甫》","《奥德赛》"],"a":3,"w":"《奥德赛》是古希腊荷马史诗。"}],"rel":[{"t":"《贝奥武甫》","n":"英国成员"},{"t":"《罗兰之歌》","n":"法国成员"},{"t":"《尼伯龙根之歌》","n":"德国成员"},{"t":"《熙德之歌》","n":"西班牙成员"},{"t":"《伊戈尔远征记》","n":"古罗斯成员"}],"exam":[]},{"id":"a09-095","t":"《贝奥武甫》","cid":"09i","p":2,"kind":"作品","alias":["贝奥武夫","贝奥武甫","Beowulf"],"one":"现存最早的古英语长诗，英雄贝奥武甫斩怪屠龙。","ans":"《贝奥武甫》是**英国的英雄史诗**，用**古英语**写成，是**现存最早的古英语长诗**，作者不详，约成于8至11世纪，手稿约抄于公元1000年。全诗约三千余行，讲述**耶阿特族英雄贝奥武甫**为丹麦国王驱除食人怪物**格伦德尔**及其母亲，晚年又为保卫国家与**火龙**搏斗，最终同归于尽。诗中结合日耳曼英雄传统与基督教色彩，是**中世纪欧洲英雄史诗**之一，也是英国文学的开端。","pts":["现存最早的古英语长诗，作者不详","贝奥武甫斩格伦德尔，晚年斗火龙","英国文学开端，中世纪英雄史诗"],"mem":"一生三战：怪物格伦德尔，怪物的母亲，火龙，前两战在青年，最后一战在晚年。国名配书名首字：英国贝奥武甫。","mix":"故事发生在斯堪的纳维亚，不是英格兰；《罗兰之歌》是法国，《尼伯龙根之歌》是德国。","mcq":[{"q":"现存最早的古英语长诗是","o":["《罗兰之歌》","《熙德之歌》","《贝奥武甫》","《尼伯龙根之歌》"],"a":2,"w":"《贝奥武甫》是古英语英雄史诗；其余分别属法、西、德。"}],"rel":[{"t":"中世纪欧洲英雄史诗","n":"所属合称"},{"t":"《罗兰之歌》","n":"同类史诗"},{"t":"《吉尔伽美什》","n":"同为英雄斗怪的古代史诗"}],"exam":[]},{"id":"a09-096","t":"《罗兰之歌》","cid":"09i","p":2,"kind":"作品","alias":["罗兰之歌","Chanson de Roland"],"one":"法国中世纪英雄史诗，写查理曼外甥罗兰在龙塞斯瓦列斯战死。","ans":"《罗兰之歌》是**法国中世纪的英雄史诗**，用古法语写成，约在11世纪末定型，作者不详。故事取材于**778年查理曼大帝远征西班牙后撤军途中，后卫部队在龙塞斯瓦列斯山谷遭伏击**的史实。诗中主人公**罗兰是查理曼的外甥**，他为保卫基督教世界英勇战死，**查理曼为其复仇**。诗中把敌人写成撒拉森人，带有浓厚的宗教色彩和**封建忠君观念**，是法国民族文学的开端，也是中世纪欧洲英雄史诗代表。","pts":["法国古法语英雄史诗","罗兰在龙塞斯瓦列斯山谷战死","查理曼外甥，忠君与基督教色彩"],"mem":"一句话：外甥为舅舅断后，战死山谷。记“罗兰（法）＝龙塞斯瓦列斯＝查理曼”。国名配书名：法国罗兰。","mix":"史实中伏击者是巴斯克人，诗中改成撒拉森人；“罗兰”也可能让人想到罗曼·罗兰，那是法国作家，与史诗无关。","mcq":[{"q":"《罗兰之歌》写的主人公罗兰是谁的外甥","o":["亚瑟王","查理曼大帝","熙德","齐格弗里德"],"a":1,"w":"罗兰是查理曼大帝的外甥。"}],"rel":[{"t":"中世纪欧洲英雄史诗","n":"所属合称"},{"t":"查理曼帝国","n":"故事背景"},{"t":"《贝奥武甫》","n":"同类史诗"},{"t":"罗曼·罗兰","n":"名字易混"}],"exam":[]},{"id":"a09-097","t":"《尼伯龙根之歌》","cid":"09i","p":3,"kind":"作品","exam":[],"alias":[],"one":"德国中世纪英雄史诗，齐格弗里德与克里姆希尔特的故事；瓦格纳歌剧《尼伯龙根的指","ans":"德国中世纪英雄史诗，齐格弗里德与克里姆希尔特的故事；瓦格纳歌剧《尼伯龙根的指环》取材于相关传说。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-098","t":"《熙德之歌》","cid":"09i","p":3,"kind":"作品","exam":[],"alias":[],"one":"西班牙英雄史诗，写抗击摩尔人的英雄熙德；高乃依悲剧《熙德》取材于同一人物。","ans":"西班牙英雄史诗，写抗击摩尔人的英雄熙德；高乃依悲剧《熙德》取材于同一人物。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-099","t":"《伊戈尔远征记》","cid":"09i","p":3,"kind":"作品","exam":[],"alias":[],"one":"古罗斯英雄史诗，写1185年伊戈尔大公远征波洛伏齐人失败。","ans":"古罗斯英雄史诗，写1185年伊戈尔大公远征波洛伏齐人失败。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a09-100","t":"民间史诗与文人史诗","cid":"09i","p":2,"kind":"概念","alias":["民间史诗","文人史诗","创世史诗","英雄史诗","口头史诗"],"one":"按作者与流传方式分：民间史诗口头集体创作，文人史诗由作家创作。","ans":"史诗是**叙述民族历史、英雄事迹或创世神话的长篇叙事诗**，按创作方式分为**民间史诗**和**文人史诗**。民间史诗口头流传，经集体创作和艺人传唱，后来才被整理成文，如**荷马史诗**和中国三大英雄史诗《格萨尔王传》《江格尔》《玛纳斯》。文人史诗由**作家个人创作**，如**维吉尔《埃涅阿斯纪》**和弥尔顿《失乐园》。按内容又可分**创世史诗**和**英雄史诗**，前者讲天地人类起源，后者讲英雄业绩。","pts":["民间史诗：口头流传、集体创作","文人史诗：作家个人创作","按内容分创世史诗与英雄史诗"],"mem":"一句话分法：谁写的？民间的是“唱出来的”（荷马、格萨尔），文人的是“写出来的”（维吉尔、弥尔顿）。内容分法：创世讲“从哪来”，英雄讲“谁最强”。","mix":"荷马史诗虽署名荷马，学界多认为它是口头传统的集体积累，归民间史诗；《神曲》常被称为长诗，一般不放进“史诗”考点里。","mcq":[{"q":"下列作品中，属于文人史诗的是","o":["《伊利亚特》","《格萨尔王传》","《埃涅阿斯纪》","《江格尔》"],"a":2,"w":"《埃涅阿斯纪》由维吉尔个人创作；其余都是民间史诗。"}],"rel":[{"t":"史诗","n":"上位概念"},{"t":"荷马史诗","n":"民间史诗代表"},{"t":"《埃涅阿斯纪》","n":"文人史诗代表"},{"t":"中国三大英雄史诗","n":"民间史诗代表"}],"exam":[]},{"id":"a09-101","t":"《卡勒瓦拉》","cid":"09i","p":3,"kind":"作品","exam":[],"alias":[],"one":"芬兰民族史诗，19世纪伦洛特搜集整理。","ans":"芬兰民族史诗，19世纪伦洛特搜集整理。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"z80-002","t":"埃斯库罗斯","cid":"09d","p":1,"kind":"人物","alias":["艾斯奇勒斯","悲剧之父"],"one":"古希腊“悲剧之父”，著《被缚的普罗米修斯》《俄瑞斯忒亚》。","ans":"埃斯库罗斯（约前525—前456）是**古希腊雅典的悲剧诗人，被称为“悲剧之父”**，与索福克勒斯、欧里庇得斯并称**古希腊三大悲剧家**。据说他在悲剧中增加了第二个演员，使戏剧冲突得以展开。他现存作品7部，代表作有**《被缚的普罗米修斯》**和**《俄瑞斯忒亚》三部曲**（含《阿伽门农》《奠酒人》《复仇女神》），另有《波斯人》。他的悲剧题材庄严，多写神意与人的命运、正义与复仇，**奠定了欧洲悲剧的基础**。","pts":["古希腊悲剧之父，三大悲剧家之一","《被缚的普罗米修斯》《俄瑞斯忒亚》三部曲","增加第二演员，奠定欧洲悲剧基础"],"mem":"三大悲剧家按年龄排“埃索欧”，自编概括“神意→命运→人性”：埃斯库罗斯写神意与正义，索福克勒斯写命运（《俄狄浦斯王》），欧里庇得斯写人性与心理（《美狄亚》）。“父”字记忆：他最年长，开创悲剧，故称“悲剧之父”。","mix":"《俄狄浦斯王》《安提戈涅》属索福克勒斯，《美狄亚》属欧里庇得斯；阿里斯托芬是“喜剧之父”；《被缚的普罗米修斯》的作者归属，个别学者有存疑，通行归埃斯库罗斯。","mcq":[{"q":"《被缚的普罗米修斯》的作者是","o":["索福克勒斯","欧里庇得斯","埃斯库罗斯","阿里斯托芬"],"a":2,"w":"埃斯库罗斯，“悲剧之父”。"},{"q":"被称为“悲剧之父”的是","o":["埃斯库罗斯","索福克勒斯","欧里庇得斯","阿里斯托芬"],"a":0,"w":"阿里斯托芬是“喜剧之父”。"}],"rel":[{"t":"古希腊三大悲剧家","n":"三大家之首"},{"t":"普罗米修斯","n":"代表作主人公"},{"t":"《俄狄浦斯王》","n":"索福克勒斯名作"},{"t":"狄俄尼索斯（酒神）","n":"悲剧起源于酒神祭祀"},{"t":"世界三大古老戏剧","n":"古希腊戏剧"}],"more":"作品：《波斯人》｜《七将攻忒拜》｜《乞援人》｜《被缚的普罗米修斯》｜《俄瑞斯忒亚》三部曲（《阿伽门农》《奠酒人》《复仇女神》）","exam":[]},{"id":"z80-003","t":"索福克勒斯","cid":"09d","p":2,"kind":"人物","alias":["索福克勒斯","Sophocles","《俄狄浦斯王》作者"],"one":"古希腊悲剧家，《俄狄浦斯王》《安提戈涅》，命运悲剧代表。","ans":"索福克勒斯（约前496–前406）是**古希腊雅典的悲剧家**，与埃斯库罗斯、欧里庇得斯并称**古希腊三大悲剧家**。代表作有**《俄狄浦斯王》**和**《安提戈涅》**，前者写俄狄浦斯在命运摆布下杀父娶母，是典型的**命运悲剧**；后者写安提戈涅为埋葬兄长而违抗国法。他把戏剧演员增加到三人，并使剧情更加紧凑，被誉为**“戏剧艺术的荷马”**。亚里士多德《诗学》以《俄狄浦斯王》为悲剧典范，弗洛伊德借此提出“俄狄浦斯情结”。","pts":["约前496–前406，古希腊悲剧家","《俄狄浦斯王》《安提戈涅》，命运悲剧","戏剧艺术的荷马，《诗学》以其为典范"],"mem":"三大悲剧家按顺序记“埃索欧”：埃斯库罗斯（悲剧之父）、索福克勒斯（命运）、欧里庇得斯（人性）。索福克勒斯＝俄狄浦斯＋安提戈涅，记“索俄安”。","mix":"“俄狄浦斯情结”是弗洛伊德借用的术语，不是索福克勒斯提出；“悲剧之父”是埃斯库罗斯，不是索福克勒斯。","mcq":[{"q":"《俄狄浦斯王》的作者是","o":["埃斯库罗斯","欧里庇得斯","阿里斯托芬","索福克勒斯"],"a":3,"w":"索福克勒斯，《诗学》以其为悲剧典范。"}],"rel":[{"t":"古希腊三大悲剧家","n":"所属合称"},{"t":"《俄狄浦斯王》","n":"代表作"},{"t":"《诗学》","n":"以其为典范"},{"t":"弗洛伊德与精神分析","n":"借用俄狄浦斯"}],"exam":[]},{"id":"z80-004","t":"欧里庇得斯","cid":"09d","p":2,"kind":"人物","alias":["欧里庇德斯","Euripides","《美狄亚》作者"],"one":"古希腊悲剧家，“舞台上的哲学家”，《美狄亚》《特洛伊妇女》。","ans":"欧里庇得斯（约前480–前406）是**古希腊雅典的悲剧家**，与埃斯库罗斯、索福克勒斯并称**三大悲剧家**，被称为**“舞台上的哲学家”**。代表作有**《美狄亚》**和**《特洛伊妇女》**，前者写被丈夫抛弃的美狄亚杀子复仇，后者写特洛伊陷落后妇女的命运。他的悲剧**关注普通人、女性心理和现实问题**，对传统神灵持怀疑态度，更重人物内心冲突。他的写法对后世**新喜剧和近代戏剧**影响很大，亚里士多德称他为“最悲剧的诗人”。","pts":["约前480–前406，三大悲剧家之一","《美狄亚》《特洛伊妇女》","关注人和女性心理，舞台上的哲学家"],"mem":"三大悲剧家递进：埃斯库罗斯写神，索福克勒斯写英雄，欧里庇得斯写“人”。名字记“欧”字尾，作品《美狄亚》是女人复仇，《特洛伊妇女》是战后女人。","mix":"美狄亚的故事出自伊阿宋取金羊毛神话，欧里庇得斯改写了结局；他生前获奖不多，死后声誉日隆。","mcq":[{"q":"被称为“舞台上的哲学家”的古希腊悲剧家是","o":["索福克勒斯","欧里庇得斯","阿里斯托芬","埃斯库罗斯"],"a":1,"w":"欧里庇得斯，代表作《美狄亚》。"}],"rel":[{"t":"古希腊三大悲剧家","n":"所属合称"},{"t":"《美狄亚》","n":"代表作"},{"t":"索福克勒斯","n":"同代悲剧家"},{"t":"米南德与新喜剧","n":"影响了新喜剧"}],"exam":[]}],"tables":[{"name":"古希腊人物速查","note":"","rows":[["人物","身份","关键词与代表作"],["荷马","相传的盲诗人","《伊利亚特》《奥德赛》"],["赫西俄德","诗人","《神谱》《工作与时日》"],["希罗多德","史学家，“历史之父”","《历史》（《希波战争史》）"],["修昔底德","史学家，雅典将军","《伯罗奔尼撒战争史》"],["泰勒斯","“哲学之父”，米利都学派","水是万物本原"],["毕达哥拉斯","哲学家、数学家","数是万物本原，勾股定理（西方称毕达哥拉斯定理）"],["赫拉克利特","以弗所哲学家","火是万物本原，“人不能两次踏进同一条河流”，逻各斯"],["德谟克利特","哲学家","原子论"],["苏格拉底","哲学家，无著作","“认识你自己”，“美德即知识”，助产术"],["柏拉图","苏格拉底弟子，创阿卡德米学园","《理想国》，理念论，洞穴比喻"],["亚里士多德","柏拉图弟子，亚历山大之师，创吕克昂学园","《诗学》《政治学》《形而上学》《尼各马可伦理学》"],["埃斯库罗斯","“悲剧之父”","《俄瑞斯忒亚》三部曲、《被缚的普罗米修斯》"],["索福克勒斯","悲剧家","《俄狄浦斯王》《安提戈涅》"],["欧里庇得斯","悲剧家，“舞台上的哲学家”","《美狄亚》《特洛伊妇女》"],["阿里斯托芬","“喜剧之父”","《鸟》《蛙》《云》"],["伊索","寓言作家","《伊索寓言》"],["希波克拉底","“医学之父”","希波克拉底誓言"],["欧几里得","数学家","《几何原本》（明末利玛窦、徐光启译前六卷）"],["阿基米德","数学家、物理学家","浮力定律、杠杆原理"]]},{"name":"两位史家与两场战争","note":"","rows":[["史家","著作","记述的战争","交战双方","方法特点"],["希罗多德","《历史》","希波战争（前5世纪前期）","希腊城邦对波斯帝国","实地考察、广采传闻，兼记各地风俗地理"],["修昔底德","《伯罗奔尼撒战争史》","伯罗奔尼撒战争（前431—前404）","雅典（提洛同盟）对斯巴达（伯罗奔尼撒同盟）","核实史料、分析因果，排除神意"]]},{"name":"中外史诗速查","note":"","rows":[["史诗","民族/国别","要点"],["《吉尔伽美什》","古代两河流域（苏美尔—巴比伦）","现存最早的史诗之一，刻于泥板，有洪水故事"],["《伊利亚特》《奥德赛》","古希腊","荷马史诗，西方文学源头"],["《摩诃婆罗多》《罗摩衍那》","古印度","印度两大史诗，前者含《薄伽梵歌》"],["《埃涅阿斯纪》","古罗马","维吉尔所作文人史诗"],["《贝奥武甫》","英国（古英语）","现存最早的古英语长诗"],["《罗兰之歌》","法国","中世纪英雄史诗"],["《尼伯龙根之歌》","德国","中世纪英雄史诗"],["《熙德之歌》","西班牙","中世纪英雄史诗"],["《伊戈尔远征记》","古罗斯","中世纪英雄史诗"],["《格萨尔王传》《江格尔》《玛纳斯》","中国藏族、蒙古族、柯尔克孜族","中国三大英雄史诗，均已入选国家级非遗"]]}]});